INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000028', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-001', 'tense', 'Hingga Mencapai Titik Kritis (~に至って)', '[Nomina / Kamus Verba] + に至って（にいたって）', 'Menegaskan pencapaian suatu tahap ekstrem setelah melalui proses panjang.', 1, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Hingga situasi memburuk barulah langkah penanganan diambil.","jp":"事態が 悪化するに至って、ようやく 対策が 取られた。","reading":"Jitai ga akka suru ni itatte, youyaku taisaku ga torareta."},{"id":"Jika sudah sampai tahap ini, arah kebijakan tak dapat diubah.","jp":"この 段階に至っては、方針を 変えられない。","reading":"Kono dankai ni itatte wa, houshin o kaerarenai."}]'::jsonb, '[Nomina / Kamus Verba] + ni itatte', '{"quiz":[{"why":"Peringatan berkali-kali yang berujung penutupan toko mencerminkan klimaks situasi serius.","answer":1,"options":["あさ おきる に至って、みずを のみました","なんども けいこくされたが、ついに へいてんする に至った","あした とうきょうへ いく に至って、たのしみだ","この ケーキは おいしい に至って やすい"],"question":"Kalimat mana yang memakai ～に至って secara PALING TEPAT?"},{"why":"ここ 至って menyoroti situasi yang sudah menumpuk hingga tahap puncak / terlambat.","answer":1,"options":["Masih sangat awal sebelum mulai","Sudah sampai di tahap genting atau sudah terlambat barulah bereaksi","Kegiatan rutin setiap hari","Rencana liburan menyenangkan"],"question":"Apa nuansa ungkapan ''ここ に 至って（ようやく）''?"},{"why":"Bentuk kamus 至る memodifikasi nomina di belakangnya (''jalan menuju kesuksesan'').","answer":0,"options":["に至る","に至って","に至っては","に至っても"],"question":"Jika diletakkan sebelum kata benda ''成功（せいこう = kesuksesan） ___ 道（みち = jalan）'', bentuknya adalah:"}],"forms":[{"id":"baru pada titik inilah...","jp":"ここに至ってはじめて","label":"Baru Sadar","reading":"koko ni itatte hajimete"},{"id":"kalau sudah sampai begini...","jp":"ここに至っては","label":"Sudah Kelewatan","reading":"koko ni itatte wa"},{"id":"penyebab yang berujung kecelakaan","jp":"じこに至る原因","label":"Berujung pada (Menerangkan)","reading":"jiko ni itaru gen''in"}],"steps":["Siapkan peristiwa atau kondisi ekstrem sebagai puncaknya (misal: じたいの あっか = memburuknya keadaan, しゅじゅつ = harus dioperasi).","Tambahkan に至って (atau に至ってはじめて = baru pada tahap itulah..., に至っては = kalau sudah sampai segitunya maka...).","Selesaikan dengan hasil berat yang akhirnya muncul atau kesadaran yang terlambat."],"analogy":"～に至って (ni itatte) artinya ''Hingga akhirnya sampai di titik kritis ini...'' atau ''Baru sekarang ketika keadaannya sudah terlanjur begini...''. Dipakai ketika sesuatu sudah berjalan jauh sampai tahap ekstrem atau terlambat.","mistakes":[{"why":"Jangan dipakai untuk aktivitas ringan sehari-hari; ～に至って hanya untuk titik puncak situasi serius/ekstrem setelah proses panjang.","right":"スーパーへ いって、パンを かった","wrong":"スーパーへ いく に至って、パンを かった"},{"why":"Bila memakai kata kerja, bentuknya wajib Bentuk Kamus (する), bukan lampau.","right":"しっぱい する に至って","wrong":"しっぱい した に至って"}],"breakdowns":[{"tokens":[{"jp":"ここ","role":"place","meaning":"titik ini","reading":"koko"},{"jp":"に至って","role":"connector","meaning":"hingga sampai di","reading":"ni itatte"},{"jp":"ようやく","role":"time","meaning":"akhirnya baru","reading":"youyaku"},{"jp":"きがつきました","role":"verb","meaning":"saya menyadari","reading":"ki ga tsukimashita"}],"translation":"Setelah sampai di titik ini, barulah saya menyadari."},{"tokens":[{"jp":"びょうき","role":"subject","meaning":"penyakit","reading":"byouki"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"悪化する","role":"verb","meaning":"memburuk (kamus)","reading":"akka suru"},{"jp":"に至って","role":"connector","meaning":"hingga mencapai tahap","reading":"ni itatte"},{"jp":"病院","role":"place","meaning":"rumah sakit","reading":"byouin"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"いった","role":"verb","meaning":"pergi","reading":"itta"}],"translation":"Baru setelah penyakitnya parah memburuk, ia akhirnya pergi ke rumah sakit."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"段階","role":"noun","meaning":"tahap","reading":"dankai"},{"jp":"に至っては","role":"connector","meaning":"kalau sudah sampai tahap ini","reading":"ni itatte wa"},{"jp":"もう","role":"time","meaning":"sudah tidak","reading":"mou"},{"jp":"ひきかえせない","role":"verb","meaning":"bisa mundur lagi","reading":"hikikaesenai"}],"translation":"Jika sudah sampai pada tahap seperti ini, kita tidak bisa mundur lagi."}],"when_to_use":["Menggambarkan krisis atau konflik yang memuncak setelah lama dibiarkan (''hingga akhirnya perang pecah / pasien pingsan baru sadar'')","Artikel berita, novel, atau pidato resmi mengenai pencapaian tahap puncak","Bila dikombinasi dengan はじめて (''baru di titik inilah menyadari...'')"],"formula_parts":[{"role":"time","text":"Nomina / Kamus Verba","label":"Titik kritis / Tahap akhir"},{"role":"connector","text":"に至って / に至っては","label":"Hingga sampai titik..."},{"role":"predicate","text":"Konsekuensi Serius","label":"Reaksi atau kesadaran terlambat"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000029', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-002', 'sentence_pattern', 'Terpaksa Oleh Keadaan Luar (~を余儀なくされる)', '[Nomina] + を余儀なくされる（をよぎなくされる）', 'Bentuk resmi bahwa suatu pihak tidak punya pilihan lain selain menerima keputusan berat karena desakan eksternal.', 2, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Akibat revisi hukum, perusahaan terpaksa mengubah strukturnya.","jp":"法改正により、企業は 体制の 変更を 余儀なくされた。","reading":"Houkaisei ni yori, kigyou wa taisei no henkou o yoginaku sareta."},{"id":"Karena cuaca buruk, penyusutan rencana terpaksa dilakukan.","jp":"悪天候のため、計画の 縮小を 余儀なくされている。","reading":"Akutenkou no tame, keikaku no shukushou o yoginaku sarete iru."}]'::jsonb, '[Nomina] + o yoginaku sareru', '{"quiz":[{"why":"Di depan を余儀なくされる wajib langsung berupa Nomina (kata benda) tanpa する.","answer":0,"options":["閉鎖（へいさ = penutupan）","閉鎖する","閉鎖した","閉鎖して"],"question":"Lengkapi kutipan koran ''工場は 経営悪化（けいえいあっか = memburuknya bisnis）により、___ を余儀なくされた'' (terpaksa melakukan pemangkasan):"},{"why":"余儀 dibaca よぎ (yogi) dengan dakuten pada gi.","answer":1,"options":["o yoki naku sareru","o yogi naku sareru","o amari gi naku","o yougi naku sareru"],"question":"Bagaimana bacaan huruf Kanji ''を余儀なくされる''?"},{"why":"Maknanya secara harfiah adalah ''dibuat tidak punya ruang pilihan lain oleh keadaan''.","answer":1,"options":["Keinginan sukarela dari dalam hati","Desakan keadaan berat dari luar sehingga tidak ada pilihan lain","Nasihat santai dari teman dekat","Hobi di waktu senggang"],"question":"Siapa atau apa pendorong tindakan dalam kalimat ～を余儀なくされる?"}],"forms":[{"id":"terpaksa dibatalkan","jp":"ちゅうしを余儀なくされた","label":"Lampau (Terpaksa)","reading":"chuushi o yogi naku sareta"},{"id":"masih terpaksa menunggu","jp":"たいきを余儀なくされている","label":"Masih Berlangsung","reading":"taiki o yogi naku sarete iru"},{"id":"memaksanya harus mundur","jp":"てったいを余儀なくさせた","label":"Bentuk Kausatif (Memaksa)","reading":"tettai o yogi naku saseta"}],"steps":["Pilih kata benda yang bermakna tindakan (biasanya kata benda berpasangan 2 kanji seperti ちゅうし = pembatalan, へいさ = penutupan, へんこう = perubahan, ひなん = pengungsian).","Tempelkan langsung を余儀なくされる di belakang kata benda tersebut (sudah bentuk pasif!).","Kalau pihak lain yang MEMAKSA (''memaksa mereka menutup toko''), akhiran aktifnya adalah ～を余儀なくさせる."],"analogy":"～を余儀なくされる artinya ''Terpaksa tidak punya pilihan lain karena tekanan keadaan luar'' — lebih berat dan formal lagi dari ～ざるを得ない. Biasanya perusahaan, pemerintah, atau publik yang ''dipaksa keadaan'' mundur atau berubah.","mistakes":[{"why":"Tidak boleh memakai kata kerja langsung; ambil KATA BENDA aksinya saja (する dibuang) sebelum を余儀なくされる.","right":"へんこう を余儀なくされた","wrong":"へんこうする を余儀なくされた"},{"why":"余儀なくされる adalah ungkapan berita/tulisan super resmi untuk situasi berat eksternal, jangan dipakai untuk hal sepele seperti mengantuk.","right":"ねむくて ねてしまった / やむをえず ねた","wrong":"ねむいから ねるを余儀なくされた"}],"breakdowns":[{"tokens":[{"jp":"おおゆき","role":"noun","meaning":"salju lebat","reading":"ooyuki"},{"jp":"で","role":"particle","meaning":"akibat","reading":"de"},{"jp":"けいかく","role":"noun","meaning":"rencana","reading":"keikaku"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"へんこう","role":"object","meaning":"perubahan","reading":"henkou"},{"jp":"を余儀なくされた","role":"verb","meaning":"terpaksa harus (oleh keadaan)","reading":"o yogi naku sareta"}],"translation":"Akibat salju lebat, kami terpaksa mengubah rencana."},{"tokens":[{"jp":"あのかいしゃ","role":"topic","meaning":"perusahaan itu","reading":"ano kaisha"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"へいてん","role":"object","meaning":"penutupan toko","reading":"heiten"},{"jp":"を余儀なくされました","role":"verb","meaning":"terpaksa harus","reading":"o yogi naku saremashita"}],"translation":"Perusahaan itu terpaksa harus menutup tokonya."},{"tokens":[{"jp":"おおぜいの","role":"adjective","meaning":"banyak","reading":"oozei no"},{"jp":"じゅうみん","role":"topic","meaning":"warga","reading":"juumin"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ひなん","role":"object","meaning":"evakuasi / mengungsi","reading":"hinan"},{"jp":"を余儀なくされている","role":"verb","meaning":"terpaksa harus menjalani","reading":"o yogi naku sarete iru"}],"translation":"Banyak warga terpaksa harus mengungsi akibat kondisi saat ini."}],"when_to_use":["Berita bencana alam atau ekonomi yang memaksa warga mengungsi atau perusahaan tutup","Laporan resmi tentang penundaan proyek akibat regulasi atau kondisi eksternal berat","Menjelaskan pengorbanan berat yang sama sekali tidak bisa dihindari"],"formula_parts":[{"role":"noun","text":"Nomina (Tindakan Aksi)","label":"Keputusan berat"},{"role":"verb","text":"を余儀なくされる","label":"Dipaksa keadaan untuk..."}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000030', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-003', 'sentence_pattern', 'Meskipun Memang Demikian (~とはいえ)', '[Nomina / Bentuk Biasa] + とはいえ', 'Mengakui suatu fakta secara formal namun menyoroti kenyataan yang berlawanan di klausa berikutnya.', 3, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Meski sudah masuk musim semi, pagi dan malam masih terasa dingin.","jp":"春になったとはいえ、朝晩は まだ 肌寒い。","reading":"Haru ni natta to wa ie, asaban wa mada hadazamui."},{"id":"Walaupun berskala kecil, makna penelitian itu sangat besar.","jp":"小規模とはいえ、その 研究の 意義は 大きい。","reading":"Shoukibo to wa ie, sono kenkyuu no igi wa ookii."}]'::jsonb, '[Nomina / Bentuk Biasa] + to wa ie', '{"quiz":[{"why":"Sifat-Na (じょうず) langsung ditempeli とはいえ tanpa な.","answer":1,"options":["な とはいえ","とはいえ","での とはいえ","て とはいえ"],"question":"Lengkapi: ''りょうりが じょうず ___、プロのように きれいには 作れない'' (Memang jago masak sih, tapi tetap tidak secantik koki profesional):"},{"why":"いえ tetap mempertahankan makna ''meski mengakui pernyataan sebelumnya, ada sisi lain yang perlu diingat''.","answer":1,"options":["Dengan kata lain...","Meskipun begitu / Namun demikian...","Sebagai kesimpulan akhir...","Sebaliknya total..."],"question":"Apa arti kata penghubung ''とはいえ'' jika diletakkan sendirian di awal paragraf kedua?"},{"why":"Mengakui prestasi nyata (lulus N1) namun jujur tetap ada kelemahan (percakapan masih susah).","answer":0,"options":["N1に うかった とはいえ、まだ かいわは にがてだ","あさ おきた とはいえ、ねむかった","コーヒーを のんだ とはいえ、おいしかった","あした とはいえ、きょうだ"],"question":"Manakah contoh yang paling cocok memakai ～とはいえ?"}],"forms":[{"id":"meski masih anak-anak sih, tapi...","jp":"こども とはいえ","label":"Kata Benda","reading":"kodomo to wa ie"},{"id":"memang sudah lulus sih, namun...","jp":"ごうかくした とはいえ","label":"Verba","reading":"goukaku shita to wa ie"},{"id":"Namun demikian, ...","jp":"とはいえ","label":"Di Awal Kalimat","reading":"to wa ie"}],"steps":["Sebutkan fakta yang memang benar (misal: はる = musim semi, やすみ = hari libur, かった = menang).","Sambungkan langsung dengan とはいえ (untuk Kata Benda dan Sifat-Na, boleh langsung tempel atau memakai だ, misalnya はる とはいえ / はるだ とはいえ).","Tambahkan fakta nyata yang agak bertolak belakang atau perlu diperhatikan."],"analogy":"～とはいえ artinya ''Meskipun memang benar begitu adanya, tapi kenyataannya...''. Mirip ungkapan Indonesia ''Memang sih sudah [A], tapi tetap saja [B]!''.","mistakes":[{"why":"Sebelum とはいえ jangan memakai な; pakai Nomina polos langsung atau Nomina + だ.","right":"きょうは にちようび（だ） とはいえ","wrong":"きょうは にちようび な とはいえ"},{"why":"Kalimat di belakang とはいえ harus membelokkan/mengimbangi fakta awal, bukan menguatkan searah.","right":"かれは 社長 とはいえ、しっぱいすることも ある","wrong":"かれは 社長 とはいえ、会社で いちばん えらい"}],"breakdowns":[{"tokens":[{"jp":"はる","role":"time","meaning":"musim semi","reading":"haru"},{"jp":"とはいえ","role":"connector","meaning":"memang sih..., tapi","reading":"to wa ie"},{"jp":"まだ","role":"time","meaning":"masih","reading":"mada"},{"jp":"さむい","role":"adjective","meaning":"dingin","reading":"samui"},{"jp":"ひ","role":"noun","meaning":"hari","reading":"hi"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"つづいています","role":"verb","meaning":"terus berlanjut","reading":"tsuzuite imasu"}],"translation":"Meskipun secara kalender sudah musim semi, hari-hari dingin masih berlanjut."},{"tokens":[{"jp":"やすみ","role":"noun","meaning":"hari libur","reading":"yasumi"},{"jp":"とはいえ","role":"connector","meaning":"walaupun namanya","reading":"to wa ie"},{"jp":"かじ","role":"subject","meaning":"pekerjaan rumah","reading":"kaji"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あって","role":"verb","meaning":"ada dan","reading":"atte"},{"jp":"いそがしい","role":"adjective","meaning":"sibuk","reading":"isogashii"}],"translation":"Walau namanya hari libur, tetap saja ada pekerjaan rumah dan sibuk."},{"tokens":[{"jp":"きかい","role":"subject","meaning":"mesin","reading":"kikai"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"べんりに","role":"adjective","meaning":"praktis","reading":"benri ni"},{"jp":"なった","role":"verb","meaning":"telah menjadi","reading":"natta"},{"jp":"とはいえ","role":"connector","meaning":"meskipun diakui","reading":"to wa ie"},{"jp":"人間の","role":"noun","meaning":"milik manusia","reading":"ningen no"},{"jp":"て","role":"subject","meaning":"tangan","reading":"te"},{"jp":"も","role":"particle","meaning":"tetap juga","reading":"mo"},{"jp":"ひつようだ","role":"adjective","meaning":"diperlukan","reading":"hitsuyou da"}],"translation":"Meskipun mesin sudah menjadi praktis, tetap saja sentuhan tangan manusia masih diperlukan."}],"when_to_use":["Mengakui suatu fakta resmi lalu membalik dengan kenyataan lapangan (''memang sudah musim semi sih, tapi masih dingin banget!'')","Merendah saat dipuji atau mengakui keunggulan lawan sambil memberi catatan (''meski masih pemula, dia cepat belajar'')","Artikel opini & esai penyeimbang argumen"],"formula_parts":[{"role":"noun","text":"Nomina / Bentuk Biasa","label":"Fakta yg diakui benar"},{"role":"connector","text":"とはいえ","label":"Memang demikian, namun"},{"role":"predicate","text":"Kenyataan Bertolak Belakang","label":"Sisi lain / catatan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000031', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-004', 'particle', 'Dengan Sarana Resmi / Batas Waktu (~をもって)', '[Nomina] + をもって', 'Menunjukkan instrumen resmi, cara penyelesaian, atau batas waktu efektif dalam pengumuman resmi.', 4, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Dengan berakhirnya hari ini, kampanye ini resmi ditutup.","jp":"本日をもちまして、本キャンペーンを 終了いたします。","reading":"Honjitsu o mochimashite, hon kyanpeen o shuuryou itashimasu."},{"id":"Hasil akan diberitahukan secara resmi melalui dokumen tertulis.","jp":"書面をもって 結果を 通知いたします。","reading":"Shomen o motte kekka o tsuuchi itashimasu."}]'::jsonb, '[Nomina] + o motte', '{"quiz":[{"why":"Menandai tanggal terakhir operasional penutupan toko memakai [tanggal] をもって.","answer":0,"options":["この みせは 来月１０日をもって 閉店（へいてん）いたします","この ペンをもって なまえを かいて ください","わたしは でんしゃをもって かいしゃへ いきます","きのうをもって ケーキを たべました"],"question":"Manakah pengumuman stasiun yang PALING ALAMI memakai ～をもって?"},{"why":"これをもちまして = ''Dengan penyampaian ini (sebagai penutup)...''.","answer":1,"options":["Tolong bawa pulang buku acara hari ini","Dengan ini, acara resmi hari ini kita akhiri","Acara baru saja dimulai","Besok acara dilanjutkan lagi"],"question":"Apa arti kalimat penutup MC ''これをもちまして、本日の 式を 終わります''?"},{"why":"をもって berasal dari ~o motte (memegang/menggunakan sarana ini sebagai patokan resmi).","answer":0,"options":["Karena bentuk aslinya berasal dari kata kerja 持つ (motsu = memegang/memakai objek)","Karena bunyinya lebih cepat","Karena にもって berarti dilarang","Karena aturan huruf Katakana"],"question":"Mengapa partikel を wajib berpasangan dengan もって ( bukan に)?"}],"forms":[{"id":"mengundurkan diri per akhir bulan ini","jp":"今月末をもって退職します","label":"Batas Tanggal","reading":"kongetsumatsu o motte taishoku shimasu"},{"id":"membalas melalui email","jp":"メールをもってご返信と代えます","label":"Sarana Tertulis","reading":"meeru o motte"},{"id":"dengan berakhirnya penyampaian di atas","jp":"以上をもちまして","label":"Penutup Pidato","reading":"ijou o mochimashite"}],"steps":["Untuk makna batas waktu berakhirnya layanan: taruh tanggal/jam akhir di depan をもって (misal: 本日をもって = terhitung hari ini...).","Untuk makna sarana/alat resmi: taruh kata benda cara/alat (misal: 書面をもって = secara tertulis lewat surat, 態度をもって = dengan perbuatan/sikap).","Di akhir kalimat biasanya muncul verba resmi seperti 終了します (berakhir), 閉店します (tutup permanen), atau お知らせします (mengumumkan)."],"analogy":"～をもって punya dua fungsi resmi: (1) ''Pada tanggal/waktu ini (sebagai batas resmi penutupan atau berakhirnya masa berlaku)'', dan (2) ''Melalui sarana resmi ini (surat, penjelasan lisan, hasil tes)''.","mistakes":[{"why":"Untuk alat sehari-hari seperti pena atau sumpit, selalu gunakan partikel で! をもって hanya untuk sarana/batasan bernuansa seremonial & resmi.","right":"きょうは ペンで 手紙を かきます","wrong":"きょうは ペンをもって 手紙を かきます (tulisan santai)"},{"why":"Untuk waktu, をもって paling lazim menandai BATAS AKHIR/penutupan resmi sesuatu.","right":"３じ から はじまります / ほんじつをもって しゅうりょうします","wrong":"３じ をもって はじまります (untuk mulai acara biasa)"}],"breakdowns":[{"tokens":[{"jp":"ほんじつ","role":"time","meaning":"hari ini","reading":"honjitsu"},{"jp":"をもって","role":"particle","meaning":"terhitung berakhir pada","reading":"o motte"},{"jp":"えいぎょう","role":"object","meaning":"operasional toko","reading":"eigyou"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"しゅうりょうします","role":"verb","meaning":"kami akhiri","reading":"shuuryou shimasu"}],"translation":"Terhitung hari ini, operasional kami resmi berakhir."},{"tokens":[{"jp":"けっか","role":"topic","meaning":"hasil","reading":"kekka"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"しょめん","role":"noun","meaning":"dokumen tertulis","reading":"shomen"},{"jp":"をもって","role":"particle","meaning":"melalui / dengan sarana","reading":"o motte"},{"jp":"おしらせします","role":"verb","meaning":"kami kabarkan","reading":"oshirase shimasu"}],"translation":"Hasilnya akan kami sampaikan secara resmi melalui dokumen tertulis."},{"tokens":[{"jp":"これ","role":"noun","meaning":"hal ini","reading":"kore"},{"jp":"をもって","role":"connector","meaning":"dengan ini","reading":"o motte"},{"jp":"へいかい","role":"noun","meaning":"penutupan acara","reading":"heikai"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"あいさつ","role":"noun","meaning":"sambutan","reading":"aisatsu"},{"jp":"とさせていただきます","role":"ending","meaning":"kami cukupkan sebagai","reading":"to sasete itadakimasu"}],"translation":"Dengan ini saya cukupkan sebagai sambutan penutupan acara."}],"when_to_use":["Pengumuman tutupnya loket, berakhirnya masa kerja/layanan, atau penutupan acara (''acara berakhir pada jam 5 tepat'')","Menyampaikan berita resmi ''melalui surat ini kami kabarkan...'' atau ''berterima kasih dengan tindakan nyata''","Kalimat formal di papan pengumuman stasiun, mal, surat kabar, atau pidato resmi"],"formula_parts":[{"role":"noun","text":"Nomina (Waktu / Sarana Resmi)","label":"Titik batas atau instrumen"},{"role":"particle","text":"をもって","label":"Pada batas / Dengan sarana"},{"role":"predicate","text":"Pernyataan Resmi","label":"Penutupan / Pembuktian"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000032', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-005', 'sentence_pattern', 'Tingkat Ekstrem Tanpa Tandingan (~極まりない)', '[Akar Kata Sifat-Na] + 極まりない（きわまりない）', 'Menekankan sifat ekstrem yang tak terlukiskan lagi (sering untuk kritik formal atau kondisi sangat serius).', 5, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Mempublikasikan tanpa verifikasi adalah tindakan yang luar biasa tidak bertanggung jawab.","jp":"確認せずに 公開するのは 無責任極まりない。","reading":"Kakunin sezu ni koukai suru no wa musekinin kiwamarinai."},{"id":"Kebisingan tengah malam merupakan tindakan yang sangat mengganggu.","jp":"深夜の 騒音は 迷惑極まりない 行為だ。","reading":"Shinnya no souon wa meiwaku kiwamarinai koui da."}]'::jsonb, '[Akar Kata Sifat-Na] + kiwamarinai', '{"quiz":[{"why":"Akar Sifat-Na langsung menempel ke 極まりない tanpa な atau だ.","answer":1,"options":["不愉快 な 極まりない","不愉快 極まりない","不愉快 だ 極まりない","不愉快 の 極まりない"],"question":"Bagaimana cara menyambungkan 不愉快（ふゆかい = tidak menyenangkan, Sifat-Na）dengan 極まりない?"},{"why":"Ungkapan N1 ini tepat untuk kecaman keras atau penekanan sifat ekstrem.","answer":0,"options":["Membahas betapa tidak sopannya orang yang membuang sampah sembarangan di tempat suci (無礼極まりない)","Memuji kucing tetangga yang imut","Meminta tambahan gula di kopi","Bertanya letak stasiun"],"question":"Pilih konteks kalimat yang PALING COCOK memakai ～極まりない:"},{"why":"きわまりない berarti ''tak berujung / tak tertandingi tingginya'', bukan bentuk penyangkalan.","answer":1,"options":["Ya, selalu berarti tidak ada batas","Tidak, artinya justru ''TERAMAT SANGAT / tiada batasnya''","Artinya ''kadang-kadang saja''","Artinya ''hampir tidak terjadi''"],"question":"Walau ada huruf ''ない'' di ujung 極まりない, apakah maknanya negatif (''tidak ekstrem'')?"}],"forms":[{"id":"amat sangat tidak bertanggung jawab","jp":"無責任極まりない","label":"Kritik Tajam","reading":"musekinin kiwamari nai"},{"id":"sungguh amat disayangkan","jp":"残念極まりない","label":"Rasa Sesal Resmi","reading":"zannen kiwamari nai"},{"id":"kehormatan yang tak terhingga","jp":"光栄極まりない","label":"Penekanan Positif Resmi","reading":"kouei kiwamari nai"}],"steps":["Ambil akar Kata Sifat-Na yang menyatakan penilaian kuat (contoh: 失礼 = tidak sopan, 危険 = berbahaya, 不愉快 = tidak menyenangkan, 遺憾 = sangat disayangkan).","JANGAN tambah な atau だ! Langsung tempelkan 極まりない (atau bentuk sopan 極まりないです / bentuk lampau 極まりなかった).","Untuk penulisan formal di koran, kadang dipakai variasi 極まる (kiwamaru)."],"analogy":"～極まりない artinya ''Sangat-sangat keterlaluan / tak terlukiskan lagi saking ekstremnya!'' (biasanya hal negatif, berbahaya, atau tidak sopan sekali — kadang juga untuk rasa syukur/senang yang memuncak di tulisan klasik).","mistakes":[{"why":"～極まりない adalah gaya tulisan/komentar tegas yang umumnya memakai Sifat-Na abstrak (berbahaya, tidak sopan, menyusahkan), bukan sifat-I ringan sehari-hari seperti ''enak''.","right":"とても おいしい！ / さいこうに おいしい！","wrong":"この ラーメンは おいしい 極まりない！"},{"why":"Tidak boleh memakai な di antara Sifat-Na dan 極まりない.","right":"しつれい 極まりない","wrong":"しつれい な 極まりない"}],"breakdowns":[{"tokens":[{"jp":"その","role":"noun","meaning":"itu","reading":"sono"},{"jp":"たいど","role":"topic","meaning":"sikap","reading":"taido"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"しつれい","role":"adjective","meaning":"kurang ajar/tidak sopan","reading":"shitsurei"},{"jp":"極まりない","role":"ending","meaning":"amat sangat (keterlaluan)","reading":"kiwamari nai"}],"translation":"Sikap seperti itu benar-benar tidak sopan tiada tara!"},{"tokens":[{"jp":"よなか","role":"time","meaning":"tengah malam","reading":"yonaka"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"ひとりで","role":"noun","meaning":"sendirian","reading":"hitori de"},{"jp":"あるく","role":"verb","meaning":"berjalan","reading":"aruku"},{"jp":"のは","role":"particle","meaning":"(hal tersebut)","reading":"no wa"},{"jp":"きけん","role":"adjective","meaning":"berbahaya","reading":"kiken"},{"jp":"極まりない","role":"ending","meaning":"sangat amat ekstrem","reading":"kiwamari nai"}],"translation":"Berjalan sendirian di tengah malam itu amat sangat berbahaya."},{"tokens":[{"jp":"めいわく","role":"adjective","meaning":"mengganggu/menyusahkan","reading":"meiwaku"},{"jp":"極まりない","role":"ending","meaning":"sungguh keterlaluan","reading":"kiwamari nai"},{"jp":"こうい","role":"noun","meaning":"tindakan","reading":"koui"},{"jp":"に","role":"particle","meaning":"terhadap","reading":"ni"},{"jp":"はら","role":"object","meaning":"perut/emosi","reading":"hara"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"たった","role":"verb","meaning":"naik (marah)","reading":"tatta"}],"translation":"Saya sangat marah atas perbuatan yang amat keterlaluan mengganggu tersebut."}],"when_to_use":["Mengkritik keras sikap sembrono atau bahaya besar (''tindakan yang amat sangat berbahaya'', ''amat tidak sopan!'')","Berita atau opini tentang kebijakan yang tidak adil atau menyusahkan","Menekankan sifat positif tertentu secara sangat sastrawi (''merupakan kehormatan yang tiada tara'')"],"formula_parts":[{"role":"adjective","text":"Akar Sifat-Na (tanpa な/だ)","label":"Sifat ekstrem"},{"role":"ending","text":"極まりない（きわまりない）","label":"Tiada tara / Kebangetan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000033', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-006', 'sentence_pattern', 'Dengan Caranya Sendiri (~なりに)', '[Nomina / Bentuk Biasa] + なりに', 'Mencapai tingkat sebaik mungkin sesuai kapasitas atau kondisi masing-masing.', 6, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Sesuai kapasitas pemula, saya berusaha sekuat tenaga.","jp":"初心者なりに 一生懸命 努力してきました。","reading":"Shoshinsha nari ni isshoukenmei doryoku shite kimashita."},{"id":"Setiap proposal punya keunggulannya tersendiri.","jp":"どの 案にも それなりの 利点が ある。","reading":"Dono an ni mo sorenari no riten ga aru."}]'::jsonb, '[Nomina / Bentuk Biasa] + nari ni', '{"quiz":[{"why":"Di depan kata benda (たのしみ方), wajib memakai なりの.","answer":1,"options":["なりに","なりの","なりのに","なりを"],"question":"Lengkapi: ''年をとれば、年をとった ___ たのしみ方が ある'' (Kalau sudah tua pun ada cara menikmati versi tuanya; たのしみ方 = nomina):"},{"why":"それなりに berarti ''ya cukuplah bagus/berfungsi sesuai porsinya''.","answer":0,"options":["Artinya ''lumayan oke / punya nilai baik sesuai keadaannya''","Artinya ''sangat gagal total''","Artinya ''paling mahal di dunia''","Artinya ''hanya untuk diri saya''"],"question":"Mengapa frase ''それなりに'' populer sekali di percakapan sehari-hari Jepang?"},{"why":"Nuansanya menghargai usaha maksimal meski level/skalanya belum seberapa.","answer":1,"options":["Memuji direktur utama","Membicarakan usaha tulus anak, pemula, atau diri sendiri dengan rendah hati","Mengeluarkan larangan polisi","Menetapkan denda pajak"],"question":"Pola ～なりに paling tepat dipakai kepada:"}],"forms":[{"id":"dia berpikir dengan caranya sendiri","jp":"かれはかれなりに考えた","label":"Diikuti Verba/Sifat","reading":"kare wa kare nari ni kangaeta"},{"id":"kreativitas khas pemula","jp":"初心者なりの工夫","label":"Diikuti Benda (+の)","reading":"shoshinsha nari no kufuu"},{"id":"lumayan bagus sesuai kadarnya","jp":"それなりにいい","label":"Pengulangan Subjek","reading":"sore nari ni ii"}],"steps":["Taruh siapa atau kondisi apa yang dijadikan patokan kapasitasnya di depan (contoh: こども = anak kecil, わたし = saya, 初心者 = pemula).","Langsung tempelkan なりに kalau diikuti kata kerja/sifat di belakang (''berusaha dengan caranya'').","Ganti menjadi なりの jika langsung diikuti kata benda (''gaya kebahagiaan tersendiri'', ''pendapat versi dirinya sendiri'')."],"analogy":"～なりに artinya ''Dengan caranya sendiri / Sesuai kadar kemampuannya''. Nada bicaranya hangat dan menghargai: mungkin hasilnya belum sempurna seperti ahli, tapi sudah diusahakan sebaik mungkin sesuai kapasitas dirinya!","mistakes":[{"why":"Jangan pakai なりに untuk memuji atasan atau ahli senior! Nuansa なりに menyiratkan ''walau levelnya masih terbatas, tapi sudah oke'' sehingga kurang sopan untuk yang lebih tinggi.","right":"すばらしい ごけいかくですね","wrong":"しゃちょう、しゃちょう なりの けいかくは じょうずですね"},{"why":"Tidak boleh menyisipkan の di depan なりに (langsung nomina + なりに).","right":"わたし なりに がんばる","wrong":"わたし の なりに がんばる"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"わたし","role":"noun","meaning":"diri saya","reading":"watashi"},{"jp":"なりに","role":"particle","meaning":"dengan cara & kemampuan saya","reading":"nari ni"},{"jp":"がんばりました","role":"verb","meaning":"sudah berjuang keras","reading":"ganbarimashita"}],"translation":"Saya sudah berjuang keras sesuai batas kemampuan diri saya sendiri."},{"tokens":[{"jp":"こども","role":"topic","meaning":"anak kecil","reading":"kodomo"},{"jp":"には","role":"particle","meaning":"bagi mereka","reading":"ni wa"},{"jp":"こども","role":"noun","meaning":"anak-anak","reading":"kodomo"},{"jp":"なりの","role":"particle","meaning":"versi/cara tersendiri","reading":"nari no"},{"jp":"なやみ","role":"subject","meaning":"kekhawatiran","reading":"nayami"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ある","role":"verb","meaning":"ada","reading":"aru"}],"translation":"Anak-anak pun punya beban pikiran versi anak-anaknya sendiri."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"まち","role":"topic","meaning":"kota","reading":"machi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"いなか","role":"noun","meaning":"pedesaan","reading":"inaka"},{"jp":"なりに","role":"particle","meaning":"sebagai daerah desa pun tetap","reading":"nari ni"},{"jp":"みりょく","role":"subject","meaning":"daya tarik","reading":"miryoku"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"たくさんある","role":"verb","meaning":"banyak sekali ada","reading":"takusan aru"}],"translation":"Meski daerah pedesaan, kota ini punya banyak daya tariknya tersendiri."}],"when_to_use":["Menghargai usaha anak kecil, pemula, atau orang yang berusaha semampunya (''meski masih anak-anak, dia berpikir dengan caranya sendiri'')","Merendah saat membicarakan usaha pribadi (''saya sudah berjuang semampu kapasitas saya'')","Melihat sisi positif dari sesuatu yang sederhana (''ruangan sempit ini punya kenyamanannya tersendiri sesuai ukurannya'')"],"formula_parts":[{"role":"noun","text":"Nomina / Bentuk Biasa","label":"Kapasitas / Posisi"},{"role":"particle","text":"なりに / なりの","label":"Sesuai caranya sendiri"},{"role":"predicate","text":"Usaha / Kualitas Tersendiri","label":"Hasil sesuai kapasitasnya"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000034', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-007', 'sentence_pattern', 'Pasti Menimbulkan Efek (~ずにはおかない)', '[Bentuk-NAI] (tanpa ない) + ずにはおかない', 'Menyatakan bahwa sesuatu pasti mendorong atau membuat orang merasakan dampak emosional/tindakan tertentu.', 7, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Pidato itu tak pelak menggugah hati seluruh hadirin.","jp":"その スピーチは 聴衆を 感動させずにはおかなかった。","reading":"Sono supiichi wa choushuu o kandou sasezu ni wa okanakatta."},{"id":"Jika mengetahui kebenarannya, siapa pun pasti terkejut.","jp":"真実を 知れば、誰もが 驚かずにはおかないだろう。","reading":"Shinjitsu o shireba, daremo ga odorokazu ni wa okanai darou."}]'::jsonb, '[Bentuk-NAI] (tanpa nai) + zu ni wa okanai', '{"quiz":[{"why":"Subjek luar (konser) memicu reaksi pada penonton, sehingga memakai bentuk kausatif (かんどうさせ) + ずにはおかない.","answer":0,"options":["かんどうさせ","かんどうし","かんどうする","かんどうさせて"],"question":"Bedakan dua pola mirip N1 ini! ''あの コンサートは、きくひとを ___ ずにはおかない'' (membuat haru; かんどうさせる = membuat terharu):"},{"why":"Dorongan spontan dari dalam diri yang sulit ditahan memakai ～ずにはいられない.","answer":1,"options":["おもしろくて わらわずには おかない","おもしろくて わらわずには いられない","おもしろくて わらうずには おかない","おもしろくて わらわせずには いられない"],"question":"Kalau yang tidak tahan menahan tawa adalah DIRIMU SENDIRI, mana yang tepat?"},{"why":"Kata kerja する wajib menjadi せず di depan ず.","answer":1,"options":["しずにはおかない","せずにはおかない","すずにはおかない","さずにはおかない"],"question":"Bentuk yang benar untuk kata kerja する sebelum ずにはおかない adalah:"}],"forms":[{"id":"pasti bikin tertawa","jp":"わらわせずにはおかない","label":"Verba Umum (-NAI + ずに)","reading":"warawasezu ni wa okanai"},{"id":"pasti membuatnya merenung","jp":"はんせいせずにはおかない","label":"Khusus する (せず)","reading":"hansei sezu ni wa okanai"},{"id":"saya tak tahan ingin tertawa (perasaan diri)","jp":"わらわずにはいられない","label":"Bandingkan: ～ずにはいられない","reading":"warawazu ni wa irarenai"}],"steps":["Ambil kata kerja emosi atau akibat yang ditimbulkan pada orang lain (contoh: かんどうさせる = bikin terharu, わらわせる = bikin tertawa, おこらせる = bikin marah).","Ubah ke Bentuk-NAI lalu buang ない (misal: かんどうさせない → かんどうさせ). Khusus する wajib menjadi せず!","Tambahkan ずにはおかない (''tidak akan membiarkannya berlalu tanpa membuat...''). Jangan bingung dengan ～ずにはいられない (''diri sendiri nggak tahan ingin...'')."],"analogy":"～ずにはおかない artinya ''Pasti tanpa ampun akan memicu reaksi/perasaan tertentu bagi siapa pun yang mengalaminya''. Seperti bilang: ''Film itu dijamin bakal bikin siapa saja yang nonton nangis!''.","mistakes":[{"why":"Kalau subjeknya dirimu sendiri yang ''nggak tahan pengen ngelakuin'', pakai ～ずにはいられない! ～ずにはおかない subjeknya adalah pemicu luar yang ''pasti bikin orang lain...''.","right":"おいしい においに、たべずにはいられない","wrong":"おいしい においに、たべずにはおかない"},{"why":"Sama seperti pola kuno ～ず lainnya, する selalu berubah menjadi せず, bukan しず.","right":"せずにはおかない","wrong":"しずにはおかない"}],"breakdowns":[{"tokens":[{"jp":"その","role":"noun","meaning":"itu","reading":"sono"},{"jp":"えいが","role":"topic","meaning":"film","reading":"eiga"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"みるひと","role":"object","meaning":"penontonnya","reading":"miru hito"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"なかせ","role":"verb","meaning":"membuat menangis","reading":"nakase"},{"jp":"ずにはおかない","role":"ending","meaning":"pasti akan","reading":"zu ni wa okanai"}],"translation":"Film itu pasti akan membuat penontonnya menangis."},{"tokens":[{"jp":"かれ","role":"topic","meaning":"dia","reading":"kare"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"スピーチ","role":"subject","meaning":"pidato","reading":"supiichi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"みんな","role":"object","meaning":"semua orang","reading":"minna"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"かんどうさせ","role":"verb","meaning":"menggugah haru","reading":"kandou sase"},{"jp":"ずにはおかない","role":"ending","meaning":"pasti takkan gagal","reading":"zu ni wa okanai"}],"translation":"Pidatonya pasti akan menggugah rasa haru semua orang."},{"tokens":[{"jp":"しんじん","role":"noun","meaning":"pendatang baru","reading":"shinjin"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"かつやく","role":"topic","meaning":"aksi gemilang","reading":"katsuyaku"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ちゅうもく","role":"object","meaning":"sorotan/perhatian","reading":"chuumoku"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"あつめ","role":"verb","meaning":"menarik","reading":"atsume"},{"jp":"ずにはおかない","role":"ending","meaning":"pasti akan","reading":"zu ni wa okanai"}],"translation":"Aksi gemilang sang pendatang baru itu pasti akan menarik sorotan publik."}],"when_to_use":["Menggambarkan kekuatan karya seni, pidato, atau musik yang pasti menggugah hati (''lagu ini pasti membuat pendengarnya terharu'')","Tekad kuat atau hukuman pasti (''kejahatan ini pasti akan mengundang kemarahan publik / pasti kubalas'')","Ulasan buku, pameran, drama, dan opini sastra"],"formula_parts":[{"role":"verb","text":"Bentuk-NAI (tanpa ない)","label":"Reaksi yg pasti muncul"},{"role":"ending","text":"ずにはおかない","label":"Pasti bikin / takkan berhenti tanpa..."}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000035', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-008', 'sentence_pattern', 'Jika Sudah Sampai Level (~ともなると)', '[Nomina / Verba Kamus] + ともなると', 'Ketika mencapai posisi, skala, atau musim tingkat tertentu, maka konsekuensi khususnya pun berlaku.', 8, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Bila skala proyek sudah sebesar ini, diperlukan kehati-hatian tinggi.","jp":"プロジェクトの 規模が これほど 大きくともなると、慎重さが 要る。","reading":"Purojekuto no kibo ga kore hodo ookiku tomo naru to, shinchousa ga iru."},{"id":"Jika sudah menduduki jajaran eksekutif, dituntut wawasan jangka panjang.","jp":"経営幹部ともなると、長期的な 視野が 求められる。","reading":"Keiei kanbu tomo naru to, choukiteki na shiya ga motomerareru."}]'::jsonb, '[Nomina / Verba Kamus] + to mo naru to', '{"quiz":[{"why":"Menyoroti dampak kemampuan ketika mencapai tingkatan tinggi (N1) memakai ～ともなると.","answer":0,"options":["ともなると","を余儀なくされて","といえども","なりに"],"question":"Lengkapi: ''JLPT N1 ___、新聞の 記事も かなり 読めるように なる'' (Kalau sudah sampai level N1...):"},{"why":"Keduanya hampir sinonim; ともなると lebih umum menggambarkan kenyataan pada level itu, ともなれば bernada syarat.","answer":0,"options":["Sama persis penggunaannya; ともなれば sedikit lebih hipotesis (''andaikan/kalau sudah...'')","ともなれば hanya untuk lampau","ともなると hanya untuk benda mati","Beda makna 180 derajat"],"question":"Apa perbedaan bentuk ともなると dan ともなれば?"},{"why":"Menjadi figur terkenal membawa konsekuensi wajar selalu difoto orang ke mana pun pergi.","answer":1,"options":["１ねんせい ともなると、あいうえおが かけない","ゆうめいじん ともなると、どこへ いっても しゃしんを とられる","きょう ともなると、あさごはんを たべた","コーヒー ともなると、あつい"],"question":"Manakah kalimat yang logis untuk ～ともなると?"}],"forms":[{"id":"kalau sudah jadi pemimpin","jp":"りーだーともなると","label":"Jabatan / Status","reading":"riidaa to mo naru to"},{"id":"begitu tiba musim libur panjang","jp":"なつやすみともなれば","label":"Musim / Waktu","reading":"natsuyasumi to mo nareba"},{"id":"kalau sudah 10 tahun tinggal di Jepang","jp":"にほんに１０ねんすむともなると","label":"Verba Peningkatan","reading":"Nihon ni 10-nen sumu to mo naru to"}],"steps":["Pilih status atau waktu yang levelnya di atas rata-rata atau istimewa (contoh: しゃちょう = direktur, N1 = level tertinggi, １２がつ = Desember akhir tahun).","Tambahkan ともなると (fakta umum di level itu) atau ともなれば (''seandainya sampai level itu...'').","Jelaskan standar baru, tekanan, atau ciri khas yang muncul sebanding dengan level tersebut."],"analogy":"～ともなると artinya ''Kalau sudah sampai di level / jabatan / musim setinggi itu, wajar dong kalau...'' (beda jauh dari pemula/biasa!).","mistakes":[{"why":"Bila tidak mencerminkan level spesial/puncak atau hanya fakta biasa, kurang cocok memakai ともなると. Juga jangan sisipkan partikel に sebelum と!","right":"高校生（こうこうせい）にも なると / 大人に なると","wrong":"学生に ともなると、まいにち 学校へ いく"},{"why":"Bila memakai kata kerja, gunakan Bentuk Kamus yang bermakna mencapai suatu tahap (misal: はたらく, もつ).","right":"しっぱいする ともなると / こまったことに なる","wrong":"しっぱいした ともなると"}],"breakdowns":[{"tokens":[{"jp":"プロ","role":"noun","meaning":"profesional","reading":"puro"},{"jp":"ともなると","role":"connector","meaning":"kalau sudah sekelas","reading":"to mo naru to"},{"jp":"れんしゅう","role":"subject","meaning":"latihan","reading":"renshuu"},{"jp":"も","role":"particle","meaning":"juga","reading":"mo"},{"jp":"きびしい","role":"adjective","meaning":"keras / ketat","reading":"kibishii"}],"translation":"Kalau sudah sampai level profesional, latihannya pun tentu sangat ketat."},{"tokens":[{"jp":"１２がつ","role":"time","meaning":"bulan Desember","reading":"juunigatsu"},{"jp":"ともなると","role":"connector","meaning":"kalau sudah masuk","reading":"to mo naru to"},{"jp":"あさばん","role":"time","meaning":"pagi & malam","reading":"asaban"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ぐっと","role":"adjective","meaning":"drastis terasa","reading":"gutto"},{"jp":"さむくなります","role":"adjective","meaning":"menjadi dingin","reading":"samuku narimasu"}],"translation":"Kalau sudah memasuki bulan Desember, pagi dan malam terasa makin dingin drastis."},{"tokens":[{"jp":"会社の","role":"noun","meaning":"milik perusahaan","reading":"kaisha no"},{"jp":"しゃちょう","role":"noun","meaning":"direktur utama","reading":"shachou"},{"jp":"ともなれば","role":"connector","meaning":"kalau sudah menjadi","reading":"to mo nareba"},{"jp":"じぶん","role":"noun","meaning":"diri sendiri","reading":"jibun"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"じかん","role":"subject","meaning":"waktu luang","reading":"jikan"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ほとんどない","role":"adjective","meaning":"hampir tidak ada","reading":"hotondo nai"}],"translation":"Jika sudah menjadi seorang direktur perusahaan, hampir tak ada waktu pribadi."}],"when_to_use":["Membahas tanggung jawab jabatan tinggi (''kalau sudah jadi manajer, tanggung jawabnya ikut besar'')","Menggambarkan kehebatan level ahli atau negara maju (''sekelas atlet olimpiade latihannya tentu luar biasa'')","Menggambarkan suasana khas di puncak musim (''kalau sudah masuk bulan Desember, kota pun ramai lampu'')"],"formula_parts":[{"role":"noun","text":"Nomina / Kamus Verba","label":"Level tinggi / Puncak waktu"},{"role":"connector","text":"ともなると / ともなれば","label":"Kalau sudah sampai level..."},{"role":"predicate","text":"Konsekuensi Selevel","label":"Kondisi khusus yg ikut berubah"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000036', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-009', 'particle', 'Tanpa Memandang Kondisi (~いかんによらず)', '[Nomina + の] + いかんによらず / いかんにかかわらず', 'Menyatakan aturan atau keputusan tetap berlaku tidak peduli bagaimana kondisi atau alasannya.', 9, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Terlepas dari apa pun alasannya, ketidakhadiran tanpa izin tidak dibenarkan.","jp":"理由の いかんによらず、無断欠勤は 認められません。","reading":"Riyuu no ikan ni yorazu, mudan kekkin wa mitomeraremasen."},{"id":"Tanpa memandang ada tidaknya pengalaman, Anda dapat mendaftar.","jp":"経験の有無の いかんにかかわらず、応募可能です。","reading":"Keiken no umu no ikan ni kakawarazu, oubo kanou desu."}]'::jsonb, '[Nomina + no] + ikan ni yorazu / ikan ni kakawarazu', '{"quiz":[{"why":"Menyatakan aturan berlaku mutlak tanpa memandang alasan apa pun menggunakan [Nomina] の いかんによらず.","answer":0,"options":["の いかんによらず","を 余儀なくされ","に 至って","ともなると"],"question":"Aturan kontrak berbunyi: ''天災（てんさい = bencana）以外の いかなる 理由 ___、解約料が 発生します'':"},{"why":"いかん sendiri berarti ''bagaimana kondisinya''; dengan よらず artinya ''tak peduli kondisinya'', sedangkan いかんだ berarti ''tergantung pada kondisinya''.","answer":1,"options":["Sudah pasti gagal","Tergantung bagaimana usahamu nanti","Tidak usah berusaha","Sudah selesai kemarin"],"question":"Jika Anda melihat pola saudaranya yang tanpa ''よらず'', yakni ''すべては あなたの 努力 ___ です'' (ikan da / shidai da), artinya berubah menjadi:"},{"why":"いかん wajib didahului Kata Benda abstrak, bukan kata sifat.","answer":2,"options":["経験（けいけん = pengalaman）","事情（じじょう = keadaan）","きれいな（cantik - Sifat-Na）","結果（けっか = hasil）"],"question":"Kata manakah yang TIDAK BISA dipasang tepat di depan のいかんによらず?"}],"forms":[{"id":"apa pun alasannya","jp":"理由のいかんによらず","label":"Tanpa Memandang Alasan","reading":"riyuu no ikan ni yorazu"},{"id":"apa pun hasilnya nanti","jp":"結果のいかんにかかわらず","label":"Variasi Umum","reading":"kekka no ikan ni kakawarazu"},{"id":"tergantung pada usahamu","jp":"きみのどりょくいかんだ","label":"Kontras: ～いかんだ","reading":"kimi no doryoku ikan da"}],"steps":["Pilih kata benda yang hasilnya belum pasti atau punya banyak variasi (contoh: 理由 = alasan, 結果 = hasil, 国籍 = kewarganegaraan, 天候 = cuaca).","Tambahkan いかんによらず atau いかんにかかわらず (dengan atau tanpa の boleh, misal: 理由のいかんによらず / 理由いかんにかかわらず).","Di bagian belakang, tegaskan aturan yang mutlak tetap sama rata bagi semuanya."],"analogy":"～いかんによらず artinya ''Tanpa memandang apakah alasannya begini atau begitu (apapun kondisinya), aturannya TETAP berlaku sama!'' — mirip kata tegas Indonesia ''Terlepas dari apapun... tetap wajib/berlaku''.","mistakes":[{"why":"Kata いかん selalu mengikuti KATA BENDA abstrak (seperti ''alasan'', ''hasil'', ''ukuran'', ''kadar''), tidak menempel ke kata sifat langsung.","right":"サイズの いかんによらず","wrong":"大きい 小さい の いかんによらず"},{"why":"Tidak boleh langsung menempel ke kata kerja! Gunakan kata benda abstrak atau gunakan ～にかかわらず saja untuk pasangan verba (いく・いかないにかかわらず).","right":"さんかの うむ にかかわらず","wrong":"いく いかんによらず"}],"breakdowns":[{"tokens":[{"jp":"りゆう","role":"noun","meaning":"alasan","reading":"riyuu"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"いかんによらず","role":"connector","meaning":"apa pun itu tanpa memandang","reading":"ikan ni yorazu"},{"jp":"ちこく","role":"topic","meaning":"keterlambatan","reading":"chikoku"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"みとめられません","role":"verb","meaning":"tidak dapat ditoleransi","reading":"mitomeraremasen"}],"translation":"Terlepas dari apa pun alasannya, keterlambatan tidak dapat ditoleransi."},{"tokens":[{"jp":"せいせき","role":"noun","meaning":"nilai / hasil","reading":"seiseki"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"いかんにかかわらず","role":"connector","meaning":"bagaimanapun hasilnya","reading":"ikan ni kakawarazu"},{"jp":"全員","role":"subject","meaning":"semua peserta","reading":"zen''in"},{"jp":"に","role":"particle","meaning":"kepada","reading":"ni"},{"jp":"さんかしょう","role":"object","meaning":"sertifikat partisipasi","reading":"sankashou"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"だします","role":"verb","meaning":"diberikan","reading":"dashimasu"}],"translation":"Tanpa memandang bagaimanapun nilainya, semua peserta akan mendapat sertifikat."},{"tokens":[{"jp":"ねんれい","role":"noun","meaning":"usia","reading":"nenrei"},{"jp":"・","role":"connector","meaning":"dan","reading":""},{"jp":"せいべつ","role":"noun","meaning":"jenis kelamin","reading":"seibetsu"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"いかんを問わず","role":"connector","meaning":"tanpa mempersoalkan","reading":"ikan o towazu"},{"jp":"おうぼできます","role":"verb","meaning":"dapat melamar","reading":"oubo dekimasu"}],"translation":"Siapa pun dapat melamar tanpa memandang usia maupun jenis kelamin."}],"when_to_use":["Aturan perusahaan, ujian, atau kontrak hukum yang tak ada toleransi pengecualian (''tidak peduli alasannya apa, keterlambatan tetap didenda'')","Pernyataan hak yang setara (''tanpa memandang usia atau jenis kelamin, semua berhak mendaftar'')","Konteks resmi pemerintahan, kebijakan kampus, dan syarat ketentuan lomba"],"formula_parts":[{"role":"noun","text":"Nomina (+ の)","label":"Kondisi / Faktor yg diabaikan"},{"role":"connector","text":"いかんによらず / にかかわらず","label":"Tanpa memandang apa pun"},{"role":"predicate","text":"Ketentuan Tetap","label":"Aturan tidak berubah"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000037', '0175a068-7604-4e23-b571-a6d14dd68a47', 'GP-JA-N1-010', 'sentence_pattern', 'Layak Untuk (~に足る)', '[Nomina / Verba Kamus] + に足る（にたる）', 'Menyatakan kualitas yang cukup memadai atau pantas untuk dipercaya, dipuji, atau dibahas.', 10, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Ia adalah sosok yang sangat layak dipercaya.","jp":"彼は 十分に 信頼するに足る 人物だ。","reading":"Kare wa juubun ni shinrai suru ni taru jinbutsu da."},{"id":"Hal itu merupakan pokok bahasan penting yang layak diperdebatkan.","jp":"それは 議論するに足る 重要な 論点である。","reading":"Sore wa giron suru ni taru juuyouna ronten de aru."}]'::jsonb, '[Nomina / Verba Kamus] + ni taru', '{"quiz":[{"why":"気にするに足りない artinya ''tidak cukup bernilai untuk dikhawatirkan / biarkan saja''.","answer":1,"options":["Rumor itu sangat berbahaya dan harus dipercaya","Rumor itu sama sekali tidak pantas dipusingkan / dihiraukan","Kita wajib menyebarkan rumor tersebut","Rumor itu layak diteliti lebih jauh"],"question":"Apa arti idiom klasik JLPT N1 ''そんな 噂（うわさ = rumor）は 気にする に足りない''?"},{"why":"注目 (kata benda perhatian) + に足る = ''layak untuk menjadi pusat perhatian''.","answer":0,"options":["に足る","ともなると","を余儀なくされる","にかぎらず"],"question":"Lengkapi: ''これは 専門家の 注目 ___ すぐれた 研究だ'' (Ini riset unggul yang layak mendapat perhatian para ahli; 注目 = perhatian/sorotan):"},{"why":"尊敬に足る (layak dihormati) adalah kolokasi standar N1 yang elegan.","answer":0,"options":["かれは 私たちの 代表として 尊敬（そんけい）に足る 人だ","あしたの てんきは あめに 足る","この カバンは ５千円に 足る","きのう ともだちに あうに 足る"],"question":"Manakah kalimat yang pemakaian ～に足る-nya PALING TEPAT?"}],"forms":[{"id":"data yang layak dipercaya","jp":"信頼に足るデータ","label":"Menerangkan Benda","reading":"shinrai ni taru deeta"},{"id":"tindakan yang pantas dipuji","jp":"ほめるに足る行動","label":"Dengan Verba","reading":"homeru ni taru koudou"},{"id":"masalah kecil yang tak perlu dipusingkan","jp":"取るに足りない問題","label":"Idiom Negatif (Remeh)","reading":"toru ni tarinai mondai"}],"steps":["Gunakan kata kerja evaluasi intelektual/etika (contoh: 信頼する = percaya, 尊敬する = hormat, 評価する = menilai positif, 驚く = kaget).","Sambungkan dengan に足る (atau bentuk kamus lengkapnya に足りる). Kalau memakai kata benda aksi, boleh langsung Nomina + に足る (contoh: 信頼に足る = layak dipercaya).","Bila menyebut masalah sepele yang tak perlu dirisaukan, pakai idiom terkenal: 心配する に足りない / 取るに足りない (''hal remeh / tak seberapa'')."],"analogy":"～に足る (dibaca ni taru / ni tariru) artinya ''Cukup layak untuk...'', ''Pantas untuk...'', atau ''Bernilai untuk...''. Mirip ungkapan formal ''layak dipercaya'', ''pantas dipuji'', atau ''layak dibahas''.","mistakes":[{"why":"～に足る khusus untuk penilaian nilai moral, kepercayaan, kehormatan, atau analisis akademis — bukan sekadar layak makan atau layak dibeli di toko.","right":"たべる かちが ある ケーキ","wrong":"おなかが すいたから、たべる に足る ケーキ"},{"why":"Bila memakai kata kerja, hanya boleh Bentuk Kamus (する), tidak boleh Bentuk-TA.","right":"かれは しんらいする に足る / しんらいに足る","wrong":"かれを しんらいした に足る"}],"breakdowns":[{"tokens":[{"jp":"かれ","role":"topic","meaning":"dia","reading":"kare"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"しんらい","role":"noun","meaning":"kepercayaan","reading":"shinrai"},{"jp":"に足る","role":"verb","meaning":"yang layak (dipercaya)","reading":"ni taru"},{"jp":"じんぶつ","role":"predicate","meaning":"sosok pribadi","reading":"jinbutsu"},{"jp":"だ","role":"ending","meaning":"(adalah)","reading":"da"}],"translation":"Dia adalah sosok pribadi yang benar-benar layak dipercaya."},{"tokens":[{"jp":"それは","role":"topic","meaning":"hal itu","reading":"sore wa"},{"jp":"とる","role":"verb","meaning":"mengambil/hitung","reading":"toru"},{"jp":"に足りない","role":"ending","meaning":"tidak layak (remeh)","reading":"ni tarinai"},{"jp":"ちいさな","role":"adjective","meaning":"kecil","reading":"chiisana"},{"jp":"ミス","role":"predicate","meaning":"kesalahan","reading":"misu"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Itu hanyalah kesalahan kecil yang sepele (tak perlu dirisaukan)."},{"tokens":[{"jp":"きみ","role":"topic","meaning":"kamu","reading":"kimi"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"けっか","role":"subject","meaning":"hasil kerja","reading":"kekka"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"じゅうぶん","role":"adjective","meaning":"sepenuhnya","reading":"juubun"},{"jp":"しょうさん","role":"noun","meaning":"pujian","reading":"shousan"},{"jp":"に足りる","role":"verb","meaning":"layak mendapat","reading":"ni tariru"},{"jp":"もの","role":"predicate","meaning":"hal/capaian","reading":"mono"},{"jp":"だ","role":"ending","meaning":"(adalah)","reading":"da"}],"translation":"Hasil kerjamu adalah capaian yang sepenuhnya layak mendapat pujian."}],"when_to_use":["Menilai kredibilitas seseorang atau sumber informasi (''orang yang layak dipercaya'', ''data yang valid/pantas diandalkan'')","Memberikan apresiasi tinggi atas karya atau pencapaian (''karya yang layak diapresiasi tinggi'')","Bentuk negatifnya ～に足りない / ～に足らない artinya ''hal remeh yang tidak layak dipusingkan / tidak pantas diperhitungkan''"],"formula_parts":[{"role":"verb","text":"Nomina (Aksi) / Kamus Verba","label":"Tindakan penilaian (percaya/puji)"},{"role":"ending","text":"に足る（にたる） / に足りない","label":"Layak untuk / Tak pantas (remeh)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000018', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-001', 'particle', 'Menjelang / Dalam Rangka (~にあたって)', '[Nomina / Kamus Verba] + にあたって', 'Digunakan secara formal menjelang momen penting atau dimulainya sebuah proyek besar.', 1, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Dalam rangka memulai bisnis baru, kami membagikan targetnya.","jp":"新事業の 開始にあたって、目標を 共有します。","reading":"Shinjigyou no kaishi ni atatte, mokuhyou o kyouyuu shimasu."},{"id":"Menjelang presentasi, saya mengecek bahan terlebih dahulu.","jp":"発表にあたって、事前に 資料を 確認した。","reading":"Happyou ni atatte, jizen ni shiryou o kakunin shita."}]'::jsonb, '[Nomina / Kamus Verba] + ni atatte', '{"quiz":[{"why":"Pola ini berkesan formal dan cocok untuk pembukaan acara, proyek, atau babak hidup baru.","answer":1,"options":["Menjelang tidur malam seperti biasa","Saat memberikan pidato pembukaan proyek besar di kantor","Saat lupa membawa payung di tengah hujan","Saat menyapa tetangga di lift"],"question":"Situasi manakah yang PALING WAJAR memakai ～にあたって?"},{"why":"Kata kerja yang menempel sebelum にあたって selalu memakai Bentuk Kamus (する).","answer":0,"options":["する","した","して","しよう"],"question":"Lengkapi: ''にほん へ りゅうがく ___ にあたって、いろいろな ほけんに はいった'' (Menjelang berangkat studi ke Jepang, ikut asuransi):"},{"why":"にあたり adalah bentuk yang sedikit lebih ringkas dan sering ditemukan di pidato, surat resmi, atau artikel berita.","answer":0,"options":["にあたり lebih formal / khas bahasa tulisan & pidato resmi","にあたり artinya ''setelah''","あたり dipakai hanya untuk bentuk negatif","Keduanya berbeda arti sepenuhnya"],"question":"Apa perbedaan にあたり dibanding にあたって?"}],"forms":[{"id":"menjelang memulai rapat","jp":"かいぎをはじめるにあたって","label":"Resmi Lisan","reading":"kaigi o hajimeru ni atatte"},{"id":"dalam rangka kelulusan","jp":"そつぎょうにあたり","label":"Teks Pidato","reading":"sotsugyou ni atari"},{"id":"aturan menyambut acara tersebut","jp":"あんぜんにあたってのルール","label":"Menerangkan Benda","reading":"ni atatte no ruuru"}],"steps":["Pilih kata benda momen penting (contoh: しゅっぱつ = keberangkatan, けっこん = pernikahan) atau kata kerja bentuk kamus.","Tambahkan にあたって (lisan resmi) atau にあたり (lebih sering di teks tertulis/pidato).","Di bagian akhir kalimat, nyatakan persiapan, pesan khusus, atau ucapan terima kasih menyambut momen tersebut."],"analogy":"～にあたって artinya ''Menjelang...'' atau ''Dalam rangka memulai...'' suatu acara besar, upacara, atau proyek penting. Nuansanya resmi dan penuh persiapan, jarang dipakai untuk kegiatan remeh harian.","mistakes":[{"why":"Jangan pakai にあたって untuk rutinitas sepele setiap hari; pola ini khusus tonggak acara atau kejadian besar.","right":"ごはんを たべる まえに、てを あらいます","wrong":"まいあさ ごはんを たべるにあたって、てを あらいます"},{"why":"にあたって artinya ''menjelang/saat memulai sesuatu yang baru'', bukan setelah selesai lama lalu menyesal.","right":"しんねん を むかえる にあたって","wrong":"しんねん が おわった にあたって"}],"breakdowns":[{"tokens":[{"jp":"しゅっぱつ","role":"time","meaning":"keberangkatan","reading":"shuppatsu"},{"jp":"にあたって","role":"connector","meaning":"menjelang","reading":"ni atatte"},{"jp":"みなさん","role":"noun","meaning":"semuanya","reading":"minasan"},{"jp":"に","role":"particle","meaning":"kepada","reading":"ni"},{"jp":"ごあいさつします","role":"verb","meaning":"menyampaikan salam","reading":"goaisatsu shimasu"}],"translation":"Menjelang keberangkatan, saya menyampaikan salam perpisahan kepada semua."},{"tokens":[{"jp":"あたらしい","role":"adjective","meaning":"baru","reading":"atarashii"},{"jp":"みせ","role":"object","meaning":"toko","reading":"mise"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"ひらく","role":"verb","meaning":"membuka (kamus)","reading":"hiraku"},{"jp":"にあたって","role":"connector","meaning":"dalam rangka","reading":"ni atatte"},{"jp":"いろいろ","role":"object","meaning":"berbagai hal","reading":"iroiro"},{"jp":"じゅんびしました","role":"verb","meaning":"mempersiapkan","reading":"junbi shimashita"}],"translation":"Menjelang membuka toko baru, saya sudah mempersiapkan berbagai hal."},{"tokens":[{"jp":"しんせいひん","role":"noun","meaning":"produk baru","reading":"shinseihin"},{"jp":"の","role":"particle","meaning":"(tentang)","reading":"no"},{"jp":"はつばい","role":"noun","meaning":"peluncuran/penjualan","reading":"hatsubai"},{"jp":"にあたり","role":"connector","meaning":"dalam rangka","reading":"ni atari"},{"jp":"イベント","role":"object","meaning":"acara promo","reading":"ibento"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"おこないます","role":"verb","meaning":"mengadakan","reading":"okonaimasu"}],"translation":"Dalam rangka peluncuran produk baru, kami akan mengadakan acara spesial."}],"when_to_use":["Memberi sambutan saat pembukaan proyek baru, rapat tahunan, atau acara resmi","Menjelaskan persiapan penting sebelum pindah kota, masuk kuliah, atau menikah","Pengumuman resmi perusahaan di email atau papan informasi"],"formula_parts":[{"role":"time","text":"Nomina / Kamus Verba","label":"Momen penting yg akan mulai"},{"role":"connector","text":"にあたって / にあたり","label":"Menjelang / Dalam rangka"},{"role":"predicate","text":"Sambutan / Persiapan","label":"Hal yang dilakukan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000019', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-002', 'sentence_pattern', 'Seiring Dengan (~に伴って)', '[Nomina / Kamus Verba] + に伴って（ともなって）', 'Menyatakan perubahan kedua yang terjadi beriringan dengan perubahan pertama.', 2, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Seiring perkembangan ekonomi, populasi kota bertambah.","jp":"経済の 発展に伴って、都市の 人口が 増えた。","reading":"Keizai no hatten ni tomonatte, toshi no jinkou ga fueta."},{"id":"Seiring pembaruan sistem, spesifikasi turut diubah.","jp":"システムの 更新に伴い、仕様を 変更します。","reading":"Shisutemu no koushin ni tomonai, shiyou o henkou shimasu."}]'::jsonb, '[Nomina / Kamus Verba] + ni tomonatte', '{"quiz":[{"why":"Pertambahan kelas online beriringan dengan naiknya permintaan laptop mencerminkan dua tren yang bergerak bersama.","answer":1,"options":["ケーキが おいしいのに ともなって、もう ひとつ たべました","オンラインじゅぎょうが ふえるに ともなって、パソコンの じゅようも たかまった","きのう ともだちに あうに ともなって、えいがを みた","へやが しずかに ともなって、ねむりやすい"],"question":"Kalimat mana yang pemakaian ～に伴って-nya PALING ALAMI?"},{"why":"Jika menerangkan nomina tepat di belakangnya, pakailah bentuk kamus ～に伴う.","answer":1,"options":["に伴って","に伴う","に伴いの","に伴っての"],"question":"Pilih bentuk yang tepat sebelum kata benda: ''引っ越し ___ いろいろな てつづき (berbagai prosedur terkait pindahan)'':"},{"why":"に伴う/に伴って menekankan perubahan A berjalan seiring dan menyebabkan perubahan B.","answer":1,"options":["Karena singkat hurufnya","Karena mengandung proses perubahan jumlah/skala yang memicu dampak ikutannya","Karena khusus untuk anak-anak","Karena bermakna larangan"],"question":"Mengapa kata kerja ''ふえる'' (bertambah) cocok sekali dipasangkan dengan ～に伴って?"}],"forms":[{"id":"seiring bertambahnya umur","jp":"としをとるに伴って","label":"Dengan Verba","reading":"toshi o toru ni tomonatte"},{"id":"seiring dengan reformasi","jp":"かいかくに伴って","label":"Dengan Nomina","reading":"kaikaku ni tomonatte"},{"id":"biaya yang menyertai pindahan","jp":"引っ越しに伴う費用","label":"Menerangkan Benda","reading":"hikkoshi ni tomonau hiyou"}],"steps":["Pastikan bagian depan mengandung makna PERUBAHAN atau PERGERAKAN (seperti ''bertambah'', ''meningkat'', ''pembangunan'', ''menurun'').","Tambahkan に伴って di tengah kalimat (bisa juga ditulis dengan Hiragana にともなって).","Jika diletakkan langsung di depan Kata Benda (''masalah yang menyertai perkembangan kota''), ubah menjadi に伴う + Nomina."],"analogy":"～に伴って artinya ''Seiring dengan berubahnya A, maka B pun ikut berubah''. Bayangkan dua hal bergerak bareng dalam satu arah (misalnya: seiring bertambahnya usia, tenaga berkurang).","mistakes":[{"why":"Tidak boleh dipakai untuk kata sifat statis tanpa unsur perubahan/perkembangan.","right":"やすくて おいしい ので、にんきです","wrong":"この みせは やすくて、おいしい に伴って にんきです"},{"why":"Bila memodifikasi kata benda langsung, ganti menjadi ～に伴う (ni tomonau).","right":"きゅうりょう げんしょう にともなう せいかつ","wrong":"きゅうりょうが さがるにともなって の せいかつ"}],"breakdowns":[{"tokens":[{"jp":"じんこう","role":"subject","meaning":"jumlah penduduk","reading":"jinkou"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ふえる","role":"verb","meaning":"bertambah","reading":"fueru"},{"jp":"に伴って","role":"connector","meaning":"seiring dengan","reading":"ni tomonatte"},{"jp":"ゴミ","role":"subject","meaning":"sampah","reading":"gomi"},{"jp":"も","role":"particle","meaning":"juga","reading":"mo"},{"jp":"ふえました","role":"verb","meaning":"bertambah","reading":"fuemashita"}],"translation":"Seiring bertambahnya penduduk, sampah pun ikut meningkat."},{"tokens":[{"jp":"ぎじゅつ","role":"noun","meaning":"teknologi","reading":"gijutsu"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"しんぽ","role":"noun","meaning":"kemajuan","reading":"shinpo"},{"jp":"に伴って","role":"connector","meaning":"seiring dengan","reading":"ni tomonatte"},{"jp":"せいかつ","role":"subject","meaning":"gaya hidup","reading":"seikatsu"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"べんりに","role":"adjective","meaning":"menjadi praktis","reading":"benri ni"},{"jp":"なりました","role":"verb","meaning":"telah menjadi","reading":"narimashita"}],"translation":"Seiring kemajuan teknologi, hidup pun menjadi semakin praktis."},{"tokens":[{"jp":"たいふう","role":"noun","meaning":"topan","reading":"taifuu"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"せっきん","role":"noun","meaning":"kedatangan mendekat","reading":"sekkin"},{"jp":"に伴い","role":"connector","meaning":"seiring","reading":"ni tomonai"},{"jp":"かぜ","role":"subject","meaning":"angin","reading":"kaze"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"つよくなってきました","role":"adjective","meaning":"semakin kencang","reading":"tsuyoku natte kimashita"}],"translation":"Seiring semakin dekatnya topan, angin mulai bertiup semakin kencang."}],"when_to_use":["Berita ekonomi atau sosial (''seiring tumbuhnya AI, cara kerja ikut berubah'')","Perubahan alam atau jumlah penduduk (''seiring naiknya suhu, pemakaian AC meningkat'')","Menceritakan konsekuensi dari perluasan perusahaan atau bertambahnya jumlah siswa"],"formula_parts":[{"role":"noun","text":"Nomina / Kamus Verba","label":"Perubahan pertama"},{"role":"connector","text":"に伴って（ともなって）","label":"Seiring dengan"},{"role":"predicate","text":"Perubahan Kedua","label":"Efek yang ikut bergerak"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000020', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-003', 'particle', 'Tidak Terbatas Pada (~に限らず)', '[Nomina] + に限らず（にかぎらず）', 'Menunjukkan cakupan yang lebih luas tidak hanya satu kategori saja.', 3, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Layanan ini tidak terbatas bagi orang Jepang, siapa saja bisa memakainya.","jp":"この サービスは 日本人に 限らず、誰でも 利用できる。","reading":"Kono saabisu wa nihonjin ni kagirazu, daredemo riyou dekiru."},{"id":"Buka tidak hanya hari kerja, tetapi juga akhir pekan.","jp":"平日のみに限らず、週末も 営業しています。","reading":"Heijitsu nomi ni kagirazu, shuumatsu mo eigyou shite imasu."}]'::jsonb, '[Nomina] + ni kagirazu', '{"quiz":[{"why":"に限らず memperluas topik dari contoh awal (masakan) ke cakupan menyeluruh (apa pun).","answer":0,"options":["に限らず","にあたり","に伴い","に限って"],"question":"Lengkapi: ''りょうり ___、なんでも 自分で 作るのが 趣味です'' (Bukan cuma soal masakan saja, bikin apa pun sendiri adalah hobinya):"},{"why":"～に限らず berasal dari bentuk negatif ''tanpa membatasi'', sedangkan に限って artinya ''justru di saat itu...'' / ''khusus...''.","answer":1,"options":["～に限って","～に限らず","Keduanya persis sama","Tidak ada yang benar"],"question":"Bedakan ～に限らず vs ～に限って. Manakah yang artinya ''Tidak terbatas pada...''?"},{"why":"Dari bahasa Jepang melebar ke bahasa Inggris dan Mandarin juga, memakai kata benda 日本語 di depan に限らず.","answer":0,"options":["日本語に限らず、英語や 中国語も はなせます","はしるに限らず、およぐのも すき","きのうに限らず、とても さむかった","あなたに限らず、わたしも いきたくない"],"question":"Kalimat mana yang menggunakan ～に限らず dengan benar?"}],"forms":[{"id":"bukan cuma mahasiswa","jp":"がくせいに限らず","label":"Kelompok Orang","reading":"gakusei ni kagirazu"},{"id":"bukan cuma musim panas, sepanjang tahun","jp":"なつに限らず一年中","label":"Waktu","reading":"natsu ni kagirazu ichinenjuu"},{"id":"bukan cuma Jepang, tapi banyak negara","jp":"日本に限らず多くの国","label":"Modifikasi Benda","reading":"Nihon ni kagirazu ooku no kuni"}],"steps":["Sebutkan kategori sempit yang biasanya paling menonjol di depan (contoh: わかもの = anak muda, ニホン = Jepang).","Tempelkan に限らず (atau versi agak lebih kaku にかぎらず).","Di bagian belakang, sebutkan bahwa cakupannya meluas memakai partikel も atau ungkapan universal (おとなも = orang dewasa juga, せかいじゅうで = di seluruh dunia)."],"analogy":"～に限らず artinya ''Tidak terbatas pada A saja, tapi juga B, C, dan lainnya!''. Sama persis seperti ungkapan Indonesia ''Bukan cuma [X] doang, tapi semua orang/bidang juga ikut...''.","mistakes":[{"why":"Di bagian belakang wajib ada makna cakupan yang LEBIH LUAS (''apa saja / semuanya juga''), tidak bisa hanya menyebut satu kejadian sempit.","right":"すし に限らず、日本りょうりは なんでも すきです","wrong":"わたしは すし に限らず たべたいです"},{"why":"Pola ini langsung menempel pada KATA BENDA (tidak menempel langsung ke kata kerja tanpa pembendaan).","right":"たべもの に限らず","wrong":"たべる に限らず"}],"breakdowns":[{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"アニメ","role":"topic","meaning":"anime","reading":"anime"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"こども","role":"noun","meaning":"anak-anak","reading":"kodomo"},{"jp":"に限らず","role":"connector","meaning":"tidak terbatas pada","reading":"ni kagirazu"},{"jp":"おとな","role":"noun","meaning":"orang dewasa","reading":"otona"},{"jp":"にも","role":"particle","meaning":"juga bagi","reading":"ni mo"},{"jp":"にんきがある","role":"adjective","meaning":"populer","reading":"ninki ga aru"}],"translation":"Anime ini tidak hanya digemari anak-anak, tetapi populer juga di kalangan orang dewasa."},{"tokens":[{"jp":"しゅうまつ","role":"time","meaning":"akhir pekan","reading":"shuumatsu"},{"jp":"に限らず","role":"connector","meaning":"tidak terbatas pada","reading":"ni kagirazu"},{"jp":"へいじつ","role":"time","meaning":"hari kerja biasa","reading":"heijitsu"},{"jp":"も","role":"particle","meaning":"pun","reading":"mo"},{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"カフェ","role":"subject","meaning":"kafe","reading":"kafe"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"こんでいます","role":"verb","meaning":"selalu ramai","reading":"konde imasu"}],"translation":"Tidak hanya akhir pekan, di hari biasa pun kafe ini selalu ramai."},{"tokens":[{"jp":"しんじん","role":"noun","meaning":"karyawan baru","reading":"shinjin"},{"jp":"に限らず","role":"connector","meaning":"tak terkecuali","reading":"ni kagirazu"},{"jp":"だれでも","role":"subject","meaning":"siapa saja","reading":"dare demo"},{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"けんしゅう","role":"noun","meaning":"pelatihan","reading":"kenshuu"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"さんかできます","role":"verb","meaning":"bisa ikut","reading":"sanka dekimasu"}],"translation":"Tidak terbatas pada karyawan baru saja, siapa pun dapat mengikuti pelatihan ini."}],"when_to_use":["Menunjukkan popularitas sesuatu melebar luas (''film ini tidak cuma disukai anak-anak, tapi juga orang dewasa'')","Aturan berlaku umum bagi siapa pun tanpa terkecuali (''tidak hanya pegawai tetap, pekerja paruh waktu pun ikut rapat'')","Menyoroti fenomena di berbagai kota atau negara (''bukan cuma di Tokyo, di daerah pun harga naik'')"],"formula_parts":[{"role":"noun","text":"Nomina (Contoh Sempit)","label":"Kategori awal"},{"role":"connector","text":"に限らず（にかぎらず）","label":"Tidak terbatas pada"},{"role":"predicate","text":"Cakupan Lebih Luas (...も)","label":"Yang lainnya juga"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000021', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-004', 'sentence_pattern', 'Tidak Mungkin Bisa / Terikat Etika (~わけにはいかない)', '[Kamus Verba] + わけにはいかない', 'Secara moral, sosial, atau logis tidak dapat melakukan sesuatu meski mungkin sebenarnya ingin.', 4, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Karena ada rapat penting, saya tidak mungkin libur.","jp":"大事な 会議が あるので、休むわけにはいきません。","reading":"Daijina kaigi ga aru node, yasumu wake ni wa ikimasen."},{"id":"Karena sudah berjanji, tidak bisa berhenti di tengah jalan.","jp":"約束したからには、途中で やめるわけにはいかない。","reading":"Yakusoku shita kara ni wa, tochuu de yameru wake ni wa ikanai."}]'::jsonb, '[Kamus Verba] + wake ni wa ikanai', '{"quiz":[{"why":"Secara etika menjaga janji tidak mungkin bisa membocorkannya (いう = mengatakan).","answer":0,"options":["いう","いわない","いえない","いった"],"question":"Sudah berjanji tidak memberi tahu siapa pun. Kalimat yang tepat: ''かれとの やくそくだから、だれにも ___ わけにはいかない'':"},{"why":"Negatif ganda (tidak pergi + tidak mungkin bisa) bermakna mau tidak mau harus hadir.","answer":1,"options":["Tidak usah datang","Mau tidak mau harus datang (tidak enak kalau absen)","Dilarang keras datang","Tidak bisa datang karena sakit"],"question":"Apa makna kalimat \"ぶちょうの けっこんしきだから、いかない わけにはいかない\"?"},{"why":"Undangan teman baik mengikat secara etika dan perasaan sosial, bukan ketidakmampuan fisik.","answer":2,"options":["Tangan patah sehingga tak kuat menulis -> かく わけにはいかない","Belum belajar kanji sehingga tidak bisa baca -> よむ わけにはいかない","Teman baik mengundang ke nikahannya, jadi nggak enak kalau absen -> いかない わけにはいかない","Harga mobil mahal sekali -> かう わけにはいかない"],"question":"Situasi manakah yang BENAR memakai ～わけにはいかない?"}],"forms":[{"id":"tidak boleh membocorkan rahasia","jp":"ひみつをはなすわけにはいかない","label":"Tidak Etis Dilakukan","reading":"himitsu o hanasu wake ni wa ikanai"},{"id":"mau tidak mau harus pergi","jp":"いかないわけにはいかない","label":"Terpaksa Harus Hadir","reading":"ikanai wake ni wa ikanai"},{"id":"tidak mungkin dapat kami tolak (sgt resmi)","jp":"おことわりするわけにはまいりません","label":"Versi Sopan","reading":"okotowari suru wake ni wa mairimasen"}],"steps":["Pakai Bentuk Kamus kalau maksudnya ''nggak bisa/nggak etis berbuat itu'' (contoh: やめるわけにはいかない = nggak bisa berhenti tengah jalan).","Pakai Bentuk-NAI kalau maksudnya ''MAU TIDAK MAU harus...'' (contoh: いかないわけにはいかない = nggak mungkin nggak pergi → mau tak mau harus datang).","Jangan tertukar dengan できない (nggak bisa secara fisik/kemampuan)! Pola ini khusus hambatan moral, janji, atau aturan sosial."],"analogy":"～わけにはいかない artinya ''Mana mungkin bisa...'' atau ''Tidak mungkin tega / etis berbuat begitu'' karena terikat janji, etika sosial, tanggung jawab kerja, atau perasaan hati — walau fisikmu sebenarnya masih mampu!","mistakes":[{"why":"Bila tidak bisa karena kemampuan teknis/fisik (tidak bisa berenang), pakailah ことができない / わけにはいかない salah konteks karena itu bukan masalah etika/janji.","right":"およぎかたを しらないから、およぐ ことが できない","wrong":"およぎかたを しらないから、およぐ わけにはいかない"},{"why":"Hati-hati logika negatif ganda! [tidak menyetir] + wake ni wa ikanai artinya ''mau tak mau HARUS menyetir''.","right":"ねむいから、うんてんする わけにはいかない","wrong":"くるまを うんてんしない わけにはいかない (mau nyetir padahal ngantuk)"}],"breakdowns":[{"tokens":[{"jp":"たいせつな","role":"adjective","meaning":"penting","reading":"taisetsu na"},{"jp":"やくそく","role":"object","meaning":"janji","reading":"yakusoku"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"やぶる","role":"verb","meaning":"melanggar","reading":"yaburu"},{"jp":"わけにはいかない","role":"ending","meaning":"tidak mungkin boleh","reading":"wake ni wa ikanai"}],"translation":"Saya tidak mungkin melanggar janji yang penting itu."},{"tokens":[{"jp":"あした","role":"time","meaning":"besok","reading":"ashita"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"しけん","role":"noun","meaning":"ujian","reading":"shiken"},{"jp":"なので","role":"connector","meaning":"karena","reading":"na node"},{"jp":"きょう","role":"time","meaning":"hari ini","reading":"kyou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"あそぶ","role":"verb","meaning":"main-main","reading":"asobu"},{"jp":"わけにはいきません","role":"ending","meaning":"tidak etis / mana bisa","reading":"wake ni wa ikimasen"}],"translation":"Karena besok ada ujian, mana mungkin hari ini saya bersantai main-main."},{"tokens":[{"jp":"ぶちょう","role":"noun","meaning":"kepala divisi","reading":"buchou"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"けっこんしき","role":"noun","meaning":"pesta nikah","reading":"kekkonshiki"},{"jp":"だから","role":"connector","meaning":"karena","reading":"dakara"},{"jp":"しゅっせきしない","role":"verb","meaning":"tidak hadir (NAI)","reading":"shusseki shinai"},{"jp":"わけにはいきません","role":"ending","meaning":"tidak mungkin tidak hadir","reading":"wake ni wa ikimasen"}],"translation":"Karena ini pesta nikah kepala divisi, mau tidak mau saya harus hadir."}],"when_to_use":["Menolak halus tawaran karena terikat tanggung jawab (''walau capek, nggak bisa seenaknya bolos kerja'')","Menjaga rahasia atau janji pribadi (''sudah berjanji, jadi nggak mungkin saya bocorkan'')","Merasa segan menolak pemberian atau bantuan karena keadaan sosial (''nggak enak hati kalau tidak datang ke pesta teman'')"],"formula_parts":[{"role":"verb","text":"Kamus Verba / Bentuk-NAI","label":"Hal yg dilarang moral/janji"},{"role":"ending","text":"わけにはいかない","label":"Tidak mungkin bisa dilakukan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000022', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-005', 'sentence_pattern', 'Terpaksa Harus (~ざるを得ない)', '[Bentuk-NAI] (tanpa ない) + ざるを得ない', 'Tidak punya pilihan selain melakukan hal tersebut walaupun berat.', 5, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Karena anggaran kurang, mau tidak mau rencana harus ditinjau ulang.","jp":"予算が 足りないため、計画を 見直さざるを得ない。","reading":"Yosan ga tarinai tame, keikaku o minaosazaru o enai."},{"id":"Demi keamanan, acara terpaksa dibatalkan.","jp":"安全のため、イベントを 中止せざるを得なかった。","reading":"Anzen no tame, ibento o chuushi sezaru o enakatta."}]'::jsonb, '[Bentuk-NAI] (tanpa nai) + zaru o enai', '{"quiz":[{"why":"Pengecualian tunggal penting di JLPT: する selalu menjadi せざるを得ない.","answer":2,"options":["延期しざるを得ない","延期するざるを得ない","延期せざるを得ない","延期さざるを得ない"],"question":"Bagaimana menyambungkan kata kerja する (melakukan, misal 延期する = menunda) ke ～ざるを得ない?"},{"why":"Ambil Bentuk-NAI (いわない), hilangkan ない (いわ), lalu tambah ざるを得ない.","answer":1,"options":["いわずを得ない","いわざるを得ない","いうざるを得ない","いわないざるを得ない"],"question":"Bagaimana mengubah いいます (mengatakan -> いわない) menjadi ''terpaksa harus mengatakan''?"},{"why":"Pola ini menunjukkan keputusan terpaksa di luar keinginan karena desakan situasi.","answer":1,"options":["Pembicara melakukannya dengan penuh sukacita","Pembicara sebenarnya tidak ingin, tapi kondisi memaksanya harus melakukannya","Pembicara masih ragu-ragu mau atau tidak","Pembicara melarang orang lain"],"question":"Apa kesan yang ditangkap pendengar saat kamu memakai ～ざるを得ない?"}],"forms":[{"id":"terpaksa menyerah","jp":"あきらめざるを得ない","label":"Verba Biasa","reading":"akiramezaru o enai"},{"id":"terpaksa membatalkan","jp":"ちゅうしせざるを得ない","label":"Verba する (Pengecualian!)","reading":"chuushi sezaru o enai"},{"id":"terpaksa harus dibatalkan (sopan)","jp":"ちゅうしせざるを得ません","label":"Bentuk Sopan","reading":"chuushi sezaru o emasen"}],"steps":["Ubah kata kerja ke Bentuk-NAI lalu buang kata ない (misal: やめる → やめ, いく → いか, あきらめる → あきらめ).","INGAT 1 PENGECUALIAN WAJIB: Kata kerja する TIDAK menjadi しざるを得ない, melainkan WAJIB menjadi せざるを得ない!","Tambahkan ざるを得ない (atau bentuk sopannya ざるを得ません) di paling akhir."],"analogy":"～ざるを得ない artinya ''Terpaksa mau tidak mau harus...'' meski di lubuk hati sebenarnya keberatan atau berat hati sekali. Lebih formal dan serius dibanding ～なければならない.","mistakes":[{"why":"Khusus kata kerja する wajib berubah menjadi せざるを得ない (bukan しざる).","right":"しごとを やめざるを得ない / せざるを得ない","wrong":"しごとを やめるしざるを得ない / しざるを得ない"},{"why":"Bentuk yang ditempeli ざるを得ない adalah akar Bentuk-NAI (warawanai → warawa + zaru o enai), bukan bentuk kamus.","right":"おもしろくて わらわざるを得ない","wrong":"たのしい ので、わらう ざるを得ない"}],"breakdowns":[{"tokens":[{"jp":"たいふう","role":"noun","meaning":"topan","reading":"taifuu"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"ため","role":"connector","meaning":"karena","reading":"tame"},{"jp":"りょこう","role":"object","meaning":"wisata","reading":"ryokou"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"ちゅうしせざるを得ない","role":"verb","meaning":"terpaksa harus membatalkan","reading":"chuushi sezaru o enai"}],"translation":"Karena ada topan, kami terpaksa harus membatalkan wisata."},{"tokens":[{"jp":"あんな","role":"noun","meaning":"begitu kuat","reading":"anna"},{"jp":"しょうこ","role":"object","meaning":"bukti","reading":"shouko"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"みせられたら","role":"verb","meaning":"kalau diperlihatkan","reading":"miseraretara"},{"jp":"じぶん","role":"noun","meaning":"diri sendiri","reading":"jibun"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"ミス","role":"object","meaning":"kesalahan","reading":"misu"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"みとめざるを得ない","role":"verb","meaning":"terpaksa harus mengakui","reading":"mitomezaru o enai"}],"translation":"Kalau sudah ditunjukkan bukti begitu, mau tidak mau harus mengakui kesalahan sendiri."},{"tokens":[{"jp":"おかね","role":"subject","meaning":"uang","reading":"okane"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"たりない","role":"verb","meaning":"tidak cukup","reading":"tarinai"},{"jp":"ので","role":"connector","meaning":"karena","reading":"node"},{"jp":"けいかく","role":"object","meaning":"rencana","reading":"keikaku"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"へんこうせざるを得ません","role":"verb","meaning":"terpaksa harus mengubah","reading":"henkou sezaru o emasen"}],"translation":"Karena dananya kurang, kami terpaksa harus mengubah rencana."}],"when_to_use":["Mengambil keputusan berat demi keadaan (harus menutup cabang toko yang merugi, menunda acara karena badai)","Terpaksa mengakui kesalahan atau menerima konsekuensi logis meski enggan","Bahasa laporan bisnis, artikel hukum, atau pengumuman resmi krisis"],"formula_parts":[{"role":"verb","text":"Bentuk-NAI (tanpa ない)","label":"Akar verba (-a)"},{"role":"ending","text":"ざるを得ない（ざるをえない）","label":"Terpaksa harus"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000023', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-006', 'sentence_pattern', 'Meskipun / Terlepas Dari (~にもかかわらず)', '[Nomina / Bentuk Biasa] + にもかかわらず', 'Menunjukkan hasil yang bertolak belakang dengan kondisi awal ("meskipun ...").', 6, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Meskipun hujan deras, banyak orang tetap berkumpul.","jp":"激しい 雨にもかかわらず、多くの 人が 集まった。","reading":"Hageshii ame ni mo kakawarazu, ooku no hito ga atsumatta."},{"id":"Meski sudah diperingatkan, kesalahan yang sama terulang.","jp":"注意したにもかかわらず、同じ ミスが 繰り返された。","reading":"Chuui shita ni mo kakawarazu, onaji misu ga kurikaesareta."}]'::jsonb, '[Nomina / Bentuk Biasa] + ni mo kakawarazu', '{"quiz":[{"why":"わかい adalah kata sifat-i, sehingga langsung menempel apa adanya sebelum にもかかわらず.","answer":2,"options":["わかい だ","わかい な","わかい","わかく"],"question":"Lengkapi: ''かれは まだ わか___ にもかかわらず、会社の リーダーを まかされている'' (Meski masih muda...):"},{"why":"Kata Benda & Sifat-Na langsung ditempelkan tanpa partikel な maupun だ.","answer":0,"options":["びょうき にもかかわらず","びょうき な にもかかわらず","びょうき だ にもかかわらず","びょうき の にもかかわらず"],"question":"Bagaimana memakai Kata Benda びょうき (penyakit) di depan にもかかわらず?"},{"why":"それにもかかわらず berdiri di awal kalimat kedua untuk membalik fakta kalimat pertama.","answer":1,"options":["Oleh karena itu","Meskipun demikian / Kendati begitu","Selain itu","Dengan kata lain"],"question":"Apa arti penghubung antarkalimat ''それにもかかわらず''?"}],"forms":[{"id":"meskipun hari libur","jp":"きゅうじつ にもかかわらず","label":"Kata Benda","reading":"kyuujitsu ni mo kakawarazu"},{"id":"meskipun tidak praktis","jp":"ふべんにもかかわらず","label":"Sifat-Na","reading":"fuben ni mo kakawarazu"},{"id":"meskipun demikian, ...","jp":"それにもかかわらず","label":"Awal Kalimat Baru","reading":"sore ni mo kakawarazu"}],"steps":["Tulis fakta awalnya terlebih dahulu (misal: あめ = hujan, いそがしい = sibuk, どりょくした = sudah berusaha keras).","PENTING: Untuk Kata Benda dan Sifat-Na, TIDAK memakai だ atau な! Langsung saja tempelkan にもかかわらず (contoh: びょうき にもかかわらず, しずか にもかかわらず).","Untuk Verba atau Sifat-I, memakai Bentuk Biasa langsung + にもかかわらず."],"analogy":"～にもかかわらず artinya persis ''Meskipun / Walaupun begitu tetap saja...'' dalam gaya bahasa yang tegas, rapi, dan cukup formal (lebih kuat dan berwibawa daripada ～のに atau ～ても).","mistakes":[{"why":"Bila didahului Kata Benda (やすみ) atau Sifat-Na (ふべん), buang だ/な seluruhnya sebelum にもかかわらず! (untuk bentuk lampau, boleh memakai ～だった にもかかわらず).","right":"やすみ にもかかわらず","wrong":"やすみ な にもかかわらず / やすみ だ にもかかわらず"},{"why":"Kalimat di belakang harus bertolak belakang (lawan logika) dengan kalimat di depan.","right":"ねむい にもかかわらず、べんきょうを つづけました","wrong":"ねむい にもかかわらず、すぐ ねました"}],"breakdowns":[{"tokens":[{"jp":"おおあめ","role":"noun","meaning":"hujan lebat","reading":"ooame"},{"jp":"にもかかわらず","role":"connector","meaning":"meskipun","reading":"ni mo kakawarazu"},{"jp":"おおぜい","role":"subject","meaning":"banyak orang","reading":"oozei"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あつまりました","role":"verb","meaning":"berkumpul hadir","reading":"atsumarimashita"}],"translation":"Meskipun hujan lebat, banyak sekali orang tetap hadir berkumpul."},{"tokens":[{"jp":"かれ","role":"topic","meaning":"dia","reading":"kare"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"なんども","role":"time","meaning":"berkali-kali","reading":"nando mo"},{"jp":"ちゅういされた","role":"verb","meaning":"sudah diperingatkan","reading":"chuui sareta"},{"jp":"にもかかわらず","role":"connector","meaning":"padahal / walaupun","reading":"ni mo kakawarazu"},{"jp":"また","role":"time","meaning":"lagi-lagi","reading":"mata"},{"jp":"おなじ","role":"adjective","meaning":"sama","reading":"onaji"},{"jp":"ミス","role":"object","meaning":"kesalahan","reading":"misu"},{"jp":"をした","role":"verb","meaning":"melakukan","reading":"o shita"}],"translation":"Meskipun sudah berkali-kali diperingatkan, dia tetap mengulangi kesalahan yang sama."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"みせ","role":"topic","meaning":"toko","reading":"mise"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ねだん","role":"subject","meaning":"harga","reading":"nedan"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"たかい","role":"adjective","meaning":"mahal","reading":"takai"},{"jp":"にもかかわらず","role":"connector","meaning":"meskipun","reading":"ni mo kakawarazu"},{"jp":"いつも","role":"time","meaning":"selalu","reading":"itsumo"},{"jp":"まんせき","role":"predicate","meaning":"penuh sesak","reading":"manseki"},{"jp":"だ","role":"ending","meaning":"(adalah)","reading":"da"}],"translation":"Toko ini meskipun harganya mahal, selalu penuh sesak."}],"when_to_use":["Menulis berita atau laporan analitis (''meskipun harga sudah diturunkan, penjualannya tetap sepi'')","Menghargai usaha seseorang di luar dugaan (''walaupun sangat sibuk, beliau meluangkan waktu datang'')","Mengungkapkan rasa kecewa atau heran secara formal"],"formula_parts":[{"role":"noun","text":"Nomina / Bentuk Biasa (tanpa だ)","label":"Fakta kondisi awal"},{"role":"connector","text":"にもかかわらず","label":"Meskipun demikian"},{"role":"predicate","text":"Hasil Berlawanan","label":"Kenapa tetap bertolak belakang"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000024', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-007', 'tense', 'Setelah Mempertimbangkan / Dalam Hal (~上で)', '[Bentuk-TA / Nomina + の] + 上で（うえで）', 'Melakukan langkah pertama secara tuntas sebagai pijakan untuk keputusan atau tindakan berikutnya.', 7, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Setelah memeriksa isi kontrak dengan saksama, silakan tanda tangani.","jp":"契約書の 内容を 確認した上で、署名してください。","reading":"Keiyakusho no naiyou o kakunin shita ue de, shomei shite kudasai."},{"id":"Dalam hal menjaga kesehatan pun, tidur sangat penting.","jp":"健康管理の 上でも、睡眠は 重要です。","reading":"Kenkou kanri no ue demo, suimin wa juuyou desu."}]'::jsonb, '[Bentuk-TA / Nomina + no] + ue de', '{"quiz":[{"why":"Untuk urutan tahap (''setelah melakukan A, baru B''), wajib memakai Bentuk-TA (りかいした).","answer":1,"options":["りかいする","りかいした","りかいして","りかい"],"question":"Lengkapi kontrak: ''内容（ないよう）を よく ___ 上で、サインしてください'' (Setelah memahami isinya dengan baik, baru tanda tangan; りかいする = memahami):"},{"why":"Bila didahului Bentuk Kamus (住む), 上で berarti ''dalam hal / ketika melakukan hal tersebut''.","answer":1,"options":["Setelah tinggal di Jepang selesai","Dalam hal / Untuk keperluan tinggal di Jepang...","Meskipun tinggal di Jepang","Seiring tinggal di Jepang"],"question":"Apa perbedaan makna kalimat ''日本に住む 上で、ルールを知ることが大切だ'' (pakai bentuk kamus)?"},{"why":"Kata Benda memakai partikel の sebelum 上で.","answer":0,"options":["けんとう の 上で","けんとう な 上で","けんとう で 上で","けんとう を 上で"],"question":"Mana yang memakai partikel penyambung yang benar untuk kata benda けんとう (pertimbangan)?"}],"forms":[{"id":"setelah memastikan syaratnya","jp":"じょうけんをかくにんした上で","label":"Urutan Matang (Bentuk-TA)","reading":"jouken o kakunin shita ue de"},{"id":"dengan kehati-hatian penuh","jp":"じゅうぶんちゅういのうえで","label":"Nomina (+の)","reading":"juubun chuui no ue de"},{"id":"dalam hal belajar","jp":"べんきょうする上で","label":"Aspek / Bidang (Kamus)","reading":"benkyou suru ue de"}],"steps":["Jika bermakna tahapan berurutan (''setelah melakukan A, baru kerjakan B''): taruh Verba Bentuk-TA atau Nomina + の di depan 上で.","Jika bermakna ''dalam hal melakukan X'' / ''dari sudut pandang X'' (seperti ''penting dalam hidup di Jepang''): pakai Kamus Verba + 上で atau Nomina + 上(で).","Bentuk negatifnya diletakkan di bagian belakang kalimat atau memakai kata benda pertimbangan."],"analogy":"～上で (dibaca ~ue de) artinya ''Setelah mempertimbangkan / menyelesaikan tahap A lebih dulu, barulah melangkah ke tahap B'' atau ''Dalam hal / Untuk keperluan...''.","mistakes":[{"why":"Untuk rutinitas sepele sehari-hari tanpa unsur persiapan keputusan/prosedur serius, gunakan ～てから. ～た上で bernuansa tindakan bermakna.","right":"あさ ごはんを たべてから、はを みがきます","wrong":"あさ ごはんを たべた 上で、はを みがきます"},{"why":"Kata Benda wajib menyisipkan の sebelum 上で (atau memakai Bentuk-TA そうだんした 上で).","right":"そうだん の 上で きめます","wrong":"そうだん 上で きめます"}],"breakdowns":[{"tokens":[{"jp":"よく","role":"adjective","meaning":"dengan matang","reading":"yoku"},{"jp":"かんがえた","role":"verb","meaning":"sudah memikirkan (TA)","reading":"kangaeta"},{"jp":"上で","role":"connector","meaning":"setelah mempertimbangkan baru","reading":"ue de"},{"jp":"へんじ","role":"object","meaning":"jawaban","reading":"henji"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"します","role":"verb","meaning":"saya beri","reading":"shimasu"}],"translation":"Setelah memikirkannya matang-matang, baru saya akan memberi jawaban."},{"tokens":[{"jp":"かぞく","role":"noun","meaning":"keluarga","reading":"kazoku"},{"jp":"と","role":"particle","meaning":"bersama","reading":"to"},{"jp":"そうだん","role":"noun","meaning":"diskusi","reading":"soudan"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"上で","role":"connector","meaning":"setelah selesai","reading":"ue de"},{"jp":"きめました","role":"verb","meaning":"kami memutuskan","reading":"kimemashita"}],"translation":"Kami memutuskannya setelah berdiskusi dengan keluarga."},{"tokens":[{"jp":"日本","role":"place","meaning":"Jepang","reading":"Nihon"},{"jp":"で","role":"particle","meaning":"di","reading":"de"},{"jp":"はたらく","role":"verb","meaning":"bekerja (kamus)","reading":"hataraku"},{"jp":"上で","role":"connector","meaning":"dalam hal / untuk","reading":"ue de"},{"jp":"けいご","role":"subject","meaning":"bahasa hormat","reading":"keigo"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"とても","role":"adjective","meaning":"sangat","reading":"totemo"},{"jp":"たいせつです","role":"adjective","meaning":"penting","reading":"taisetsu desu"}],"translation":"Dalam hal bekerja di Jepang, keigo sangatlah penting."}],"when_to_use":["Prosedur resmi (''setelah berdiskusi dengan keluarga, baru memutuskan''; ''setelah baca ketentuan kontrak, baru tanda tangan'')","Menyebutkan aspek pertimbangan tertentu (''sangat penting dari segi kesehatan / belajar'')","Konteks bisnis, aturan, dan keputusan yang butuh pertimbangan matang"],"formula_parts":[{"role":"verb","text":"Bentuk-TA / Nomina + の","label":"Tahap persiapan / Bidang"},{"role":"connector","text":"上で（うえで）","label":"Setelah ... baru / Dalam hal"},{"role":"predicate","text":"Keputusan / Penilaian","label":"Langkah utama"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000025', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-008', 'tense', 'Sedang Terus Berlangsung (~つつある)', '[Stem Verba] + つつある', 'Menggambarkan tren atau perubahan progresif yang sedang berlangsung secara formal (sering dipakai di berita).', 8, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Penuaan demografi masyarakat terus bergerak maju.","jp":"地域社会の 高齢化が 進みつつある。","reading":"Chiiki shakai no koureika ga susumitsutsu aru."},{"id":"Situasinya sedikit demi sedikit sedang terus membaik.","jp":"状況は 少しずつ 改善されつつあります。","reading":"Joukyou wa sukoshizutsu kaizen saretsutsu arimasu."}]'::jsonb, '[Stem Verba] + tsutsu aru', '{"quiz":[{"why":"へります dibuang ます menjadi stem へり, lalu disambung dengan つつある.","answer":1,"options":["へる つつある","へり つつある","へった つつある","へって つつある"],"question":"Pilih bentuk akar verba yang benar untuk ''Populasi beruang mulai berkurang (へります = berkurang)'':"},{"why":"Makan nasi bukan tren progresif yang sedang berubah perlahan; gunakan たべています.","answer":1,"options":["Karena makanan tidak boleh dijelaskan dengan formal","Karena ～つつある khusus menyatakan proses perubahan/tren berangsur, bukan aktivitas seketika sehari-hari","Karena kata kerja grup 2 tidak punya stem","Karena つつある hanya untuk bentuk lampau"],"question":"Mengapa kalimat ''あした つつある'' atau ''ごはんを たべつつあります'' terdengar aneh?"},{"why":"Stem (悪化し) + つつある langsung bisa memodifikasi kata benda (もんだい).","answer":0,"options":["悪化し つつある","悪化する つつある","悪化した つつある","悪化し つつあって"],"question":"Jika diletakkan sebelum kata benda ''環境（かんきょう = lingkungan）が ___ もんだい'', bentuk yang tepat adalah:"}],"forms":[{"id":"sedang meningkat perlahan","jp":"ふえつつある","label":"Pernyataan Tren","reading":"fue tsutsu aru"},{"id":"sedang terus bertambah","jp":"ふえつつあります","label":"Bahasa Laporan Sopan","reading":"fue tsutsu arimasu"},{"id":"masyarakat yang terus berubah","jp":"かわりつつある社会","label":"Menerangkan Benda","reading":"kawari tsutsu aru shakai"}],"steps":["Ambil kata kerja bermakna proses perubahan (seperti かわり-ます = berubah, へり-ます = berkurang, ふえ-ます = bertambah, かいふくし-ます = pulih).","Buang akhiran ます (dapat akarnya: かわり, へり, かいふくし).","Tempelkan つつある (atau bentuk sopan つつあります) tepat di belakangnya."],"analogy":"～つつある adalah versi formal dari ''sedang terus berlangsung / perlahan berubah menuju...''. Mirip versi berita atau jurnal dari ～てきている / ～ている.","mistakes":[{"why":"つつある hanya cocok untuk perubahan tren bertahap jangka agak panjang & bernada formal, bukan kegiatan harian singkat seperti nonton TV atau makan.","right":"いま テレビを みています","wrong":"いま テレビを みつつあります"},{"why":"Yang dipakai sebelum つつある wajib Stem Verba (bentuk ます tanpa ます), bukan bentuk kamus.","right":"ふえ つつある","wrong":"ふえる つつある"}],"breakdowns":[{"tokens":[{"jp":"けいざい","role":"subject","meaning":"ekonomi","reading":"keizai"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"かいふくし","role":"verb","meaning":"pulih (stem)","reading":"kaifuku shi"},{"jp":"つつあります","role":"ending","meaning":"sedang berangsur","reading":"tsutsu arimasu"}],"translation":"Perekonomian sedang berangsur pulih."},{"tokens":[{"jp":"まち","role":"noun","meaning":"kota","reading":"machi"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"けしき","role":"subject","meaning":"pemandangan","reading":"keshiki"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"すこしずつ","role":"adjective","meaning":"sedikit demi sedikit","reading":"sukoshi zutsu"},{"jp":"かわり","role":"verb","meaning":"berubah (stem)","reading":"kawari"},{"jp":"つつある","role":"ending","meaning":"sedang terus berlangsung","reading":"tsutsu aru"}],"translation":"Pemandangan kota perlahan sedang berubah sedikit demi sedikit."},{"tokens":[{"jp":"かつて","role":"time","meaning":"dahulu","reading":"katsute"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"ふるい","role":"adjective","meaning":"kuno","reading":"furui"},{"jp":"でんとう","role":"subject","meaning":"tradisi","reading":"dentou"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"うしなわれ","role":"verb","meaning":"hilang (pasif stem)","reading":"ushinaware"},{"jp":"つつある","role":"ending","meaning":"kian terkikis / menghilang","reading":"tsutsu aru"}],"translation":"Tradisi lama dari masa lalu kini perlahan mulai menghilang."}],"when_to_use":["Membaca atau menulis laporan berita (''ekonomi sedang berangsur membaik'', ''jumlah warga desa mulai menyusut'')","Menggambarkan tren perubahan yang sedang berproses saat ini","Menjelaskan kemajuan bertahap sebuah proyek (''pembangunan jembatan sedang terus berjalan'')"],"formula_parts":[{"role":"verb","text":"Stem Verba (Akar ます)","label":"Perubahan bertahap"},{"role":"ending","text":"つつある","label":"Sedang perlahan berlangsung"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000026', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-009', 'sentence_pattern', 'Bisa Saja Berakibat Buruk (~かねない)', '[Stem Verba] + かねない', 'Menyatakan kekhawatiran bahwa situasi sekarang berisiko memicu kejadian buruk.', 9, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Jika lalai mengecek, bisa saja memicu kecelakaan besar.","jp":"確認を 怠ると、大きな 事故に つながりかねない。","reading":"Kakunin o okotaru to, ookina jiko ni tsunagarikanenai."},{"id":"Jadwal yang dipaksakan berisiko merusak kualitas.","jp":"無理な スケジュールは 品質を 損ないかねません。","reading":"Murina sukejuuru wa hinshitsu o sokonaikanemasen."}]'::jsonb, '[Stem Verba] + kanenai', '{"quiz":[{"why":"Meski ada akhiran ない/ません, かねない/かねません artinya kekhawatiran hal buruk ''bisa saja terjadi''.","answer":1,"options":["Kalau terburu-buru seperti itu, tidak akan pernah salah","Kalau terburu-buru begitu, bisa-bisa nanti malah membuat kesalahan lho","Kita harus melakukan kesalahan","Sudah pasti gagal total"],"question":"Apa arti kalimat peringatan ''そんな いそぎかたでは、ミスを し かねませんよ''?"},{"why":"～かねる bermakna halus ''keberatan / tidak mampu melakukan'', sedangkan ～かねない bermakna ''berisiko berakibat buruk''.","answer":1,"options":["かねない (bisa saja menjawab - bahaya)","かねます (mohon maaf tidak sanggup/tidak bisa menjawab)","かねた (lupa menjawab)","かねるな (jangan jawab)"],"question":"Hati-hati pasangan jebakan di JLPT! Bedakan ～かねる vs ～かねない pada kalimat ''その しつもんには おこたえ し___'':"},{"why":"Khawatir ucapan dapat melukai hati seseorang (きずつけて しまい) adalah hal negatif yang sangat pas dengan かねない.","answer":1,"options":["テストに ごうかく し かねない","かのじょを きずつけて しまい かねない","きょねん １０万円 ひろい かねなかった","おいしい ので、また かい かねない"],"question":"Kalimat mana yang benar secara tata bahasa dan rasa?"}],"forms":[{"id":"bisa-bisa nanti terlambat","jp":"おくれかねない","label":"Kasual Peringatan","reading":"okure kanenai"},{"id":"berisiko memicu kecelakaan (sopan)","jp":"じこをおこしかねません","label":"Sopan","reading":"jiko o okoshi kanemasen"},{"id":"mohon maaf sulit/tidak bisa menjawab","jp":"おこたえしかねます","label":"Beda Arti: ～かねる","reading":"okotae shikanemasu"}],"steps":["Pastikan akibatnya adalah hal NEGATIF atau mengkhawatirkan (jangan pakai untuk hal bagus seperti menang hadiah!).","Ambil stem verba (misal: おこします → おこし, まちがえます → まちがえ, こわします → こわし).","Tambahkan かねない (hati-hati: walau diakhiri ない, artinya BUKAN negatif, melainkan POSITIF ''bisa saja terjadi''!)."],"analogy":"～かねない artinya ''Jangan-jangan bisa berakibat...'' atau ''Bisa saja ujung-ujungnya malah memicu hal buruk!''. Selalu bernada KEKHAWATIRAN bahwa kelalaian sekarang berisiko menimbulkan akibat negatif.","mistakes":[{"why":"～かねない hanya untuk kekhawatiran akibat BURUK; untuk hasil baik gunakan かもしれない atau そうだ.","right":"１００てんを とれる かもしれない","wrong":"まいにち べんきょうすれば、１００てんを とりかねない！"},{"why":"Selalu wajib memakai Stem Verba (tanpa ます), bukan bentuk kamus.","right":"おこし かねない","wrong":"おこす かねない"}],"breakdowns":[{"tokens":[{"jp":"そんな","role":"noun","meaning":"seperti itu","reading":"sonna"},{"jp":"スピード","role":"noun","meaning":"kecepatan","reading":"supiido"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"だすと","role":"verb","meaning":"kalau memacu","reading":"dasu to"},{"jp":"じこ","role":"object","meaning":"kecelakaan","reading":"jiko"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"おこし","role":"verb","meaning":"menimbulkan (stem)","reading":"okoshi"},{"jp":"かねない","role":"ending","meaning":"bisa-bisa memicu","reading":"kanenai"}],"translation":"Kalau mengebut segitu cepat, bisa-bisa memicu kecelakaan!"},{"tokens":[{"jp":"むり","role":"object","meaning":"memaksakan diri","reading":"muri"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"つづけると","role":"verb","meaning":"kalau terus","reading":"tsuzukeru to"},{"jp":"からだ","role":"object","meaning":"tubuh/kesehatan","reading":"karada"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"こわし","role":"verb","meaning":"merusak (stem)","reading":"kowashi"},{"jp":"かねません","role":"ending","meaning":"berisiko (sopan)","reading":"kanemasen"}],"translation":"Kalau terus memforsir diri, bisa-bisa merusak kesehatanmu!"},{"tokens":[{"jp":"誤解","role":"object","meaning":"kesalahpahaman","reading":"gokai"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"まねき","role":"verb","meaning":"mengundang (stem)","reading":"maneki"},{"jp":"かねない","role":"ending","meaning":"berisiko mengundang","reading":"kanenai"},{"jp":"いいかた","role":"noun","meaning":"cara bicara","reading":"iikata"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"さけたほうがいい","role":"verb","meaning":"sebaiknya dihindari","reading":"saketa hou ga ii"}],"translation":"Cara bicara yang berisiko mengundang kesalahpahaman sebaiknya dihindari."}],"when_to_use":["Mengingatkan bahaya atau risiko kerja (''kalau dibiarkan begini terus, perusahaan bisa bangkrut!'')","Memperingatkan dampak kesehatan/kecelakaan (''jangan ngebut, nanti bisa menimbulkan kecelakaan!'')","Komentar kritis di berita soal risiko kebijakan atau kebiasaan"],"formula_parts":[{"role":"verb","text":"Stem Verba (Akar ます)","label":"Peristiwa buruk yg ditakutkan"},{"role":"ending","text":"かねない","label":"Berisiko memicu / Bisa saja"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000027', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'GP-JA-N2-010', 'honorific', 'Ungkapan Hormat Peninggi (Sonkeigo Baku)', 'お + [Stem] + になる / Verba Khusus', 'Meninggikan posisi lawan bicara, klien, atau atasan dalam percakapan bisnis formal.', 10, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Bapak Direktur sudah pulang terlebih dahulu.","jp":"社長は すでに お帰りになりました。","reading":"Shachou wa sudeni okaeri ni narimashita."},{"id":"Apakah Anda berkenan melihat dokumen ini?","jp":"こちらの 資料を ご覧いただけますか。","reading":"Kochira no shiryou o goran itadakemasu ka."}]'::jsonb, 'o + [Stem] + ni naru / Verba Khusus', '{"quiz":[{"why":"まいります (Kenjougo untuk saya/tim sendiri); いらっしゃいましたか (Sonkeigo menghormati tindakan direktur).","answer":1,"options":["しゃちょうは もう まいりましたか","しゃちょうは もう いらっしゃいましたか","しゃちょうは もう おきますか","しゃちょうは もう おりましたか"],"question":"Klien bertanya kapan Bos datang ke kantor. Kalimat hormat untuk ''Apakah Direktur sudah datang?'' adalah:"},{"why":"Sonkeigo baku untuk makan/minum adalah kata kerja khusus めしあがります.","answer":1,"options":["おたべに なりましたか","めしあがりましたか","いただきましたか","おめしあがり しましたか"],"question":"Bagaimana menanyakan secara sangat sopan apakah guru sudah makan kue tersebut (たべます -> Sonkeigo)?"},{"why":"Untuk mempersilakan tamu/atasan melakukan sesuatu secara langsung, rumus manisnya adalah お + [Stem] + ください.","answer":0,"options":["Karena お～になる untuk aksi lawan bicara, dan bila mempersilakan langsung jauh lebih luwes pakai お[stem]ください!","Karena kata やすむ tidak punya stem","Karena ください lebih rendah","Karena 先生 tidak boleh istirahat"],"question":"Mengapa bentuk ''先生、おやすみに なってください'' kadang dihindari dan diganti ''ごゆっくり おやすみ ください''?"}],"forms":[{"id":"beliau membaca","jp":"およみになります","label":"Rumus Baku (お～になる)","reading":"oyomi ni narimasu"},{"id":"beliau ada / pergi / datang","jp":"いらっしゃいます","label":"Khusus: Pergi/Ada","reading":"irasshaimasu"},{"id":"beliau makan / minum","jp":"めしあがります","label":"Khusus: Makan/Minum","reading":"meshiagarimasu"},{"id":"beliau mengatakan","jp":"おっしゃいます","label":"Khusus: Berkata","reading":"osshaimasu"}],"steps":["Pastikan pelakunya adalah ATASAN, KLIEN, atau TAMU — jangan pernah memakai pola ini untuk tindakan diri sendiri!","Rumus baku: お + [Stem Verba] + になる (contoh: かきます → おかきになる, みます → *tidak cocok! Pakai kata khusus*).","WAJIB hafal 6 kata kerja khusus Sonkeigo karena tidak memakai rumus お～になる: pergi/datang/ada → いらっしゃる, makan/minum → めしあがる, melihat → ごらんになる, berkata → おっしゃる, melakukan → なさる, tahu → ごぞんじだ."],"analogy":"Sonkeigo adalah bahasa meninggikan lawan bicara — ibarat berkata ''Beliau berkenan melakukan...''. Kalau di N4 kita pakai Kenjougo untuk MERENDAHKAN diri sendiri, Sonkeigo khusus untuk MENGHORMATI tindakan atasan, klien, atau tamu!","mistakes":[{"why":"Sonkeigo adalah penghormatan peninggi! Memakainya untuk DIRI SENDIRI adalah kesalahan fatal etiket Jepang.","right":"わたしは あした かえります (atau まいります)","wrong":"わたしは あした おかえりになります"},{"why":"Kata kerja みます dan beberapa kata 1 suku kata lain tidak memakai お～になる, melainkan punya bentuk khusus ごらんになる.","right":"ごらんに なりました","wrong":"おみに なりました (untuk melihat)"}],"breakdowns":[{"tokens":[{"jp":"しゃちょう","role":"topic","meaning":"Direktur","reading":"shachou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"もう","role":"time","meaning":"sudah","reading":"mou"},{"jp":"おかえりに","role":"verb","meaning":"pulang","reading":"okaeri ni"},{"jp":"なりましたか","role":"ending","meaning":"apakah (hormat)?","reading":"narimashita ka"}],"translation":"Apakah Bapak Direktur sudah pulang?"},{"tokens":[{"jp":"こちら","role":"place","meaning":"sebelah sini","reading":"kochira"},{"jp":"で","role":"particle","meaning":"di","reading":"de"},{"jp":"どうぞ","role":"connector","meaning":"silakan","reading":"douzo"},{"jp":"おかけに","role":"verb","meaning":"duduk","reading":"okake ni"},{"jp":"なって","role":"ending","meaning":"silakan (TE hormat)","reading":"natte"},{"jp":"ください","role":"ending","meaning":"tolong","reading":"kudasai"}],"translation":"Silakan berkenan duduk di sebelah sini."},{"tokens":[{"jp":"せんせい","role":"topic","meaning":"Guru/Profesor","reading":"sensei"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"ほん","role":"object","meaning":"buku","reading":"hon"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"ごらんに","role":"verb","meaning":"membaca/melihat (khusus)","reading":"goran ni"},{"jp":"なりました","role":"ending","meaning":"(sangat hormat)","reading":"narimashita"}],"translation":"Profesor sudah berkenan membaca/melihat buku ini."}],"when_to_use":["Menanyakan kabar atau rencana atasan/klien (''apakah Bapak sudah makan?'', ''jam berapa Ibu tiba?'')","Memberi petunjuk atau mempersilakan tamu secara sangat sopan (''silakan tunggu sebentar'', ''silakan melihat-lihat'')","Melaporkan tindakan atasan ke rekan atau tamu luar"],"formula_parts":[{"role":"particle","text":"お / ご","label":"Awalan hormat"},{"role":"verb","text":"Stem Verba","label":"Tindakan lawan bicara"},{"role":"ending","text":"になる / Verba Khusus","label":"Bentuk meninggikan (Sonkeigo)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000008', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-001', 'sentence_pattern', 'Berusaha Membiasakan Diri (~ようにする)', '[Kamus Verba / Bentuk-NAI] + ようにする', 'Menyatakan usaha sadar dan konsisten untuk membiasakan suatu perilaku.', 1, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Saya membiasakan diri berolahraga 30 menit setiap hari.","jp":"毎日 30分 運動するように しています。","reading":"Mainichi sanjuppun undou suru you ni shite imasu."},{"id":"Saya berhati-hati agar tidak terlambat.","jp":"遅刻しないように 気をつけます。","reading":"Chikoku shinai you ni ki o tsukemasu."}]'::jsonb, '[Kamus Verba / Bentuk-NAI] + you ni suru', '{"quiz":[{"why":"Sebelum ようにする / ようにしている memakai bentuk kamus (のむ).","answer":1,"options":["まいあさ おみずを のんだ ようにしています","まいあさ おみずを のむ ようにしています","まいあさ おみずを のみ ようにしています","まいあさ おみずを のんで ようにしています"],"question":"Bagaimana mengatakan ''Saya berusaha rutin minum air putih setiap pagi''?"},{"why":"ようにしています menggambarkan kebiasaan yang memang sedang rutin diupayakan dalam hidup sehari-hari.","answer":0,"options":["～ようにしています menyatakan kebiasaan usaha yang terus dijalankan rutin sekarang","～ようにしています artinya sudah berhenti berusaha","～ようにしています hanya untuk orang ketiga","Keduanya terlarang dipakai di masa sekarang"],"question":"Bedanya ～ようにしています dibanding ～ようにします dalam aktivitas sehari-hari adalah:"},{"why":"Bentuk-NAI diletakkan sebelum ようにします: しない ようにします.","answer":0,"options":["よふかし しない ようにします","よふかし する ようにしません","よふかし なかった ようにします","よふかし しなかった ようにします"],"question":"Cara berkata ''Saya usahakan tidak begadang (ねおそくならない / よふかししない)'' adalah:"}],"forms":[{"id":"berusaha rutin olahraga","jp":"うんどうするようにしています","label":"Membiasakan (+)","reading":"undou suru you ni shite imasu"},{"id":"berusaha tidak lupa","jp":"わすれないようにします","label":"Menghindari (-)","reading":"wasurenai you ni shimasu"},{"id":"usahakan selalu berhati-hati","jp":"きをつけるようにしてください","label":"Imbauan","reading":"ki o tsukeru you ni shite kudasai"}],"steps":["Ambil kata kerja bentuk dasar kamus (misal: のむ, ねる) atau Bentuk-NAI kalau tujuannya menghindari (おくれない, たべすぎない).","Tambahkan ようにします di belakangnya untuk menyatakan niat membiasakan.","Kalau mau bilang sudah mulai membiasakan sejak lama, ubah akhirnya ke ようにしています (''saya terbiasa berusaha...'')."],"analogy":"～ようにする artinya ''berusaha membiasakan diri untuk...'' atau ''usahakan supaya jangan...''. Beda dari sekadar janji sekali jadi, pola ini menekankan ikhtiar sadar yang diulang pelan-pelan tiap hari.","mistakes":[{"why":"Kata kerja bentuk kamus (suru) atau Bentuk-NAI wajib ada sebelum ようにする, bukan kata benda telanjang.","right":"まいにち うんどう する ようにします","wrong":"まいにち うんどう ようにします"},{"why":"～ようにする dipakai bersama aksi yang bisa dikendalikan oleh niat/usaha sendiri (okiru = bangun), bukan hasil di luar kendali.","right":"あした ５じに おきる ようにします","wrong":"あした ５じに おきられる ようにします"}],"breakdowns":[{"tokens":[{"jp":"まいにち","role":"time","meaning":"setiap hari","reading":"mainichi"},{"jp":"やさい","role":"object","meaning":"sayur-sayuran","reading":"yasai"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"たべる","role":"verb","meaning":"makan (kamus)","reading":"taberu"},{"jp":"ようにしています","role":"ending","meaning":"berusaha membiasakan","reading":"you ni shite imasu"}],"translation":"Saya membiasakan diri makan sayur setiap hari."},{"tokens":[{"jp":"かいぎ","role":"place","meaning":"rapat","reading":"kaigi"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"おくれない","role":"verb","meaning":"tidak terlambat (NAI)","reading":"okurenai"},{"jp":"ようにします","role":"ending","meaning":"berusaha agar tidak","reading":"you ni shimasu"}],"translation":"Saya berusaha supaya tidak terlambat rapat."},{"tokens":[{"jp":"ねる","role":"verb","meaning":"tidur","reading":"neru"},{"jp":"まえに","role":"time","meaning":"sebelum","reading":"mae ni"},{"jp":"スマホ","role":"object","meaning":"ponsel","reading":"sumaho"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"みない","role":"verb","meaning":"tidak melihat (NAI)","reading":"minai"},{"jp":"ようにしてください","role":"ending","meaning":"usahakan untuk","reading":"you ni shite kudasai"}],"translation":"Usahakan jangan main ponsel sebelum tidur ya."}],"when_to_use":["Menetapkan resolusi hidup sehat atau belajar rutin (''usahakan tidur cukup tiap hari'')","Berusaha meninggalkan kebiasaan buruk (''berusaha untuk tidak telat'')","Memberi imbauan atau aturan ke orang lain agar menjaga suatu kebiasaan"],"formula_parts":[{"role":"verb","text":"Kamus Verba / Bentuk-NAI","label":"Kebiasaan yang dituju"},{"role":"ending","text":"ようにする","label":"Berusaha membiasakan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000009', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-002', 'sentence_pattern', 'Keputusan Organisasi / Jadwal Resmi (~ことになる)', '[Kamus Verba] + ことになる', 'Menyatakan keputusan yang ditetapkan oleh pihak luar, kantor, atau situasi (bukan kehendak pribadi semata).', 2, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Diputuskan bahwa mulai bulan depan saya bekerja di kantor pusat Tokyo.","jp":"来月から 東京本社で 働くことに なりました。","reading":"Raigetsu kara Toukyou honsha de hataraku koto ni narimashita."},{"id":"Rapat dijadwalkan berlangsung secara daring.","jp":"会議は オンラインで 行うことに なっています。","reading":"Kaigi wa onrain de okonau koto ni natte imasu."}]'::jsonb, '[Kamus Verba] + koto ni naru', '{"quiz":[{"why":"Keputusan dari atasan atau perusahaan disampaikan dengan ～ことになりました.","answer":0,"options":["おおさかで はたらく ことになりました","おおさかで はたらく ようにしました","おおさかで はたらいた ことにしました","おおさかで はたらく つもりになりました"],"question":"Kantor menugaskanmu pindah ke cabang Osaka bulan depan. Kalimat yang paling pas disampaikan ke teman adalah:"},{"why":"～ことになっています menekankan status aturan/sistem yang saat ini berlaku resmi.","answer":1,"options":["Baru rencana pribadi","Sudah ditetapkan sebagai aturan atau jadwal resmi berlaku","Kemungkinan batal","Harapan di masa depan"],"question":"Apa makna pola ～ことになっています pada pengumuman sekolah atau jadwal kantor?"},{"why":"ことにする = memutuskan sendiri; ことになる = diputuskan oleh situasi/organisasi.","answer":1,"options":["ことになりました","ことにしました","Keduanya mutlak aturan luar","Keduanya keputusan pribadi"],"question":"Bandingkan ことにしました vs ことになりました. Mana yang keputusan pribadi?"}],"forms":[{"id":"diputuskan akan pergi","jp":"いくことになりました","label":"Keputusan Baru","reading":"iku koto ni narimashita"},{"id":"diputuskan tidak jadi pergi","jp":"いかないことになりました","label":"Batal / Tidak Jadi","reading":"ikanai koto ni narimashita"},{"id":"aturannya mulai jam 9 pagi","jp":"あさ９じにはじまることになっています","label":"Aturan Resmi Tetap","reading":"asa kuji ni hajimaru koto ni natte imasu"}],"steps":["Tentukan aksi yang diputuskan dalam bentuk kamus (atau Bentuk-NAI jika diputuskan untuk TIDAK dilakukan).","Tambahkan ことになりました / ことになっています bila sudah menjadi aturan tetap atau jadwal resmi.","Bandingkan: kalau dirimu sendiri yang memutuskan secara pribadi, pakailah ～ことにする; kalau dari rapat/pihak luar, pakai ～ことになる."],"analogy":"～ことになる artinya ''sudah diputuskan bahwa...'' atau ''jadinya diputuskan begini...'' oleh kantor, sekolah, atau aturan bersama — jadi kesannya keputusan itu bukan semata-mata maumu sendiri.","mistakes":[{"why":"Kalau itu keputusan/tekad dirimu sendiri, gunakan ことにしました. ことになりました menunjukkan pihak lain/aturan yang memutuskan.","right":"まいにち １じかん はしる ことにしました","wrong":"まいにち １じかん はしる ことになりました (tekad pribadi)"},{"why":"Sebelum ことになる umumnya pakai bentuk non-lampau (bentuk kamus / Bentuk-NAI), walau keputusannya di masa lalu (narimashita).","right":"しゅっちょう する ことになりました","wrong":"しゅっちょう した ことになりました"}],"breakdowns":[{"tokens":[{"jp":"らいげつ","role":"time","meaning":"bulan depan","reading":"raigetsu"},{"jp":"東京","role":"place","meaning":"Tokyo","reading":"Toukyou"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"しゅっちょうする","role":"verb","meaning":"dinas luar (kamus)","reading":"shucchou suru"},{"jp":"ことになりました","role":"ending","meaning":"sudah diputuskan","reading":"koto ni narimashita"}],"translation":"Diputuskan bahwa bulan depan saya dinas ke Tokyo."},{"tokens":[{"jp":"かいぎ","role":"subject","meaning":"rapat","reading":"kaigi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ちゅうしに","role":"noun","meaning":"batal / dibatalkan","reading":"chuushi ni"},{"jp":"なる","role":"verb","meaning":"menjadi","reading":"naru"},{"jp":"ことになりました","role":"ending","meaning":"akhirnya diputuskan","reading":"koto ni narimashita"}],"translation":"Rapatnya diputuskan untuk dibatalkan."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"ビル","role":"place","meaning":"gedung","reading":"biru"},{"jp":"の","role":"particle","meaning":"(di)","reading":"no"},{"jp":"なか","role":"place","meaning":"dalam","reading":"naka"},{"jp":"では","role":"particle","meaning":"di area","reading":"de wa"},{"jp":"たばこ","role":"object","meaning":"rokok","reading":"tabako"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"すわない","role":"verb","meaning":"tidak merokok","reading":"suwanai"},{"jp":"ことになっています","role":"ending","meaning":"sudah menjadi aturan","reading":"koto ni natte imasu"}],"translation":"Aturannya di dalam gedung ini dilarang merokok."}],"when_to_use":["Mengumumkan penugasan kerja, mutasi cabang, atau jadwal perjalanan dinas","Menyampaikan keputusan rapat atau aturan baru perusahaan/kampus","Bercerita sopan mengenai perubahan rencana hidup (seperti jadi menikah atau pindah ke Jepang)"],"formula_parts":[{"role":"verb","text":"Kamus Verba / Bentuk-NAI","label":"Isi keputusan"},{"role":"ending","text":"ことになる / ことになった","label":"Sudah diputuskan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000010', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-003', 'sentence_pattern', 'Berkat Sesuatu (~おかげで)', '[Nomina + の / Bentuk Biasa] + おかげで', 'Menyatakan akibat positif yang terjadi berkat bantuan seseorang atau kondisi baik.', 3, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Berkat senior, saya cepat terbiasa dengan pekerjaan.","jp":"先輩のおかげで、仕事に 早く 慣れました。","reading":"Senpai no okage de, shigoto ni hayaku naremashita."},{"id":"Berkat mengulang materi tiap hari, saya lulus ujian.","jp":"毎日 復習したおかげで、試験に 合格しました。","reading":"Mainichi fukushuu shita okage de, shiken ni goukaku shimashita."}]'::jsonb, '[Nomina + no / Bentuk Biasa] + okage de', '{"quiz":[{"why":"みんな adalah kata benda/pronomina sehingga memakai の, dan hasilnya positif memakai おかげで.","answer":0,"options":["の おかげで","な おかげで","の せいで","から おかげで"],"question":"Lengkapi: ''みんな ___、たのしい りょこうに なりました'' (Berkat semuanya, jadi wisata yang menyenangkan):"},{"why":"Hanya pilihan ke-3 yang menunjukkan situasi selamat/baik berkat ayah.","answer":2,"options":["かぜの おかげで ねつが でました","しごとの おかげで とても つかれました","ちちの おかげで だいじょうぶ でした","ねぼうの おかげで ちこく しました"],"question":"Kalimat mana yang pemakaian おかげで-nya PALING TEPAT?"},{"why":"Sifat-Na memakai な di depan おかげで (べんりな おかげで).","answer":2,"options":["べんりの おかげで","べんりだ おかげで","べんりな おかげで","べんりで おかげで"],"question":"Bagaimana menyambungkan Kata Sifat-Na seperti べんり (praktis) dengan おかげで?"}],"forms":[{"id":"ini semua berkat kalian","jp":"みなさんのおかげです","label":"Kata Benda (+の)","reading":"minasan no okage desu"},{"id":"berkat sudah minum obat","jp":"くすりをのんだおかげで","label":"Verba Lampau","reading":"kusuri o nonda okage de"},{"id":"berkat kondisi yang sehat","jp":"げんきなおかげで","label":"Sifat-Na (+な)","reading":"genki na okage de"}],"steps":["Cek apakah hasilnya baik/positif! Jika hasilnya rugi atau buruk, pakai せいで (''gara-gara''), bukan おかげで.","Kalau penyebabnya Kata Benda, tambahkan の (contoh: せんせい の おかげで).","Kalau penyebabnya Kata Sifat-Na, tambahkan な (contoh: べんりな おかげで); kalau verba/sifat-i langsung Bentuk Biasa."],"analogy":"～おかげで persis kata ''Berkat...'' dalam bahasa Indonesia! Wajib dipakai HANYA kalau hasilnya POSITIF dan kamu mau berterima kasih atas penyebabnya.","mistakes":[{"why":"Pertandingan batal akibat topan adalah kejadian buruk, jadi jangan pakai おかげで (kecuali bermaksud sarkas/mengejek!).","right":"たいふうの せいで、しあいが ちゅうしに なりました","wrong":"たいふうの おかげで、しあいが ちゅうしに なりました"},{"why":"Setelah kata benda (ともだち) wajib disisipkan partikel の sebelum おかげで.","right":"ともだち の おかげで、たすかりました","wrong":"ともだち おかげで、たすかりました"}],"breakdowns":[{"tokens":[{"jp":"せんせい","role":"noun","meaning":"guru","reading":"sensei"},{"jp":"の","role":"particle","meaning":"(penghubung)","reading":"no"},{"jp":"おかげで","role":"connector","meaning":"berkat","reading":"okage de"},{"jp":"ごうかくしました","role":"verb","meaning":"lulus ujian","reading":"goukaku shimashita"}],"translation":"Berkat guru, saya lulus ujian."},{"tokens":[{"jp":"はやめに","role":"time","meaning":"lebih awal","reading":"hayame ni"},{"jp":"しゅっぱつした","role":"verb","meaning":"berangkat (lampau)","reading":"shuppatsu shita"},{"jp":"おかげで","role":"connector","meaning":"berkat","reading":"okage de"},{"jp":"ひこうき","role":"noun","meaning":"pesawat","reading":"hikouki"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"まにあいました","role":"verb","meaning":"sempat terkejar","reading":"maniaimashita"}],"translation":"Berkat berangkat lebih awal, saya sempat naik pesawat."},{"tokens":[{"jp":"インターネット","role":"noun","meaning":"internet","reading":"intaanetto"},{"jp":"の","role":"particle","meaning":"(penghubung)","reading":"no"},{"jp":"おかげで","role":"connector","meaning":"berkat","reading":"okage de"},{"jp":"どこにいても","role":"place","meaning":"di mana pun","reading":"doko ni ite mo"},{"jp":"日本語","role":"object","meaning":"bahasa Jepang","reading":"nihongo"},{"jp":"が","role":"particle","meaning":"(objek)","reading":"ga"},{"jp":"べんきょうできます","role":"verb","meaning":"bisa belajar","reading":"benkyou dekimasu"}],"translation":"Berkat internet, di mana pun berada kita bisa belajar bahasa Jepang."}],"when_to_use":["Berterima kasih karena bantuan teman, guru, atau mentor (''berkat bantuanmu saya lulus'')","Bersyukur atas cuaca cerah atau alat yang memudahkan pekerjaan","Melaporkan kesuksesan hasil positif ke atasan secara sopan"],"formula_parts":[{"role":"noun","text":"Nomina の / Bentuk Biasa (+ な u/ Sifat-Na)","label":"Penyebab baik"},{"role":"connector","text":"おかげで","label":"Berkat"},{"role":"predicate","text":"Hasil Positif","label":"Kesuksesan / lega"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000011', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-004', 'sentence_pattern', 'Gara-gara / Akibat Buruk (~せいで)', '[Nomina + の / Bentuk Biasa] + せいで', 'Menyatakan akibat negatif yang disebabkan oleh sesuatu atau kesalahan tertentu.', 4, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Gara-gara topan, penerbangannya dibatalkan.","jp":"台風のせいで、飛行機が 欠航に なりました。","reading":"Taifuu no sei de, hikouki ga kekkou ni narimashita."},{"id":"Akibat kurang tidur, kepala saya sakit.","jp":"寝不足のせいで、頭が 痛いです。","reading":"Nebusoku no sei de, atama ga itai desu."}]'::jsonb, '[Nomina + no / Bentuk Biasa] + sei de', '{"quiz":[{"why":"Kejadian minum kopinya sudah terjadi (lampau), sehingga memakai Bentuk-TA (のんだ).","answer":1,"options":["のむ","のんだ","のみ","のんで"],"question":"Lengkapi: ''きのうの よる コーヒーを ___ せいで、ねむれませんでした'' (Gara-gara minum kopi tadi malam, tidak bisa tidur):"},{"why":"[Orang] の せいです dipakai untuk mengakui tanggung jawab kesalahan.","answer":1,"options":["Semua ini berkat usaha saya","Semua ini kesalahan/gara-gara saya, maaf","Saya tidak tahu salah siapa","Mari kita selesaikan bersama"],"question":"Apa arti kalimat ''ぜんぶ わたしの せいです。すみません''?"},{"why":"Sakit tenggorokan akibat mendadak dingin adalah akibat negatif, sangat pas dengan せいで.","answer":1,"options":["あつい せいで アイスクリームが おいしい","きゅうに さむくなった せいで のどが いたい","おかあさんの せいで げんきに なりました","バスが はやい せいで たすかりました"],"question":"Pilih kalimat yang cocok memakai ～せいで:"}],"forms":[{"id":"gara-gara hujan","jp":"あめのせいで","label":"Kata Benda (+の)","reading":"ame no sei de"},{"id":"gara-gara ketiduran","jp":"ねぼうしたせいで","label":"Verba Lampau","reading":"nebou shita sei de"},{"id":"ini salah saya","jp":"わたしのせいです","label":"Akhir Kalimat","reading":"watashi no sei desu"}],"steps":["Pastikan akibat di belakang kalimat bernada negatif atau tidak diharapkan.","Sambungkan penyusun kalimatnya sama persis seperti aturan おかげで: Kata Benda + の, Sifat-Na + な, Verba/Sifat-I Bentuk Biasa.","Akhiri kalimat dengan hasil buruk yang terjadi (atau tutup di akhir dengan ～のせいです = ''ini gara-gara...'')."],"analogy":"～せいで adalah kebalikan persis dari おかげで — artinya ''Gara-gara...'' atau ''Akibat...''. Selalu dipakai ketika hasilnya BURUK, merugikan, atau menyebalkan.","mistakes":[{"why":"Lulus ujian itu hal menggembirakan! Selalu gunakan おかげで untuk hasil positif.","right":"がんばった おかげで、JLPTに うかりました","wrong":"がんばった せいで、JLPTに うかりました"},{"why":"Sifat-Na di depan せいで tidak pakai だ, melainkan berubah ke な.","right":"たいへん な せいで","wrong":"たいへん だ せいで"}],"breakdowns":[{"tokens":[{"jp":"じゅうたい","role":"noun","meaning":"macet","reading":"juutai"},{"jp":"の","role":"particle","meaning":"(penghubung)","reading":"no"},{"jp":"せいで","role":"connector","meaning":"gara-gara","reading":"sei de"},{"jp":"おくれました","role":"verb","meaning":"terlambat","reading":"okuremashita"}],"translation":"Gara-gara macet, saya terlambat."},{"tokens":[{"jp":"エアコン","role":"object","meaning":"AC","reading":"eakon"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"つけっぱなしにした","role":"verb","meaning":"membiarkan menyala","reading":"tsukeppanashi ni shita"},{"jp":"せいで","role":"connector","meaning":"gara-gara","reading":"sei de"},{"jp":"かぜ","role":"object","meaning":"masuk angin","reading":"kaze"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"ひきました","role":"verb","meaning":"terkena","reading":"hikimashita"}],"translation":"Gara-gara membiarkan AC menyala semalaman, saya masuk angin."},{"tokens":[{"jp":"きょねん","role":"time","meaning":"tahun lalu","reading":"kyonen"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"あめ","role":"subject","meaning":"hujan","reading":"ame"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ふらなかった","role":"verb","meaning":"tidak turun","reading":"furanakatta"},{"jp":"せいで","role":"connector","meaning":"akibat","reading":"sei de"},{"jp":"やさい","role":"subject","meaning":"sayuran","reading":"yasai"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"たかくなりました","role":"adjective","meaning":"menjadi mahal","reading":"takaku narimashita"}],"translation":"Akibat tahun lalu tidak turun hujan, harga sayur jadi mahal."}],"when_to_use":["Menjelaskan kenapa sesuatu gagal, rusak, terlambat, atau sakit (''gara-gara begadang, ketiduran'')","Mengeluh soal cuaca buruk atau macet yang bikin rencana berantakan","Membela diri menjelaskan kesalahan (catatan: hati-hati jangan terlalu menyalahkan orang lain langsung di kantor!)"],"formula_parts":[{"role":"noun","text":"Nomina の / Bentuk Biasa (+ な u/ Sifat-Na)","label":"Penyebab buruk"},{"role":"connector","text":"せいで","label":"Gara-gara / Akibat"},{"role":"predicate","text":"Akibat Buruk","label":"Kerugian / Kesalahan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000012', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-005', 'particle', 'Kepada / Terhadap (~に対して)', '[Nomina] + に対して', 'Menunjukkan sasaran sikap, tindakan, atau perbandingan terhadap dua pihak.', 5, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Menggunakan bahasa yang sopan terhadap pelanggan.","jp":"お客様に対して 丁寧な 言葉を使います。","reading":"Okyakusama ni taishite teineina kotoba o tsukaimasu."},{"id":"Berbeda dengan perkotaan yang praktis, daerah pinggiran tenang.","jp":"都市部は 便利なのに 対して、地方は 静かだ。","reading":"Toshibu wa benrina no ni taishite, chihou wa shizuka da."}]'::jsonb, '[Nomina] + ni taishite', '{"quiz":[{"why":"Untuk memodifikasi kata benda (たいさく) di belakangnya, pakailah bentuk kamus に対する.","answer":1,"options":["に対して","に対する","に対しての","を対して"],"question":"Pilih bentuk penyambung ke kata benda untuk ''kebijakan terhadap masalah ini (この もんだい ___ たいさく)'':"},{"why":"Saat menghubungkan dua fakta yang berlawanan sifatnya, に対して berarti ''berbanding terbalik / sedangkan''.","answer":1,"options":["Menunjukkan perasaan sayang ke Hokkaido","Membandingkan dua situasi yang kontras (panas vs sejuk)","Menyatakan sebab akibat","Memberi perintah"],"question":"Dalam kalimat ''とうきょうは あついのにたいして、ほっかいどうは すずしいです'', fungsi のに対して adalah:"},{"why":"Pola bakunya selalu memakai partikel に sebelum たいして.","answer":0,"options":["ぶかに たいして きびしい じょうし","ぶかを たいして きびしい じょうし","ぶかで たいして きびしい じょうし","ぶかへ たいして きびしい じょうし"],"question":"Manakah kalimat yang tepat mengenai etika kerja?"}],"forms":[{"id":"ramah terhadap semua orang","jp":"みんなに対してやさしい","label":"Sikap kepada Sasaran","reading":"minna ni taishite yasashii"},{"id":"keluhan terhadap pemerintah","jp":"せいふに対するふまん","label":"Menerangkan Benda","reading":"seifu ni taisuru fuman"},{"id":"sementara A..., sebaliknya B...","jp":"Aなのに対してBは","label":"Perbandingan Kontras","reading":"A na no ni taishite B wa"}],"steps":["Taruh pihak sasaran atau topik yang dituju di depan pola (seperti おきゃくさん, しつもん).","Tambahkan に対して jika setelahnya berupa kalimat lengkap / sifat / kata kerja.","Kalau mau menerangkan kata benda di belakangnya (seperti ''sikap terhadap pelanggan''), ubah ekornya menjadi に対する + Kata Benda!"],"analogy":"～に対して artinya bisa ''terhadap / kepada (sikap kita ke orang/topik)'' ATAU ''sedangkan / berbanding terbalik dengan... (membandingkan dua kubu yang kontras)''.","mistakes":[{"why":"Bila langsung disambung ke kata benda (いけん = pendapat), gunakan ～に対する [Kata Benda], bukan ～に対しての.","right":"けいかく に たいする いけん","wrong":"けいかく に対して の いけん"},{"why":"Partikel depannya selalu に (ni taishite), bukan を.","right":"しつもん に たいして こたえる","wrong":"しつもん を たいして こたえる"}],"breakdowns":[{"tokens":[{"jp":"おきゃくさん","role":"noun","meaning":"pelanggan","reading":"okyakusan"},{"jp":"に対して","role":"particle","meaning":"terhadap","reading":"ni taishite"},{"jp":"ていねいに","role":"adjective","meaning":"dengan sopan","reading":"teinei ni"},{"jp":"はなします","role":"verb","meaning":"berbicara","reading":"hanashimasu"}],"translation":"Berbicara dengan sopan kepada/terhadap pelanggan."},{"tokens":[{"jp":"かれ","role":"topic","meaning":"dia (lk)","reading":"kare"},{"jp":"の","role":"particle","meaning":"(milik)","reading":"no"},{"jp":"しつもん","role":"noun","meaning":"pertanyaan","reading":"shitsumon"},{"jp":"に対して","role":"particle","meaning":"atas / terhadap","reading":"ni taishite"},{"jp":"すぐ","role":"time","meaning":"langsung","reading":"sugu"},{"jp":"こたえました","role":"verb","meaning":"menjawab","reading":"kotaemashita"}],"translation":"Langsung menjawab terhadap pertanyaannya."},{"tokens":[{"jp":"あに","role":"topic","meaning":"kakak laki-laki","reading":"ani"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"しずか","role":"adjective","meaning":"pendiam","reading":"shizuka"},{"jp":"なのに対して","role":"connector","meaning":"sedangkan sebaliknya","reading":"na no ni taishite"},{"jp":"おとうと","role":"subject","meaning":"adik laki-laki","reading":"otouto"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"にぎやか","role":"adjective","meaning":"ramai / ceria","reading":"nigiyaka"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Kakaknya pendiam, sedangkan sebaliknya adiknya sangat ceria."}],"when_to_use":["Menjelaskan sikap seseorang kepada pelanggan, bawahan, atau hewan (''ramah terhadap tamu'')","Menyatakan respons/tindakan atas suatu pertanyaan atau kritik (''menjawab pertanyaan tersebut'')","Membandingkan dua hal yang bertolak belakang (''kakak pendiam, sebaliknya adiknya ceria'')"],"formula_parts":[{"role":"noun","text":"Nomina (Sasaran / Hal 1)","label":"Pihak yang dituju / dibanding"},{"role":"particle","text":"に対して / に対する","label":"Terhadap / Sebaliknya"},{"role":"predicate","text":"Sikap / Klausa Kontras","label":"Tindakan atau pembanding"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000013', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-006', 'tense', 'Mumpung / Selagi (~うちに)', '[Keadaan Sekarang] + うちに', 'Melakukan sesuatu sebelum kondisi yang ada sekarang berubah.', 6, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Selagi masih hangat, silakan dinikmati.","jp":"熱いうちに、どうぞ 召し上がってください。","reading":"Atsui uchi ni, douzo meshiagatte kudasai."},{"id":"Mumpung masih di Jepang, saya ingin melihat banyak tempat.","jp":"日本に いるうちに、いろいろな 場所を 見たいです。","reading":"Nihon ni iru uchi ni, iroirona basho o mitai desu."}]'::jsonb, '[Keadaan Sekarang] + uchi ni', '{"quiz":[{"why":"''Mumpung belum terjadi'' memakai Bentuk-NAI (ふらない) + うちに.","answer":2,"options":["ふる","ふった","ふらない","ふって"],"question":"Lengkapi: ''あめが ___ うちに、はやく うちへ かえりましょう'' (Mumpung belum turun hujan, ayo cepat pulang):"},{"why":"Kata Benda selalu membutuhkan の di depan うちに (どくしん の うちに).","answer":1,"options":["どくしん な うちに","どくしん の うちに","どくしん で うちに","どくしん だ うちに"],"question":"Bagaimana menghubungkan 独身 (どくしん = masih lajang, Kata Benda) dengan うちに?"},{"why":"Ketika dipakai dengan Bentuk ～ている + うちに, bisa menggambarkan kejadian tak terduga yang timbul selama kondisi itu berlangsung.","answer":1,"options":["Saya sengaja mendengarkan musik supaya bangun","Tanpa sadar ketiduran di tengah-tengah mendengarkan musik","Setelah tidur baru mendengarkan musik","Saya dilarang tidur saat dengar musik"],"question":"Dalam kalimat ''おんがくを きいている うちに、ねむってしまいました'', apa maknanya?"}],"forms":[{"id":"mumpung masih muda","jp":"わかい うちに","label":"Sifat-I","reading":"wakai uchi ni"},{"id":"mumpung hari belum gelap","jp":"くらくならない うちに","label":"Belum (NAI)","reading":"kuraku naranai uchi ni"},{"id":"selagi masih jam istirahat siang","jp":"ひるやすみ の うちに","label":"Kata Benda (+の)","reading":"hiruyasumi no uchi ni"}],"steps":["Pasangkan di depan うちに: Verba ～ている / ～ない (''selagi belum...''), Sifat-I tetap, Sifat-Na + な, Kata Benda + の.","Kombinasi favorit yang sering keluar di ujian: Bentuk-NAI + うちに = ''selagi belum / mumpung belum'' (contoh: わすれない うちに = mumpung belum lupa).","Di bagian belakangnya, taruh ajakan, tekad, atau perubahan yang berlangsung selagi kondisi awal masih aktif."],"analogy":"～うちに artinya persis kata ''Mumpung...'' atau ''Selagi...''. Maksudnya: lakukanlah sesuatu SEKARANG mumpung situasinya masih mendukung, sebelum terlambat atau keburu berubah!","mistakes":[{"why":"うちに membutuhkan kondisi yang SEDANG berlangsung atau BELUM berubah; ''sebelum jam 5'' berarti kondisinya masih ''belum menjadi jam 5'' (naranai uchi ni).","right":"５じに ならない うちに、かえりましょう","wrong":"５じに なる うちに、かえりましょう"},{"why":"Sifat-Na wajib menyisipkan な sebelum うちに (genki na uchi ni).","right":"げんき な うちに、あそぼう","wrong":"げんき うちに、あそぼう"}],"breakdowns":[{"tokens":[{"jp":"あたたかい","role":"adjective","meaning":"hangat","reading":"atatakai"},{"jp":"うちに","role":"connector","meaning":"mumpung masih","reading":"uchi ni"},{"jp":"どうぞ","role":"connector","meaning":"silakan","reading":"douzo"},{"jp":"たべてください","role":"verb","meaning":"makanlah","reading":"tabete kudasai"}],"translation":"Silakan dimakan selagi masih hangat!"},{"tokens":[{"jp":"わすれない","role":"verb","meaning":"belum lupa (NAI)","reading":"wasurenai"},{"jp":"うちに","role":"connector","meaning":"mumpung","reading":"uchi ni"},{"jp":"メモ","role":"object","meaning":"catatan","reading":"memo"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"とっておきます","role":"verb","meaning":"saya catat dulu","reading":"totte okimasu"}],"translation":"Mumpung belum lupa, saya catat dulu ya."},{"tokens":[{"jp":"にほん","role":"place","meaning":"Jepang","reading":"Nihon"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"いる","role":"verb","meaning":"berada","reading":"iru"},{"jp":"うちに","role":"connector","meaning":"selagi masih","reading":"uchi ni"},{"jp":"いろいろ","role":"adjective","meaning":"bermacam-macam","reading":"iroiro"},{"jp":"りょこうしたいです","role":"verb","meaning":"ingin jalan-jalan","reading":"ryokou shitai desu"}],"translation":"Mumpung masih di Jepang, saya ingin berwisata ke mana-mana."}],"when_to_use":["Mengajak makan selagi panas atau belajar mumpung masih muda","Memesan tempat atau membereskan pekerjaan mumpung belum lupa / sebelum gelap","Bercerita bahwa tanpa sadar suatu perubahan terjadi selagi melakukan kegiatan lain (seperti ''ketiduran selagi membaca'')"],"formula_parts":[{"role":"time","text":"Keadaan Berlangsung (Biasa / NAI / の)","label":"Kondisi sementara"},{"role":"connector","text":"うちに","label":"Mumpung / Selagi"},{"role":"verb","text":"Tindakan Segera","label":"Sebelum berubah"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000014', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-007', 'sentence_pattern', 'Seharusnya Menurut Logika (~はずだ)', '[Bentuk Biasa] + はずです', 'Menyatakan keyakinan logis pembicara berdasarkan informasi atau jadwal yang diketahui.', 7, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Tuan Tanaka seharusnya sebentar lagi tiba.","jp":"田中さんは もうすぐ 着くはずです。","reading":"Tanaka-san wa mousugu tsuku hazu desu."},{"id":"Karena dikirim kemarin, seharusnya sampai hari ini.","jp":"昨日 送ったので、今日 届くはずです。","reading":"Kinou okutta node, kyou todoku hazu desu."}]'::jsonb, '[Bentuk Biasa] + hazu desu', '{"quiz":[{"why":"Keyakinan berdasarkan perhitungan/bukti jadwal memakai ～はずです.","answer":1,"options":["つもりです","はずです","ようです","そうです"],"question":"Kamu mengecek peta dan melihat jaraknya dekat. Kalimat yang pas: ''あと 5ふんで つく ___'' (Harusnya 5 menit lagi sampai):"},{"why":"～はずがない menyatakan mustahil menurut akal sehat / fakta yang diketahui tentang orang itu.","answer":1,"options":["Dia memang sering berbohong","Mana mungkin dia berbohong! (mustahil menurut sifatnya)","Sebaiknya dia tidak berbohong","Saya dengar dia berbohong"],"question":"Apa arti teriakan kaget ''かれが うそを つく はずがない!''?"},{"why":"Sifat-Na tetap membutuhkan な di depan kata nomina はず.","answer":2,"options":["かんたん はずです","かんたんの はずです","かんたんな はずです","かんたんだ はずです"],"question":"Cara yang benar menggabungkan sifat-Na かんたん (mudah) dengan はず adalah:"}],"forms":[{"id":"harusnya mengerti","jp":"わかるはずです","label":"Keyakinan Logis","reading":"wakaru hazu desu"},{"id":"mana mungkin begitu!","jp":"そんなはずがない","label":"Mustahil (Negatif Kuat)","reading":"sonna hazu ga nai"},{"id":"padahal harusnya sudah sampai","jp":"とどくはずだったのに","label":"Ternyata Meleset","reading":"todoku hazu datta noni"}],"steps":["Pastikan kamu punya alasan atau bukti kuat di balik keyakinanmu (jadwal, foto, kebiasaan orang itu).","Sambungkan dengan aturan biasa: Verba/Sifat-I biasa, Sifat-Na + な, Kata Benda + の (misal: やすみ の はずです = harusnya hari ini libur).","Tambahkan はずです di ujung; kalau terkejut ternyata meleset dari dugaan, pakai はずだったのに (''padahal harusnya...'')."],"analogy":"～はずです artinya ''Harusnya sih...'' atau ''Logikanya pasti...''. Bukan nebak asal-asalan, melainkan yakin karena punya bukti, jadwal, atau perhitungan yang jelas!","mistakes":[{"why":"Memakai ～はずだ ke keputusan pribadi atasan atau menebak kemauan orang bisa terasa sedikit lancang jika tidak berdasar fakta resmi.","right":"きょうは いらっしゃると おもいます","wrong":"しゃちょう、きょうは いらっしゃる はずですよ"},{"why":"Sebelum はず, Kata Benda memakai の (yasumi no hazu desu), jangan だ.","right":"きょうは やすみ の はずです","wrong":"きょうは やすみ だ はずです"}],"breakdowns":[{"tokens":[{"jp":"かれ","role":"topic","meaning":"dia","reading":"kare"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"きょう","role":"time","meaning":"hari ini","reading":"kyou"},{"jp":"くる","role":"verb","meaning":"datang","reading":"kuru"},{"jp":"はずです","role":"ending","meaning":"harusnya (sesuai jadwal)","reading":"hazu desu"}],"translation":"Menurut jadwal, dia harusnya datang hari ini."},{"tokens":[{"jp":"さっき","role":"time","meaning":"tadi","reading":"sakki"},{"jp":"メール","role":"object","meaning":"email","reading":"meeru"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"おくった","role":"verb","meaning":"sudah kirim","reading":"okutta"},{"jp":"ので","role":"connector","meaning":"karena","reading":"node"},{"jp":"もう","role":"time","meaning":"sekarang sudah","reading":"mou"},{"jp":"とどいている","role":"verb","meaning":"sampai/masuk","reading":"todoite iru"},{"jp":"はずです","role":"ending","meaning":"harusnya sih","reading":"hazu desu"}],"translation":"Karena barusan sudah saya kirim emailnya, harusnya sekarang sudah masuk."},{"tokens":[{"jp":"きょう","role":"time","meaning":"hari ini","reading":"kyou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"にちようび","role":"noun","meaning":"hari Minggu","reading":"nichiyoubi"},{"jp":"だから","role":"connector","meaning":"karena","reading":"dakara"},{"jp":"ぎんこう","role":"subject","meaning":"bank","reading":"ginkou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"あいている","role":"verb","meaning":"buka","reading":"aite iru"},{"jp":"はずがありません","role":"ending","meaning":"mustahil","reading":"hazu ga arimasen"}],"translation":"Karena hari ini hari Minggu, bank tidak mungkin sedang buka."}],"when_to_use":["Menyimpulkan jadwal kereta/acara (''keretanya berangkat jam 9, harusnya sebentar lagi sampai'')","Meyakini kemampuan teman berdasarkan usaha (''dia belajar keras tiap hari, harusnya lulus!'')","Versi negatif ～はずがない: ''Mustahil / Mana mungkin...'' berdasarkan logika"],"formula_parts":[{"role":"predicate","text":"Bentuk Biasa (+ な u/ Sifat-Na, + の u/ Nomina)","label":"Dugaan berdasar bukti"},{"role":"ending","text":"はずだ / はずです","label":"Harusnya menurut logika"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000015', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-008', 'conjugation', 'Bentuk Pasif (~られる)', '[Verba Pasif] + ます', 'Menyatakan subjek dikenai suatu tindakan atau peristiwa.', 8, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Saya dipuji oleh manajer bagian.","jp":"部長に ほめられました。","reading":"Buchou ni homeraremashita."},{"id":"Teknologi ini digunakan di seluruh dunia.","jp":"この 技術は 世界中で 使われています。","reading":"Kono gijutsu wa sekaijuu de tsukawarete imasu."}]'::jsonb, '[Verba Pasif] + masu', '{"quiz":[{"why":"き berubah ke vokal ''a'' (か = ka) + れる → かかれる (ditulis).","answer":0,"options":["かかれる","かけられる","かきられる","かされる"],"question":"Bagaimana mengubah かきます (menulis, Grup 1) ke bentuk pasif (''ditulis'')?"},{"why":"Bahasa Jepang punya ''pasif penderitaan'' (meiwaku no ukemi) saat kejadian alam/orang lain bikin pembicara kerepotan.","answer":1,"options":["Salah tata bahasa tapi populer","Untuk mengekspresikan ''kehujanan'' yang bikin pembicara terganggu/kerepotan","Artinya ''saya menurunkan hujan''","Hanya dipakai dalam puisi kuno"],"question":"Mengapa kalimat ''あめに ふられました'' sering dipakai padahal hujan adalah benda tak bernyawa?"},{"why":"Verba berakhiran -u/-います (おこなう) berubah menjadi -わ + れる → おこなわれます.","answer":1,"options":["おこなあれます","おこなわれます","おこなられます","おこなさせます"],"question":"Lengkapi: ''かいぎは 日本語で おこな___'' (Rapat diadakan dalam bahasa Jepang; おこなう = mengadakan):"}],"forms":[{"id":"dimarahi (dari shikaru)","jp":"しかられました","label":"Grup 1 (-a + れる)","reading":"shikararemashita"},{"id":"dilihat (dari miru)","jp":"みられました","label":"Grup 2 (+られる)","reading":"miraremashita"},{"id":"diundang","jp":"しょうたいされました","label":"Grup 3 (する→される)","reading":"shoutai saremashita"}],"steps":["Ubah verba ke bentuk pasif: Grup 1 ganti vokal akhir ke baris ''a'' + れる (shikarimasu → shikarareru = dimarahi, iimasu → iwareru); Grup 2 ganti ます jadi られる (homemasu → homerareru = dipuji); Grup 3: shimasu → sareru, kimasu → korareru.","Tandai pelakunya dengan partikel に (misal: せんせいに ほめられました = dipuji oleh guru).","Kalau subjeknya barang mati sejarah (''dibuat di Jepang''), pelakunya bisa memakai によって."],"analogy":"Bentuk Pasif (~られる) itu seperti awalan ''di-'' di bahasa Indonesia (''dimarahi bos'', ''dibangun tahun 1990'', ''dompetku dicuri orang''). Hati-hati, di Jepang bentuk pasif juga sering dipakai saat pembicara MERASA DIRUGIKAN atau terganggu oleh suatu kejadian (misal: kehujanan di jalan)!","mistakes":[{"why":"Bila kaki kita yang diinjak orang, pakai bentuk pasif ふまれました + objek kaki tetap memakai を.","right":"でんしゃで となりのひとに 足を ふまれました","wrong":"でんしゃで 足を ともだちに ふみました"},{"why":"Kata kerja Grup 1 berakhiran -う / -います tidak menjadi ''a'', melainkan ''wa'' + reru (iu → iwareru, kau → kawareru)!","right":"いわれます","wrong":"いいます → いあれます"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"せんせい","role":"noun","meaning":"guru","reading":"sensei"},{"jp":"に","role":"particle","meaning":"oleh","reading":"ni"},{"jp":"ほめられました","role":"verb","meaning":"dipuji (pasif)","reading":"homeraremashita"}],"translation":"Saya dipuji oleh guru."},{"tokens":[{"jp":"かえり","role":"time","meaning":"waktu pulang","reading":"kaeri"},{"jp":"に","role":"particle","meaning":"saat","reading":"ni"},{"jp":"あめ","role":"noun","meaning":"hujan","reading":"ame"},{"jp":"に","role":"particle","meaning":"(dikenai)","reading":"ni"},{"jp":"ふられました","role":"verb","meaning":"kehujanan (pasif rugi)","reading":"furaremashita"}],"translation":"Saat pulang tadi saya kehujanan."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"おてら","role":"topic","meaning":"kuil","reading":"otera"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"300ねんまえ","role":"time","meaning":"300 tahun lalu","reading":"sanbyakunen mae"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"たてられました","role":"verb","meaning":"dibangun","reading":"tateraremashita"}],"translation":"Kuil ini dibangun 300 tahun yang lalu."}],"when_to_use":["Menceritakan kejadian yang menimpa dirimu (''dipuji guru'', ''dompet dicopet'', ''diundang ke pesta'')","Menceritakan kejadian alam/sosial yang merugikan tanpa sengaja (''kehujanan di tengah jalan'')","Menulis fakta netral benda bersejarah atau produk (''kuil ini dibangun 300 tahun lalu'')"],"formula_parts":[{"role":"topic","text":"Korban / Subjek","label":"Yang dikenai aksi"},{"role":"particle","text":"は + Pelaku に","label":"Oleh siapa"},{"role":"verb","text":"Verba Pasif","label":"Berakhiran -areru / -rareru"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000016', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-009', 'tense', 'Baru Saja Selesai (~たばかり)', '[Verba Bentuk-TA] + ばかりです', 'Menekankan bahwa suatu aksi baru saja terjadi secara psikologis menurut pembicara.', 9, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Saya baru saja datang ke Jepang bulan lalu.","jp":"先月 日本に 来たばかりです。","reading":"Sengetsu Nihon ni kita bakari desu."},{"id":"Karena baru saja makan siang, perut saya kenyang.","jp":"昼ご飯を 食べたばかりなので、おなかが いっぱいです。","reading":"Hirugohan o tabeta bakari na node, onaka ga ippai desu."}]'::jsonb, '[Verba Bentuk-TA] + bakari desu', '{"quiz":[{"why":"Pola ''baru saja selesai'' selalu memakai Bentuk-TA (たべた) + ばかりです.","answer":1,"options":["さっき たべる ばかりです","さっき たべた ばかりです","さっき たべて ばかりです","さっき たべない ばかりです"],"question":"Teman mengajak makan siang, tapi kamu baru selesai makan 15 menit lalu. Kamu bilang:"},{"why":"～たばかり bersifat psikologis; jika dirasa masih pengantin baru, setahun pun bisa memakai ～たばかり.","answer":1,"options":["Salah ketik tahun","~たばかり bergantung pada rasa ''masih baru'' di hati pembicara","Hanya boleh untuk acara besar","Artinya akan menikah tahun depan"],"question":"Mengapa orang bisa berkata ''きょねん けっこんした ばかりです'' (Padahal menikah sudah setahun lalu)?"},{"why":"ばかり berlaku seperti nomina di depan kata benda lain, sehingga memakai partikel の.","answer":2,"options":["かったばかり くつ","かったばかりな くつ","かったばかりの くつ","かったばかりで くつ"],"question":"Bagaimana menerangkan kata benda dengan ～たばかり (''sepatu yang baru dibeli'')?"}],"forms":[{"id":"baru saja bangun","jp":"おきたばかりです","label":"Kalimat Akhir","reading":"okita bakari desu"},{"id":"karena baru saja mulai","jp":"はじめたばかりなので","label":"Sambung Alasan","reading":"hajimeta bakari na node"},{"id":"bayi yang baru saja lahir","jp":"うまれたばかりのあかちゃん","label":"Menerangkan Benda","reading":"umareta bakari no akachan"}],"steps":["Ubah kata kerja ke Bentuk-TA (bentuk lampau kamus, misal: きた, たべた, かった).","Tambahkan ばかりです di akhir kalimat.","Kalau mau menerangkan kata benda di belakangnya (''roti yang baru dibeli''), gunakan ～たばかりの + Kata Benda (例: かったばかりの パン)."],"analogy":"～たばかり artinya ''Baru saja selesai...'' (menurut PERASAAN si pembicara). Meskipun sudah lewat sebulan atau setahun, kalau rasanya masih hangat/baru banget di benak kita (misal ''baru aja masuk perusahaan ini''), kita pakai ～たばかり!","mistakes":[{"why":"Beda utama dengan ～たところ: ところ murni untuk hitungan detik/menit barusan, sedangkan ばかり bebas menurut perasaan (boleh berbulan-bulan lalu pun asal terasa baru).","right":"さっき ついたばかりです / きたところです","wrong":"おきたばかりで、でんしゃが しゅっぱつしました"},{"why":"Selalu wajib memakai Bentuk-TA (sudah selesai), tidak boleh bentuk kamus sebelum ばかり.","right":"さっき かえった ばかりです","wrong":"さっき かえる ばかりです"}],"breakdowns":[{"tokens":[{"jp":"さっき","role":"time","meaning":"tadi","reading":"sakki"},{"jp":"たべた","role":"verb","meaning":"makan (TA)","reading":"tabeta"},{"jp":"ばかりです","role":"ending","meaning":"baru saja","reading":"bakari desu"}],"translation":"Saya baru saja makan barusan."},{"tokens":[{"jp":"せんげつ","role":"time","meaning":"bulan lalu","reading":"sengetsu"},{"jp":"にほん","role":"place","meaning":"Jepang","reading":"Nihon"},{"jp":"に","role":"particle","meaning":"ke","reading":"ni"},{"jp":"きた","role":"verb","meaning":"datang (TA)","reading":"kita"},{"jp":"ばかり","role":"connector","meaning":"baru saja","reading":"bakari"},{"jp":"なので","role":"connector","meaning":"karena","reading":"na node"},{"jp":"まだ","role":"time","meaning":"masih belum","reading":"mada"},{"jp":"なれません","role":"verb","meaning":"terbiasa","reading":"naremasen"}],"translation":"Karena baru saja tiba di Jepang bulan lalu, saya belum terbiasa."},{"tokens":[{"jp":"これ","role":"topic","meaning":"ini","reading":"kore"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"きのう","role":"time","meaning":"kemarin","reading":"kinou"},{"jp":"かった","role":"verb","meaning":"beli (TA)","reading":"katta"},{"jp":"ばかりの","role":"particle","meaning":"yang baru saja","reading":"bakari no"},{"jp":"カメラ","role":"predicate","meaning":"kamera","reading":"kamera"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Ini adalah kamera yang baru saja saya beli kemarin."}],"when_to_use":["Menolak ajakan makan karena baru saja makan 10 menit lalu","Menceritakan hal baru dalam hidup meski kejadiannya beberapa minggu/bulan lalu (''baru aja pindah ke Jepang bulan lalu'')","Melaporkan produk atau mesin yang baru saja dibeli atau diperbaiki"],"formula_parts":[{"role":"verb","text":"Verba Bentuk-TA","label":"Sudah terjadi"},{"role":"ending","text":"ばかりです","label":"Baru saja rasanya"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000017', '4a1e0477-b5b2-42ba-844d-596bd2a80cc7', 'GP-JA-N3-010', 'particle', 'Berdasarkan / Oleh (~によって)', '[Nomina] + によって', 'Menunjukkan pelaku dalam kalimat pasif, penyebab, sarana, atau variasi menurut faktor.', 10, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Budaya berbeda-beda tergantung negaranya.","jp":"文化は 国によって 異なります。","reading":"Bunka wa kuni ni yotte kotonarimasu."},{"id":"Masalah terselesaikan melalui metode baru.","jp":"新しい 方法によって 問題が 解決されました。","reading":"Atarashii houhou ni yotte mondai ga kaiketsu saremashita."}]'::jsonb, '[Nomina] + ni yotte', '{"quiz":[{"why":"Dengan verba perbedaan/perubahan (かわる/ちがう), によって bermakna ''tergantung pada...''.","answer":1,"options":["Pakaian dibuat oleh musim","Tergantung musimnya, warna pakaian berubah","Musim menyebabkan pakaian kotor","Berdasarkan pakaian, musim ditentukan"],"question":"Apa arti kalimat ''きせつ によって ふくの いろが かわります''?"},{"why":"Karena langsung diikuti kata benda 被害 (kerusakan), wajib memakai bentuk kamus による.","answer":1,"options":["によって","による","にとって","について"],"question":"Lengkapi frasa berita ''火事 ___ 被害 (かじ ___ ひがい = kerusakan akibat kebakaran)'':"},{"why":"Menyebut pencipta atau pembangun karya terkenal dalam kalimat pasif memakai によって.","answer":1,"options":["きのう いぬに によって かまれました","この たてものは ゆうめいな けんちくかに よって つくられました","ともだちに よって カフェへ いきました","あしたは てんきに よって にちようびです"],"question":"Mana yang memakai によって secara paling tepat?"}],"forms":[{"id":"lukisan yang dilukis oleh Leonardo","jp":"レオナルドによってかかれた絵","label":"Pencipta (Pasif)","reading":"Reonarudo ni yotte kakareta e"},{"id":"tergantung orangnya, pemikirannya beda","jp":"ひとによってかんがえがちがう","label":"Tergantung Faktor","reading":"hito ni yotte kangae ga chigau"},{"id":"kemacetan akibat kecelakaan","jp":"じこによるじゅうたい","label":"Modifikasi Benda","reading":"jiko ni yoru juutai"}],"steps":["Kenali konteks kalimatnya: jika akhir kalimat ada bentuk pasif penemuan (つくられた, かかれた), maka によって artinya ''oleh''.","Jika belakangnya berupa kata perbedaan (ちがいます, さまざまです), maka によって artinya ''tergantung pada...''.","Jika diletakkan persis di depan kata benda, ganti ujungnya menjadi による (contoh: たいふうによる ひがい = kerusakan akibat topan)."],"analogy":"～によって punya 3 arti andalan tergantung kalimatnya: (1) ''Oleh / Diciptakan oleh...'', (2) ''Tergantung / Berbeda menurut...'', dan (3) ''Disebabkan oleh / Dengan cara...''.","mistakes":[{"why":"Untuk kejadian sehari-hari yang mengenai dirimu secara langsung (seperti dimarahi ibu, digigit nyamuk), gunakan partikel に biasa, jangan によって. によって cocok untuk fakta umum/karya resmi.","right":"ははに しかられました","wrong":"ははによって しかられました"},{"why":"Saat berada langsung di depan kata benda, bentuk yang benar adalah による (bukan によっての).","right":"たいふうによる ひがい","wrong":"たいふうによっての ひがい"}],"breakdowns":[{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"しょうせつ","role":"topic","meaning":"novel","reading":"shousetsu"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"むらかみさん","role":"noun","meaning":"Murakami","reading":"Murakami-san"},{"jp":"によって","role":"particle","meaning":"oleh","reading":"ni yotte"},{"jp":"かかれました","role":"verb","meaning":"ditulis (pasif)","reading":"kakaremashita"}],"translation":"Novel ini ditulis oleh Murakami."},{"tokens":[{"jp":"くに","role":"noun","meaning":"negara","reading":"kuni"},{"jp":"によって","role":"particle","meaning":"tergantung pada","reading":"ni yotte"},{"jp":"ぶんか","role":"subject","meaning":"budaya","reading":"bunka"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ちがいます","role":"verb","meaning":"berbeda-beda","reading":"chigaimasu"}],"translation":"Tergantung negaranya, budayanya berbeda-beda."},{"tokens":[{"jp":"じしん","role":"noun","meaning":"gempa","reading":"jishin"},{"jp":"によって","role":"particle","meaning":"akibat / disebabkan oleh","reading":"ni yotte"},{"jp":"でんしゃ","role":"subject","meaning":"kereta","reading":"densha"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"とまっています","role":"verb","meaning":"terhenti","reading":"tomatte imasu"}],"translation":"Akibat gempa, kereta sedang terhenti."}],"when_to_use":["Menyebut pencipta karya atau arsitek suatu penemuan bersejarah dalam kalimat pasif (''ditemukan oleh...'')","Menyatakan variasi berbeda tergantung faktor (''tergantung negara, budayanya berbeda'')","Menjelaskan sarana atau sebab resmi dalam berita (''disebabkan oleh gempa'', ''melalui diskusi'')"],"formula_parts":[{"role":"noun","text":"Nomina (Pencipta / Faktor / Sebab)","label":"Penentu"},{"role":"particle","text":"によって / により / による","label":"Oleh / Tergantung / Akibat"},{"role":"predicate","text":"Keterangan / Hasil Berbeda","label":"Penjelas"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('fc7f7429-1673-4eb1-b1de-1551413056fe', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-001', 'sentence_pattern', 'Permohonan Sangat Sopan (～ていただけませんか)', '[Verba Bentuk-Te] + いただけませんか', 'Digunakan untuk meminta tolong kepada atasan, guru, klien, atau orang yang belum akrab dengan tingkat kesopanan jauh lebih tinggi daripada ～てください.', 1, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Bersediakah Anda menjelaskannya sekali lagi?","jp":"もう いちど せつめいして いただけませんか。","reading":"Mou ichido setsumei shite itadakemasen ka."},{"id":"Maaf, bisakah Anda tolong mengambilkan foto?","jp":"すみませんが、しゃしんを とって いただけませんか。","reading":"Sumimasen ga, shashin o totte itadakemasen ka."},{"id":"Apakah Anda berkenan memeriksa dokumen ini?","jp":"この しりょうを チェックして いただけませんか。","reading":"Kono shiryou o chekku shite itadakemasen ka."}]'::jsonb, '[Verba-te] + itadakemasen ka', '{"quiz":[{"why":"Pola permohonan sangat sopan memakai [Verba Bentuk-TE] + いただけませんか, jadi みます menjadi みて + いただけませんか.","answer":0,"options":["レポートを みて いただけませんか。","レポートを みます いただけませんか。","レポートを みた いただけませんか。","レポートを みない いただけませんか。"],"question":"Saat meminta manajer memeriksa laporan dengan sangat sopan (みます → Bentuk-TE: みて), kalimat mana yang tepat?"},{"why":"Kata kerja Grup 1 berakhiran ち sebelum ます (machimasu) berubah menjadi って di Bentuk-TE → まって いただけませんか.","answer":1,"options":["まちて いただけませんか。","まって いただけませんか。","まいて いただけませんか。","まちます いただけませんか。"],"question":"Bagaimana berkata \"Bersediakah Anda menunggu sebentar?\" kepada tamu dengan sangat santun? (まちます = menunggu)"},{"why":"Kepada senior atau atasan di tempat kerja Jepang, [Verba Bentuk-TE] + いただけませんか adalah standar permohonan santun N4.","answer":2,"options":["つかいかたを おしえて！","つかいかたを おしえる。","つかいかたを おしえて いただけませんか。","つかいかたを おしえませんでしたか。"],"question":"Manakah ungkapan yang paling sopan saat meminta senior mengajari cara memakai mesin kantor?"}],"forms":[{"id":"Bersediakah Anda mengajarkannya?","jp":"おしえて いただけませんか","label":"Sangat Sopan (Umum)","reading":"oshiete itadakemasen ka"},{"id":"Bisakah Anda mengajarkannya?","jp":"おしえて いただけますか","label":"Sopan Halus","reading":"oshiete itadakemasu ka"},{"id":"Tolong ajarkan.","jp":"おしえて ください","label":"Sopan Standar (N5)","reading":"oshiete kudasai"}],"steps":["Awali dengan kata pembuka sopan seperti すみませんが (Maaf mengganggu, ...).","Ubah kata kerja inti ke Bentuk-TE (misal: おしえます → おしえて, みます → みて).","Tambahkan いただけませんか di akhir kalimat dengan intonasi bertanya yang lembut."],"analogy":"Jika ～てください itu \"Tolong ... ya\" (kadang terasa seperti instruksi langsung), maka ～ていただけませんか setara dengan \"Bersediakah / Maukah Bapak/Ibu berkenan membantu ...?\" yang sangat santun di lingkungan kerja JLPT N4.","mistakes":[{"why":"Kepada atasan atau guru, ～てください terdengar seperti instruksi langsung. Pakai ～ていただけませんか agar lebih menghormati.","right":"せんせい、すみませんが、ペンを かして いただけませんか","wrong":"せんせい、ペンを かして ください"},{"why":"Sebelum いただけませんか kata kerja wajib berbentuk TE (てつだって), tidak boleh bentuk -ます.","right":"てつだって いただけませんか","wrong":"てつだいます いただけませんか"}],"breakdowns":[{"tokens":[{"jp":"もういちど","role":"time","meaning":"sekali lagi","reading":"mou ichido"},{"jp":"せつめいして","role":"verb","meaning":"jelaskan (TE)","reading":"setsumei shite"},{"jp":"いただけませんか","role":"ending","meaning":"bersediakah Anda","reading":"itadakemasen ka"}],"translation":"Bersediakah Anda menjelaskannya sekali lagi?"},{"tokens":[{"jp":"すみませんが、","role":"connector","meaning":"maaf mengganggu,","reading":"sumimasen ga,"},{"jp":"しゃしん","role":"object","meaning":"foto","reading":"shashin"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"とって","role":"verb","meaning":"ambilkan (TE)","reading":"totte"},{"jp":"いただけませんか","role":"ending","meaning":"maukah Anda","reading":"itadakemasen ka"}],"translation":"Maaf, maukah Anda tolong mengambilkan foto?"},{"tokens":[{"jp":"この しりょう","role":"object","meaning":"dokumen ini","reading":"kono shiryou"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"チェックして","role":"verb","meaning":"periksa (TE)","reading":"chekku shite"},{"jp":"いただけませんか","role":"ending","meaning":"berkenankah Anda","reading":"itadakemasen ka"}],"translation":"Apakah Anda berkenan memeriksa dokumen ini?"}],"when_to_use":["Meminta tolong kepada atasan, guru, atau klien di lingkungan kerja","Meminta bantuan orang asing atau orang yang lebih tua secara sangat hormat","Meminta penjelasan ulang, koreksi dokumen, atau izin dengan nada merendah"],"formula_parts":[{"role":"verb","text":"Verba Bentuk-TE","label":"Tindakan yang diminta (-て / -で)"},{"role":"ending","text":"いただけませんか","label":"Bersediakah Anda? (sangat sopan)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('6cda8b61-f64d-4483-bc37-d0ab70789858', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-002', 'sentence_pattern', 'Keadaan Hasil Aksi Disengaja (～てあります)', '[Nomina] が [Verba Transitif Bentuk-Te] + あります', 'Menyatakan suatu benda kini berada dalam keadaan tertentu karena sebelumnya seseorang sengaja melakukan aksi tersebut (memakai verba transitif dengan penanda subjek が).', 2, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Jendelanya sudah dibuka (sengaja dibuka seseorang sebelumnya).","jp":"まどが あけて あります。","reading":"Mado ga akete arimasu."},{"id":"Di atas meja sudah diletakkan memo.","jp":"つくえの うえに メモが おいて あります。","reading":"Tsukue no ue ni memo ga oite arimasu."},{"id":"Masakan untuk pesta sudah selesai disiapkan.","jp":"パーティーの りょうりは もう つくって あります。","reading":"Paatii no ryouri wa mou tsukutte arimasu."}]'::jsonb, '[Nomina] ga [Verba-te] + arimasu', '{"quiz":[{"why":"Walaupun かきます adalah verba transitif, pada pola ～てあります subjek keadaan ditandai dengan が (atau は), bukan を.","answer":1,"options":["を","が","へ","から"],"question":"Partikel mana yang tepat untuk pola ～てあります berikut? 「こくばんに なまえ ___ かいて あります。」"},{"why":"Pola hasil aksi disengaja menggabungkan verba transitif Bentuk-TE (あけて) + あります dengan subjek bertanda が.","answer":0,"options":["ドアが あけて あります。","ドアが あいて あります。","ドアを あいて あります。","ドアが あけて います。"],"question":"Pilih kalimat yang benar untuk \"Pintu sengaja sudah dibuka sebelumnya\" (あけます = membuka [transitif]):"},{"why":"もう + [Verba Transitif Bentuk-TE] + あります berarti persiapannya (pemesanan tiket) sudah tuntas dan siap digunakan.","answer":1,"options":["Saya akan segera memesan tiket pesawat.","Tiket pesawatnya sudah dipesan sebelumnya (sudah siap).","Tolong pesankan tiket pesawat sekarang.","Tiket pesawatnya tidak jadi dipesan."],"question":"Arti yang paling tepat dari 「ひこうきの チケットは もう よやくして あります。」 adalah:"}],"forms":[{"id":"AC sengaja sudah dinyalakan.","jp":"エアコンが つけて あります","label":"Sudah Disiapkan","reading":"eakon ga tsukete arimasu"},{"id":"Barangnya sudah dikirimkan.","jp":"にもつは もう おくって あります","label":"Sudah Selesai (もう)","reading":"nimotsu wa mou okutte arimasu"},{"id":"Belum dituliskan.","jp":"まだ かいて ありません","label":"Belum Disiapkan","reading":"mada kaite arimasen"}],"steps":["Pilih verba transitif (他動詞, verba yang biasa berpasangan dengan を) seperti あけます, おきます, かきます.","Ubah partikel を menjadi が (atau は jika sudah menjadi topik) karena kalimat fokus pada kondisi benda.","Ubah verba transitif ke Bentuk-TE lalu sambungkan dengan あります."],"analogy":"Bedakan antara \"jendela terbuka\" begitu saja (～ている) dan \"jendela sengaja dibuka sebelumnya agar sejuk\" (～てある). Di level N4, pola ini dipakai untuk menekankan persiapan atau hasil tindakan manusia.","mistakes":[{"why":"～てあります wajib memakai verba transitif (かけます = menggantungkan), sedangkan intransitif (かかります) memakai ～ています.","right":"かべに カレンダーが かけて あります","wrong":"かべに カレンダーが かかって あります"},{"why":"Pada pola ～てあります, benda tidak ditandai を melainkan が (atau は) karena yang disorot adalah kondisi benda tersebut.","right":"つくえに ほんが おいて あります","wrong":"つくえに ほんを おいて あります"}],"breakdowns":[{"tokens":[{"jp":"まど","role":"subject","meaning":"jendela","reading":"mado"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あけて","role":"verb","meaning":"dibuka (TE)","reading":"akete"},{"jp":"あります","role":"ending","meaning":"kondisinya sudah begitu","reading":"arimasu"}],"translation":"Jendelanya sudah dibuka (sengaja dibuka sebelumnya)."},{"tokens":[{"jp":"つくえの うえ","role":"place","meaning":"atas meja","reading":"tsukue no ue"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"メモ","role":"subject","meaning":"memo","reading":"memo"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"おいて","role":"verb","meaning":"diletakkan (TE)","reading":"oite"},{"jp":"あります","role":"ending","meaning":"sudah tersedia di sana","reading":"arimasu"}],"translation":"Di atas meja sudah diletakkan memo."},{"tokens":[{"jp":"パーティーの りょうり","role":"topic","meaning":"masakan pesta","reading":"paatii no ryouri"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"もう","role":"time","meaning":"sudah","reading":"mou"},{"jp":"つくって","role":"verb","meaning":"dibuat (TE)","reading":"tsukutte"},{"jp":"あります","role":"ending","meaning":"sudah beres disiapkan","reading":"arimasu"}],"translation":"Masakan untuk pesta sudah selesai disiapkan."}],"when_to_use":["Menjelaskan kondisi benda yang sengaja diatur (jadwal tertulis di papan, pintu dibuka)","Melaporkan persiapan yang telah tuntas dikerjakan sebelum acara atau rapat","Menyorot benda hasil aksi dengan partikel が tanpa perlu menyebut siapa pelakunya"],"formula_parts":[{"role":"subject","text":"Nomina (Benda)","label":"Benda yang tampak keadaannya"},{"role":"particle","text":"が / は","label":"Penanda subjek keadaan"},{"role":"verb","text":"Verba Transitif Bentuk-TE","label":"Aksi yang disengaja (-て / -で)"},{"role":"ending","text":"あります","label":"Sudah dalam keadaan begitu"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('cb4acb75-471c-4397-a72b-1df038d3176a', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-003', 'sentence_pattern', 'Bentuk Keharusan ~Nakereba Narimasen', '[Verba Bentuk-Nai (buang -i)] + ければなりません', 'Pola formal standar untuk menyatakan kewajiban atau keharusan mutlak (harus melakukan sesuatu).', 3, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Laporan harus dikumpulkan paling lambat besok.","jp":"あしたまでに レポートを 出さなければなりません。","reading":"Ashita made ni repooto o dasanakereba narimasen."},{"id":"Harus minum obat.","jp":"くすりを のまなければなりません。","reading":"Kusuri o nomanakereba narimasen."}]'::jsonb, '[Verba Bentuk-Nai (buang -i)] + kereba narimasen', '{"quiz":[{"why":"Ambil akar Bentuk-NAI (かかな-) lalu tempelkan ければなりません.","answer":0,"options":["かかなければなりません","かきなければなりません","かくなければなりません","かいてなりません"],"question":"Bagaimana mengatakan ''Saya harus menulis laporan'' (かきます -> かかない)?"},{"why":"Bentuk-NAI (tanpa い) + くてもいいです artinya tidak wajib / boleh tidak melakukan.","answer":2,"options":["Hari Sabtu wajib masuk kerja","Hari Sabtu dilarang masuk kerja","Hari Sabtu tidak perlu masuk kerja","Hari Sabtu ingin masuk kerja"],"question":"Apa arti kalimat ''どようびは しゅっきん しなくてもいいです''?"},{"why":"Bentuk lampau dari なりません adalah なりませんでした.","answer":1,"options":["～なければなりません","～なければなりませんでした","～なかったらなりません","～ないでした"],"question":"Kalau kewajibannya terjadi KEMARIN (''Kemarin harus lembur''), ujungnya berubah menjadi:"}],"forms":[{"id":"harus pergi","jp":"いかなければなりません","label":"Wajib Formal","reading":"ikanakereba narimasen"},{"id":"kemarin harus pergi","jp":"いかなければなりませんでした","label":"Lampau Wajib","reading":"ikanakereba narimasen deshita"},{"id":"tidak usah pergi","jp":"いかなくてもいいです","label":"Tidak Perlu (Lawan)","reading":"ikanakutemo ii desu"}],"steps":["Ubah kata kerja ke Bentuk-NAI dulu (nomimasu → nomanai, ikimasu → ikanai, shimasu → shinai).","Buang huruf い di akhir kata -ない, lalu ganti dengan ければなりません.","Jika situasinya santai dengan teman, orang Jepang sering menyingkat ujungnya menjadi ～なくちゃ atau ～なきゃ."],"analogy":"～なければなりません itu artinya ''mau tidak mau HARUS melakukan''. Di balik rumus panjangnya, makna aslinya lucu: ''kalau tidak [verba], tidak akan beres'' — makanya jadi berarti HARUS!","mistakes":[{"why":"Jangan tempelkan ke bentuk kamus; wajib ubah ke Bentuk-NAI (ikanai), buang い, lalu tambah ければなりません.","right":"いかなければなりません","wrong":"いくなければなりません"},{"why":"''Tidak perlu'' memakai ～なくてもいいです (bukan なければ).","right":"あしたは いかなくても いいです","wrong":"あした やすみでも いかなくては いいです"}],"breakdowns":[{"tokens":[{"jp":"くすり","role":"object","meaning":"obat","reading":"kusuri"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"のまなければなりません","role":"verb","meaning":"harus minum","reading":"nomanakereba narimasen"}],"translation":"Harus minum obat."},{"tokens":[{"jp":"きょう","role":"time","meaning":"hari ini","reading":"kyou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"はやく","role":"adjective","meaning":"lebih awal","reading":"hayaku"},{"jp":"かえらなければなりません","role":"verb","meaning":"harus pulang","reading":"kaeranakereba narimasen"}],"translation":"Hari ini saya harus pulang lebih awal."},{"tokens":[{"jp":"ここ","role":"place","meaning":"di sini","reading":"koko"},{"jp":"では","role":"particle","meaning":"(konteks)","reading":"de wa"},{"jp":"くつ","role":"object","meaning":"sepatu","reading":"kutsu"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"ぬがなければなりません","role":"verb","meaning":"wajib melepas","reading":"nuganakereba narimasen"}],"translation":"Di sini kita harus melepas sepatu."}],"when_to_use":["Menyatakan aturan kantor, sekolah, atau hukum yang wajib dipatuhi","Menyatakan kewajiban pribadi (harus minum obat, harus belajar untuk ujian besok)","Sebaliknya, kalau mau bilang ''tidak wajib'', pakai ～なくてもいいです"],"formula_parts":[{"role":"verb","text":"Bentuk-NAI (buang い)","label":"Akar negasi (-na)"},{"role":"ending","text":"ければなりません","label":"Kalau tidak -> tidak boleh (= Harus)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000001', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-004', 'conjugation', 'Bentuk Potensial / Bisa (~られる / ~える)', '[Akar Verba Potensial] + ます', 'Menyatakan kemampuan atau kemungkinan melakukan suatu tindakan (setara dengan "bisa ...").', 4, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Saya bisa berbicara bahasa Jepang sedikit.","jp":"日本語が すこし 話せます。","reading":"Nihongo ga sukoshi hanasemasu."},{"id":"Kartu dapat digunakan di restoran ini.","jp":"この レストランで カードが 使えます。","reading":"Kono resutoran de kaado ga tsukaemasu."}]'::jsonb, '[Akar Verba Potensial] + masu', '{"quiz":[{"why":"Grup 1 cukup ubah huruf sebelum ます ke baris vokal E: し (shi) → せ (se) → はなせます.","answer":1,"options":["はなせられます","はなせます","はなしできます","はなさます"],"question":"Bagaimana bentuk potensial (''bisa berbicara'') dari はなします (Grup 1)?"},{"why":"きます (Grup 3) bentuk potensial bakunya adalah こられます.","answer":2,"options":["きます","きられます","こられます","きますできます"],"question":"Lengkapi kalimat ''あした ７じに ___ か'' (Apakah kamu bisa datang jam 7 besok? きます = datang):"},{"why":"たべます (Grup 2) diubah menjadi たべられます, lalu negatifnya たべられません.","answer":0,"options":["からい たべものが たべられません","からい たべものが たべません","からい たべものを たべますか","からい たべものが たべれません"],"question":"Manakah kalimat yang tepat untuk ''Saya tidak bisa makan makanan pedas (からい たべもの)''?"}],"forms":[{"id":"bisa menulis (dari kakimasu)","jp":"かけます","label":"Grup 1 (i→e)","reading":"kakemasu"},{"id":"bisa makan (dari tabemasu)","jp":"たべられます","label":"Grup 2 (+られ)","reading":"taberaremasu"},{"id":"tidak bisa membaca","jp":"よめません","label":"Negatif","reading":"yomemasen"},{"id":"bisa menyetir","jp":"うんてんできます","label":"Khusus shimasu","reading":"unten dekimasu"}],"steps":["Grup 1 (bunyi ''i'' sebelum masu): ganti vokal i ke baris ''e'' (kaki-masu → kake-masu = bisa menulis, hanashi-masu → hanase-masu = bisa bicara).","Grup 2 (seperti tabe-masu, mi-masu): ubah ます menjadi られます (tabe-raremasu = bisa makan, mi-raremasu = bisa melihat).","Grup 3 (pengecualian): shimasu → dekimasu (bisa), kimasu → koraremasu (bisa datang). Catat: objek kalimat potensial biasanya pakai が."],"analogy":"Bentuk Potensial artinya ''bisa / mampu / memungkinkan'' (seperti imbuhan ''bisa...'' atau ''dapat...'' dalam bahasa Indonesia). Objeknya biasanya berubah memakai partikel が.","mistakes":[{"why":"Secara lisan sering diucapkan ''miremasu'', tapi bentuk baku tes JLPT untuk Grup 2 tetap memakai ''～られます'' (miraremasu).","right":"きのう えいがが みられました","wrong":"きのう えいがが みれます (dalam tulisan resmi)"},{"why":"Kata kerja します tidak diubah menjadi しまれます, melainkan diganti langsung menjadi できます.","right":"くるまが うんてん できます","wrong":"くるまを うんてん しまれます"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"およげます","role":"verb","meaning":"bisa berenang","reading":"oyogemasu"}],"translation":"Saya bisa berenang."},{"tokens":[{"jp":"かんじ","role":"subject","meaning":"huruf Kanji","reading":"kanji"},{"jp":"が","role":"particle","meaning":"(objek mampu)","reading":"ga"},{"jp":"よめます","role":"verb","meaning":"bisa membaca","reading":"yomemasu"}],"translation":"Saya bisa membaca Kanji."},{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"レストラン","role":"place","meaning":"restoran","reading":"resutoran"},{"jp":"では","role":"particle","meaning":"di sini","reading":"de wa"},{"jp":"カード","role":"subject","meaning":"kartu kredit","reading":"kaado"},{"jp":"が","role":"particle","meaning":"(objek mampu)","reading":"ga"},{"jp":"つかえません","role":"verb","meaning":"tidak bisa dipakai","reading":"tsukaemasen"}],"translation":"Di restoran ini kartu tidak dapat digunakan."}],"when_to_use":["Menyatakan keahlian bahasa, olahraga, atau skill (''bisa membaca Kanji'', ''bisa berenang'')","Menyatakan suatu tempat/situasi memungkinkan suatu hal dilakukan (''di sini bisa pesan kopi'')","Bentuk negatifnya berarti ''tidak bisa'' (bisa karena tidak mampu atau karena situasi tidak memungkinkan)"],"formula_parts":[{"role":"subject","text":"Hal yang Bisa Dilakukan","label":"Kemampuan"},{"role":"particle","text":"が","label":"Penanda objek mampu"},{"role":"verb","text":"Verba Potensial + ます","label":"Bisa ... (Grup 1-3)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000002', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-005', 'sentence_pattern', 'Memberi & Menerima Bantuan (~てあげる / ~てくれる)', '[Verba Bentuk-TE] + あげます / くれます', 'Menyatakan seseorang melakukan tindakan kebaikan bagi orang lain (あげます) atau bagi pembicara (くれます).', 5, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Senior mengajari saya cara kerja.","jp":"先輩が 仕事の やり方を 教えてくれました。","reading":"Senpai ga shigoto no yarikata o oshiete kuremashita."},{"id":"Saya mengantar teman sampai stasiun.","jp":"友達に 駅まで 送ってあげました。","reading":"Tomodachi ni eki made okutte agemashita."}]'::jsonb, '[Verba Bentuk-TE] + agemasu / kuremasu', '{"quiz":[{"why":"Yang dibantu adalah kamu (pembicara), sedangkan pelakunya teman. Arah kebaikan ke diri sendiri memakai くれます.","answer":1,"options":["ともだちが えきまで おくって あげました","ともだちが えきまで おくって くれました","わたしが えきまで おくって くれました","ともだちに えきまで おくって あげました"],"question":"Temanmu mengantar dirimu ke stasiun (おくる = mengantar). Kalimat yang paling tepat untuk bercerita adalah:"},{"why":"Pembicara berbuat baik kepada adik (orang lain), maka memakai ～てあげました.","answer":1,"options":["わたしは いもうとに ほんを よんで くれました","わたしは いもうとに ほんを よんで あげました","いもうとは わたしに ほんを よんで あげました","わたしは いもうとが ほんを よんで もらいました"],"question":"Kalau kamu yang membacakan buku cerita untuk adikmu (いもうと = adik perempuan):"},{"why":"あげます bermakna memberi ke bawah/setara, sehingga terkesan kurang sopan bila ditujukan ke atasan atau guru.","answer":1,"options":["Karena salah tata bahasa partikelnya","Karena ~te agemasu bernuansa sedikit superior (''nih aku bantuin kamu'')","Karena artinya ''guru membantu saya''","Karena hanya dipakai di masa lalu"],"question":"Mengapa sebaiknya kita menghindari berkata ''せんせい、おしえてあげますよ'' ke guru?"}],"forms":[{"id":"mengajarkan untuknya","jp":"おしえてあげます","label":"Membantu Org Lain","reading":"oshiete agemasu"},{"id":"diajari untuk saya","jp":"おしえてくれます","label":"Dibantu Org Lain","reading":"oshiete kuremasu"},{"id":"mendapat bantuan diajarkan","jp":"おしえてもらいます","label":"Menerima Bantuan","reading":"oshiete moraimasu"}],"steps":["Cek dulu siapa yang menerima manfaat aksinya!","Kalau orang lain yang menerima kebaikan (bukan dirimu), pakai ～てあげます (hati-hati: jangan pakai ke atasan langsung karena terkesan menggurui!).","Kalau DIRIMU (atau keluargamu) yang dibantu oleh orang lain, WAJIB pakai ～てくれます."],"analogy":"Di Jepang, kata kerja ''memberi/melakukan sesuatu untuk orang lain'' dibedakan dari arah kebaikannya: kalau SAYA (atau kelompok saya) berbuat baik ke orang lain pakai ～てあげます; kalau ORANG LAIN berbuat baik ke SAYA pakai ～てくれます.","mistakes":[{"why":"Bila penerima bantuannya adalah わたし (saya), TIDAK BOLEH memakai あげます, wajib memakai くれます!","right":"せんせいが わたしに ほんを かして くれました","wrong":"せんせいが わたしに ほんを かして あげました"},{"why":"Ke atasan atau orang asing, memakai ～てあげます terdengar agak angkuh. Gunakan お～しましょうか.","right":"ぶちょう、おてつだい しましょうか","wrong":"ぶちょう、てつだって あげましょうか (ke bos)"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ともだち","role":"noun","meaning":"teman","reading":"tomodachi"},{"jp":"に","role":"particle","meaning":"kepada","reading":"ni"},{"jp":"にほんご","role":"object","meaning":"bahasa Jepang","reading":"nihongo"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"おしえて","role":"verb","meaning":"mengajarkan (TE)","reading":"oshiete"},{"jp":"あげました","role":"ending","meaning":"telah memberi bantuan","reading":"agemashita"}],"translation":"Saya mengajarkan bahasa Jepang untuk teman saya."},{"tokens":[{"jp":"やまださん","role":"topic","meaning":"Sdr. Yamada","reading":"Yamada-san"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"わたし","role":"noun","meaning":"saya","reading":"watashi"},{"jp":"に","role":"particle","meaning":"untuk","reading":"ni"},{"jp":"しゃしん","role":"object","meaning":"foto","reading":"shashin"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"とって","role":"verb","meaning":"memotret (TE)","reading":"totte"},{"jp":"くれました","role":"ending","meaning":"telah berbaik hati","reading":"kuremashita"}],"translation":"Yamada memotretkan foto untuk saya."},{"tokens":[{"jp":"はは","role":"topic","meaning":"ibu saya","reading":"haha"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"まいにち","role":"time","meaning":"setiap hari","reading":"mainichi"},{"jp":"おいしい","role":"adjective","meaning":"enak","reading":"oishii"},{"jp":"りょうり","role":"object","meaning":"masakan","reading":"ryouri"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"つくって","role":"verb","meaning":"membuatkan (TE)","reading":"tsukutte"},{"jp":"くれます","role":"ending","meaning":"untuk saya","reading":"kuremasu"}],"translation":"Ibu saya membuatkan masakan enak setiap hari (untuk saya)."}],"when_to_use":["Menawarkan atau bercerita bahwa kamu menolong seseorang (pakai ～てあげます)","Berterima kasih atau menceritakan seseorang menolong/mengajarkanmu (pakai ～てくれます)","Meminta izin dengan sangat sopan sambil menyatakan kebaikan kepada orang yang dekat"],"formula_parts":[{"role":"topic","text":"Pemberi は","label":"Yang menolong"},{"role":"noun","text":"Penerima に","label":"Yang ditolong"},{"role":"verb","text":"Verba Bentuk-TE","label":"Aksi bantuannya"},{"role":"ending","text":"あげます / くれます","label":"Ke org lain / Ke saya"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000003', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-006', 'sentence_pattern', 'Saran Sebaiknya (~たほうがいい)', '[Verba Bentuk-TA / Bentuk-NAI] + ほうがいいです', 'Memberikan saran atau nasihat kuat kepada lawan bicara ("sebaiknya ... / sebaiknya jangan ...").', 6, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Karena demam, hari ini sebaiknya istirahat.","jp":"ねつが あるので、きょうは 休んだほうがいいです。","reading":"Netsu ga aru node, kyou wa yasunda hou ga ii desu."},{"id":"Sebaiknya jangan terlalu memaksakan diri.","jp":"あまり 無理を しないほうがいいですよ。","reading":"Amari muri o shinai hou ga ii desu yo."}]'::jsonb, '[Verba Bentuk-TA / Bentuk-NAI] + hou ga ii desu', '{"quiz":[{"why":"Saran positif menggunakan kata kerja Bentuk-TA (やすんだ) + ほうがいいです.","answer":1,"options":["やすむ ほうがいいです","やすんだ ほうがいいです","やすんで ほうがいいです","やすみ ほうがいいです"],"question":"Temanmu tampak pucat. Kamu mau bilang ''Sebaiknya istirahat (やすみます -> やすんだ)'':"},{"why":"Saran negatif menggunakan Bentuk-NAI sekarang (でかけない) + ほうがいいです.","answer":2,"options":["でかけなかった ほうがいいです","でかけた ほうがいいです","でかけない ほうがいいです","でかけません ほうがいいです"],"question":"Bagaimana mengatakan ''Sebaiknya tidak keluar malam-malam'' (でかけます -> でかけない)?"},{"why":"～たほうがいい terkesan cukup tegas memberi tahu apa yang seharusnya dilakukan, lebih pas untuk teman atau bawahan.","answer":0,"options":["Terlalu tegas/menggurui, sebaiknya pakai saran lebih halus ke atasan","Sangat hormat seperti keigo","Hanya dipakai dalam surat resmi","Bermakna pujian"],"question":"Nuansa pola ～たほうがいいです bila diucapkan langsung ke atasan di kantor adalah:"}],"forms":[{"id":"sebaiknya pergi ke RS","jp":"びょういんへいったほうがいいです","label":"Saran Positif","reading":"byouin e itta hou ga ii desu"},{"id":"sebaiknya jangan memaksakan diri","jp":"むりをしないほうがいいです","label":"Saran Negatif","reading":"muri o shinai hou ga ii desu"}],"steps":["Untuk menyarankan DILAKUKAN: ubah kata kerja ke Bentuk-TA (bentuk lampau kamus, misal: iku → itta, nomu → nonda, miru → mita), lalu tambahkan ほうがいいです.","Untuk menyarankan JANGAN DILAKUKAN: pakai Bentuk-NAI (misal: nomanai, ikanai) + ほうがいいです.","Tips: pakai pola ini kepada teman atau junior. Kepada bos, lebih sopan memakai kalimat pertanyaan halus (~tara dou desu ka)."],"analogy":"～たほうがいいです artinya mirip nasihat akrab ''Sebaiknya kamu...'' atau ''Lebih bagus kamu...'', sedangkan versi negatifnya ～ないほうがいいです artinya ''Sebaiknya kamu jangan...''.","mistakes":[{"why":"Bila memberi saran pada situasi spesifik sekarang, jauh lebih alami dan baku memakai Bentuk-TA (nonda), bukan bentuk kamus.","right":"くすりを のんだ ほうがいいです","wrong":"くすりを のむ ほうがいいです (saran satu kali)"},{"why":"Untuk saran larangan (''sebaiknya jangan''), selalu memakai Bentuk-NAI masa kini (tabenai), jangan lampau.","right":"たべない ほうがいいです","wrong":"たべなかった ほうがいいです"}],"breakdowns":[{"tokens":[{"jp":"はやめに","role":"time","meaning":"lebih cepat","reading":"hayame ni"},{"jp":"ねた","role":"verb","meaning":"tidur (TA)","reading":"neta"},{"jp":"ほうが","role":"connector","meaning":"sebaiknya","reading":"hou ga"},{"jp":"いいです","role":"ending","meaning":"lebih baik","reading":"ii desu"}],"translation":"Sebaiknya kamu tidur lebih awal."},{"tokens":[{"jp":"毎日","role":"time","meaning":"setiap hari","reading":"mainichi"},{"jp":"すこしずつ","role":"adjective","meaning":"sedikit demi sedikit","reading":"sukoshi zutsu"},{"jp":"れんしゅうした","role":"verb","meaning":"berlatih (TA)","reading":"renshuu shita"},{"jp":"ほうがいいです","role":"ending","meaning":"sebaiknya","reading":"hou ga ii desu"}],"translation":"Sebaiknya berlatih sedikit demi sedikit setiap hari."},{"tokens":[{"jp":"かぜ","role":"noun","meaning":"masuk angin","reading":"kaze"},{"jp":"の","role":"particle","meaning":"(saat)","reading":"no"},{"jp":"とき","role":"time","meaning":"ketika","reading":"toki"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"おさけ","role":"object","meaning":"alkohol","reading":"osake"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"のまない","role":"verb","meaning":"tidak minum (NAI)","reading":"nomanai"},{"jp":"ほうがいいです","role":"ending","meaning":"sebaiknya jangan","reading":"hou ga ii desu"}],"translation":"Saat sedang flu, sebaiknya jangan minum alkohol."}],"when_to_use":["Memberikan saran kesehatan (''kamu demam, sebaiknya istirahat/pergi ke RS'')","Memberikan tips belajar, perjalanan, atau persiapan (''sebaiknya bawa payung'')","Mengingatkan teman agar menghindari sesuatu (''sebaiknya jangan begadang'')"],"formula_parts":[{"role":"verb","text":"Bentuk-TA / Bentuk-NAI","label":"Sebaiknya / Sebaiknya tidak"},{"role":"noun","text":"ほうがいい","label":"Sisi yang lebih baik"},{"role":"ending","text":"です","label":"(Sopan)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000004', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-007', 'particle', 'Menyatakan Alasan Halus (~ので)', '[Bentuk Biasa] + ので、[Akibat]', 'Menghubungkan sebab dan akibat dengan nada lebih objektif dan sopan dibanding から.', 7, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Karena kereta terlambat, saya tidak sempat masuk rapat.","jp":"電車が 遅れたので、会議に 間に合いませんでした。","reading":"Densha ga okureta node, kaigi ni maniaimasen deshita."},{"id":"Karena ada keperluan, saya permisi pulang duluan.","jp":"用事が あるので、お先に 失礼します。","reading":"Youji ga aru node, osaki ni shitsurei shimasu."}]'::jsonb, '[Bentuk Biasa] + node, [Akibat]', '{"quiz":[{"why":"Kata benda (テスト) + な + ので → テストなので.","answer":2,"options":["テスト で ので","テスト だ ので","テスト な ので","テスト の ので"],"question":"Lengkapi: ''あした テスト ___、きょうは はやく かえります'' (Karena besok ujian, hari ini pulang cepat; テスト = kata benda):"},{"why":"～ので memberi kesan alasan yang objektif sehingga sangat aman dipakai di kantor atau saat memohon izin.","answer":1,"options":["Tidak ada perbedaan sama sekali","~ので terdengar lebih lembut, objektif, dan sopan untuk alasan izin/maaf","~から jauh lebih formal untuk email bisnis","~ので hanya boleh untuk peristiwa masa lalu"],"question":"Apa perbedaan utama antara ～ので dan ～から saat meminta izin ke atasan?"},{"why":"ない (bentuk biasa negatif) langsung disambung ke ので menjadi じかんがない ので.","answer":2,"options":["しずか ので、よく ねられます","ねむい な ので、ねます","じかんが ない ので、タクシーで いきます","あめ ので、うちへ かえります"],"question":"Pilih kalimat yang benar secara tata bahasa:"}],"forms":[{"id":"karena ada urusan, saya pulang","jp":"ようじがあるのでかえります","label":"Kata Kerja","reading":"youji ga aru node kaerimasu"},{"id":"karena sakit, saya istirahat","jp":"びょうきなのでやすみます","label":"Kata Benda (+な)","reading":"byouki na node yasumimasu"},{"id":"karena sibuk, tidak bisa pergi","jp":"いそがしいのでいけません","label":"Sifat-I","reading":"isogashii node ikemasen"}],"steps":["Letakkan kalimat alasannya di depan kata ので.","PERHATIAN PENTING: Jika alasannya berakhir dengan KATA BENDA atau KATA SIFAT-NA (dalam bentuk sekarang positif), wajib sisipkan な di antara kata itu dan ので (misal: あめ なので, ひま なので)!","Untuk kata kerja atau sifat-i, langsung pakai bentuk biasa kasual (atau kadang masu di lisan sangat formal) + ので."],"analogy":"～ので itu artinya ''karena... (jadi/maka...)''. Kalau di N5 ada から (karakternya lebih subjektif/pribadi), di N4 ～ので jauh lebih sopan, lembut, dan terdengar seperti alasan objektif ketika minta izin atau minta maaf.","mistakes":[{"why":"Bila didahului Kata Benda (あめ) atau Sifat-Na (しずか), huruf だ wajib berubah menjadi な sebelum ので!","right":"あめ な ので、いきません","wrong":"あめ だ ので、いきません"},{"why":"Karena ～ので bernuansa lembut/objektif, hindari memasangkannya dengan kalimat perintah kasar atau ajakan pribadi keras.","right":"さむい から、ドアを しめて","wrong":"さむい ので、ドアを しめて！ (perintah keras)"}],"breakdowns":[{"tokens":[{"jp":"あつい","role":"adjective","meaning":"panas","reading":"atsui"},{"jp":"ので","role":"particle","meaning":"karena","reading":"node"},{"jp":"まど","role":"object","meaning":"jendela","reading":"mado"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"あけます","role":"verb","meaning":"saya buka","reading":"akemasu"}],"translation":"Karena panas, saya buka jendelanya ya."},{"tokens":[{"jp":"にちようび","role":"time","meaning":"hari Minggu","reading":"nichiyoubi"},{"jp":"な","role":"particle","meaning":"(penghubung nomina)","reading":"na"},{"jp":"ので","role":"particle","meaning":"karena","reading":"node"},{"jp":"ぎんこう","role":"subject","meaning":"bank","reading":"ginkou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"やすみ","role":"predicate","meaning":"tutup/libur","reading":"yasumi"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Karena hari Minggu, bank tutup."},{"tokens":[{"jp":"バス","role":"subject","meaning":"bus","reading":"basu"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"おくれた","role":"verb","meaning":"terlambat (lampau)","reading":"okureta"},{"jp":"ので","role":"particle","meaning":"karena","reading":"node"},{"jp":"かいぎ","role":"place","meaning":"rapat","reading":"kaigi"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"まにあいませんでした","role":"verb","meaning":"tidak sempat tepat waktu","reading":"maniaimasen deshita"}],"translation":"Karena busnya terlambat, saya tidak sempat tiba tepat waktu untuk rapat."}],"when_to_use":["Meminta izin pulang cepat atau cuti karena ada urusan mendadak","Menjelaskan penyebab keterlambatan atau kesalahan dengan sopan","Mengungkapkan alasan logis situasi alam atau jadwal (karena hujan, pertandingan ditunda)"],"formula_parts":[{"role":"connector","text":"Alasan (Bentuk Biasa)","label":"Verba/Sifat-i biasa | Nomina/Sifat-na + な"},{"role":"particle","text":"ので","label":"Karena (halus/objektif)"},{"role":"predicate","text":"Akibat / Permintaan","label":"Hasilnya"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000005', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-008', 'tense', 'Syarat & Pengandaian (~たら)', '[Verba/Sifat Bentuk Lampau Biasa] + ら、[Hasil]', 'Menyatakan syarat ("kalau ...") atau urutan ("nanti setelah ... selesai").', 8, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Kalau sudah sampai di stasiun, tolong segera hubungi saya.","jp":"駅に 着いたら、すぐ 連絡してください。","reading":"Eki ni tsuitara, sugu renraku shite kudasai."},{"id":"Kalau harganya murah, saya berpikir untuk membelinya.","jp":"安かったら、買おうと 思います。","reading":"Yasukattara, kaou to omoimasu."}]'::jsonb, '[Verba/Sifat Bentuk Lampau Biasa] + ra, [Hasil]', '{"quiz":[{"why":"Bentuk-TA dari なる adalah なった, lalu ditambah ら menjadi なったら.","answer":1,"options":["なるたら","なったら","なってたら","なりたら"],"question":"Lengkapi: ''6じに ___、ばんごはんを たべましょう'' (Nanti kalau sudah jam 6 / menjadi jam 6, ayo makan malam; なる = menjadi):"},{"why":"あった (lampau ada) + ら = ''kalau ada'' (syarat pengandaian).","answer":1,"options":["Kemarin saya punya uang dan pergi ke Jepang","Kalau saya punya uang, saya ingin pergi ke Jepang","Karena tidak punya uang, saya tidak pergi","Sebelum ke Jepang, siapkan uang"],"question":"Apa arti kalimat ''おかねが あったら、にほんへ いきたいです''?"},{"why":"Lampau negatif kasualnya adalah ふらなかった, ditambah ら menjadi ふらなかったら.","answer":2,"options":["ふらないら","ふらなったら","ふらなかったら","ふりませんたら"],"question":"Manakah bentuk pengandaian negatif (''Kalau besok TIDAK turun hujan'') yang benar? (ふる = turun -> ふらない)"}],"forms":[{"id":"kalau ada waktu","jp":"じかんがあったら","label":"Kata Kerja (+)","reading":"jikan ga attara"},{"id":"kalau tidak datang","jp":"こなかったら","label":"Kata Kerja (-)","reading":"konakattara"},{"id":"kalau sulit","jp":"むずかしかったら","label":"Sifat-I","reading":"muzukashikattara"},{"id":"kalau senggang","jp":"ひまだったら","label":"Nomina / Sifat-Na","reading":"hima dattara"}],"steps":["Ubah kata kerja, kata sifat, atau kata benda menjadi bentuk lampau kasualnya (contoh: たべる → たべた, おいしい → おいしかった, ひま → ひまだった).","Tinggal tambahkan huruf ら di belakangnya (たべたら, おいしかったら, ひまだったら).","Tambahkan kalimat utama di belakangnya. Meski memakai bentuk lampau -た, maknanya di sini bukan masa lalu melainkan ''kalau/setelah''!"],"analogy":"～たら artinya bisa dua macam tergantung konteks: ''Kalau (syarat)...'' atau ''Nanti setelah ... selesai''. Uniknya, pembentukannya sangat gampang karena tinggal menambahkan huruf ら di belakang bentuk lampau biasa (-ta / -katta / -datta)!","mistakes":[{"why":"Bentuk-TA dari いく adalah いった (bukan いくた). Pastikan hafal perubahan lampau -ta yang benar sebelum menambah ら.","right":"とうきょうへ いったら、れんらくします","wrong":"とうきょうへ いくたら、れんらくします"},{"why":"Kata benda & sifat-Na memakai bentuk lampau だった sebelum ら, bukan な.","right":"あめ だったら、いきません","wrong":"あめ な たら、いきません"}],"breakdowns":[{"tokens":[{"jp":"やすかった","role":"adjective","meaning":"kalau murah (lampau)","reading":"yasukatta"},{"jp":"ら","role":"connector","meaning":"apabila","reading":"ra"},{"jp":"かいます","role":"verb","meaning":"saya beli","reading":"kaimasu"}],"translation":"Kalau murah, saya beli."},{"tokens":[{"jp":"うち","role":"place","meaning":"rumah","reading":"uchi"},{"jp":"に","role":"particle","meaning":"ke","reading":"ni"},{"jp":"かえったら","role":"verb","meaning":"nanti setelah pulang","reading":"kaettara"},{"jp":"すぐ","role":"time","meaning":"segera","reading":"sugu"},{"jp":"シャワー","role":"object","meaning":"mandi","reading":"shawaa"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"あびます","role":"verb","meaning":"mengguyur/mandi","reading":"abimasu"}],"translation":"Nanti begitu sampai rumah, saya langsung mandi."},{"tokens":[{"jp":"あした","role":"time","meaning":"besok","reading":"ashita"},{"jp":"あめ","role":"noun","meaning":"hujan","reading":"ame"},{"jp":"だったら","role":"connector","meaning":"kalau","reading":"dattara"},{"jp":"ピクニック","role":"topic","meaning":"piknik","reading":"pikunikku"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"ちゅうし","role":"predicate","meaning":"dibatalkan","reading":"chuushi"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Kalau besok hujan, pikniknya dibatalkan."}],"when_to_use":["Mengungkapkan syarat pengandaian (''kalau hujan tidak jadi pergi'', ''kalau punya uang mau beli rumah'')","Menyusun rencana berdasarkan waktu selesai suatu hal (''nanti kalau sudah sampai stasiun, kabari ya'')","Berandai-andai tentang kejadian yang belum tentu terjadi (''kalau menang lotre...'')"],"formula_parts":[{"role":"verb","text":"Bentuk Lampau Biasa (-TA / -かった / -だった)","label":"Syarat / Kondisi"},{"role":"connector","text":"ら","label":"Kalau / Setelah (-ra)"},{"role":"predicate","text":"Hasil / Tindakan Berikutnya","label":"Apa yang terjadi"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000006', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-009', 'sentence_pattern', 'Persiapan Sebelumnya (~ておく)', '[Verba Bentuk-TE] + おきます', 'Melakukan suatu tindakan terlebih dahulu sebagai persiapan menghadapi kondisi berikutnya.', 9, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Sebelum rapat saya fotokopi bahannya terlebih dahulu.","jp":"会議の前に 資料を コピーして おきます。","reading":"Kaigi no mae ni shiryou o kopii shite okimasu."},{"id":"Saya sudah memesan hotel sebelumnya.","jp":"ホテルを 予約して おきました。","reading":"Hoteru o yoyaku shite okimashita."}]'::jsonb, '[Verba Bentuk-TE] + okimasu', '{"quiz":[{"why":"Dinginkan bir lebih dulu untuk persiapan menyambut tamu memakai ～ておきます.","answer":0,"options":["ビールを ひやして おきます","ビールを ひやして いません","ビールを ひやして みます","ビールを ひやして しまいます"],"question":"Teman-teman akan datang makan malam di rumahmu nanti. Kalimat yang pas adalah:"},{"why":"かたづけておきます menyatakan kesiapan menyelesaikan pemberesan sebelum ditinggal.","answer":1,"options":["Meja jangan disentuh selamanya","Biarkan saja begitu di meja, nanti saya bereskan sebelum pulang","Saya sudah membereskan meja kemarin","Meja ini tidak bisa dibereskan"],"question":"Apa makna ucapan rekan kerja ''机の上は そのままで いいですよ。あとで かたづけておきますから''?"},{"why":"て + おく dalam ucapan cepat sehari-hari sering melebur menjadi とく (kaitoku).","answer":1,"options":["かいてく","かいとく","かいてる","かいちゃう"],"question":"Di percakapan kasual antara teman dekat, ''かいて おく'' (menulis siap-siap dulu) sering terdengar disingkat menjadi:"}],"forms":[{"id":"beli siap-siap dulu","jp":"かっておきます","label":"Siap-siap (Formal)","reading":"katte okimasu"},{"id":"tolong cari tahu dulu","jp":"しらべておいてください","label":"Minta Dikerjakan Dulu","reading":"shirabete oite kudasai"},{"id":"aku kerjain dulu ya! (santai)","jp":"やっとくね","label":"Obrolan Lisan Singkat","reading":"yattoku ne"}],"steps":["Ubah aksi yang ingin dipersiapkan ke Bentuk-TE (contoh: かう → かって, しらべる → しらべて).","Tambahkan おきます (bisa dikonjugasikan ke bentuk meminta: ～ておいてください = tolong disiapkan dulu).","Dalam obrolan sehari-hari yang cepat, ～ておく sering melebur menjadi ～とく (しとく, かっとく)!"],"analogy":"～ておきます itu artinya ''melakukan sesuatu LEBIH AWAL sebagai persiapan sebelum kejadian berikutnya'', atau ''membiarkan suatu keadaan tetap begitu apa adanya''. Mirip ungkapan Indonesia ''siapin dulu ya / biarin aja gitu dulu''.","mistakes":[{"why":"～ています artinya sedang melakukan sekarang atau status hasil; kalau maksudnya berjaga-jaga menyiapkan untuk nanti, pakai ～ておきます.","right":"よやくして おきます","wrong":"よやくして います (saat berniat persiapan besok)"},{"why":"～ておきます dilakukan dengan sengaja sebagai persiapan oleh subjek (Saya menyiapkan), sedangkan ～てあります hanya menggambarkan keadaan benda.","right":"たべて おきます / ならべて あります","wrong":"たべて あります"}],"breakdowns":[{"tokens":[{"jp":"ホテル","role":"object","meaning":"hotel","reading":"hoteru"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"よやくして","role":"verb","meaning":"reservasi (TE)","reading":"yoyakushite"},{"jp":"おきます","role":"ending","meaning":"siapkan duluan","reading":"okimasu"}],"translation":"Saya reservasi hotelnya dulu (sebagai persiapan)."},{"tokens":[{"jp":"かいぎ","role":"noun","meaning":"rapat","reading":"kaigi"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"まえ","role":"time","meaning":"sebelum","reading":"mae"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"しりょう","role":"object","meaning":"materi dokumen","reading":"shiryou"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"よんで","role":"verb","meaning":"baca (TE)","reading":"yonde"},{"jp":"おいてください","role":"ending","meaning":"tolong siapkan dulu","reading":"oite kudasai"}],"translation":"Tolong baca dulu materinya sebelum rapat dimulai."},{"tokens":[{"jp":"つぎ","role":"noun","meaning":"berikutnya","reading":"tsugi"},{"jp":"も","role":"particle","meaning":"juga","reading":"mo"},{"jp":"つかう","role":"verb","meaning":"dipakai","reading":"tsukau"},{"jp":"ので","role":"connector","meaning":"karena","reading":"node"},{"jp":"まど","role":"object","meaning":"jendela","reading":"mado"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"あけて","role":"verb","meaning":"buka (TE)","reading":"akete"},{"jp":"おきましょう","role":"ending","meaning":"biarkan dulu yuk","reading":"okimashou"}],"translation":"Karena nanti mau dipakai lagi, biarkan saja jendelanya tetap terbuka."}],"when_to_use":["Menyiapkan materi rapat, memesan tiket pesawat, atau membeli bahan sebelum hari-H","Membereskan alat atau menaruh dokumen di tempat semula seusai dipakai","Membiarkan jendela terbuka atau AC menyala untuk orang berikutnya"],"formula_parts":[{"role":"verb","text":"Verba Bentuk-TE","label":"Aksi persiapan (-て / -で)"},{"role":"ending","text":"おきます","label":"Dilakukan siap-siap dulu"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('d1000019-0000-0000-0000-000000000007', '54857970-6269-4f19-a601-6e6f2834a769', 'GP-JA-N4-010', 'honorific', 'Bentuk Sopan Merendah (Kenjougo Dasar)', 'お + [Stem] + します', 'Merendahkan tindakan diri sendiri sebagai wujud rasa hormat saat melayani klien atau berbicara dengan atasan.', 10, '2026-11-19T11:16:23.251825+00:00', '[{"id":"Mari saya bawakan barang bawaan Anda.","jp":"お荷物を お持ちします。","reading":"Onimotsu o omochi shimasu."},{"id":"Nanti saya akan menghubungi Anda lewat email.","jp":"後ほど メールで ご連絡いたします。","reading":"Nochihodo meeru de gorenraku itashimasu."}]'::jsonb, 'o + [Stem] + shimasu', '{"quiz":[{"why":"Kamu (tuan rumah) merendahkan aksi sendiri mengantar tamu memakai ご + kata kerja します → ごあんないします.","answer":1,"options":["おまち になりますか","ごあんない します","あんないして あげます","ごあんない なさいますか"],"question":"Saat menyambut tamu yang ingin kamu tunjukkan jalan ke kantor, kamu sebagai resepsionis berkata:"},{"why":"Kenjougo merendahkan tindakan diri sendiri (pembicara) demi menghormati lawan bicara.","answer":1,"options":["Atasan atau pelanggan kita","Pembicara (diri sendiri) / pihak internal kita","Orang asing di jalan","Benda mati"],"question":"Siapakah pelaku tindakan bila kita memakai pola Kenjougo お[Stem]します?"},{"why":"Kata khusus Kenjougo dari いいます (berkata/bernama) adalah もうします.","answer":0,"options":["アグスと もうします","アグスと おっしゃいます","アグスに いらっしゃいます","アグスを いただきます"],"question":"Dalam perkenalan wawancara kerja resmi, cara super sopan mengganti ''わたしは アグスと いいます'' adalah:"}],"forms":[{"id":"mari saya bawakan","jp":"おもちします","label":"Membantu Bawa","reading":"omochi shimasu"},{"id":"izinkan saya jelaskan","jp":"ごせつめいします","label":"Menjelaskan","reading":"gosetsumei shimasu"},{"id":"saya pergi / datang (merendah)","jp":"まいります","label":"Khusus: Pergi/Datang","reading":"mairimasu"},{"id":"nama saya / saya sampaikan","jp":"もうします","label":"Khusus: Berkata","reading":"moushimasu"}],"steps":["Pastikan pelakunya adalah DIRIMU SENDIRI (atau anggota perusahaanmu) yang berbuat sesuatu untuk lawan bicara.","Untuk kata kerja asli Jepang (1–2 kanji): tempelkan お di depan akar masu, lalu tutup dengan します (misal: もちます → おもちします = biar saya bawakan).","Untuk kata kerja gabungan kanji + します (seperti 案内します = mengantar, 説明します = menjelaskan): ganti menjadi ご案内します / ご説明します."],"analogy":"Kenjougo (bahasa merendah) dipakai untuk ''menurunkan'' tindakan DIRI SENDIRI saat berbicara kepada atasan, klien, atau tamu terhormat — tujuannya meninggikan rasa hormat kepada lawan bicara. Ibaratnya kita berkata ''izinkan saya membantu membawakan...''.","mistakes":[{"why":"Kenjougo (お～します) HANYA untuk tindakan DIRI SENDIRI, jangan dipakai ke tindakan atasan! Untuk atasan gunakan Sonkeigo (peninggi).","right":"しゃちょう、コーヒーを めしあがりますか","wrong":"しゃちょう、コーヒーを おのみしますか (nanya bos minum)"},{"why":"Kata serapan kanji berpasangan (案内, 連絡, 説明) memakai awalan ご (go-), bukan お (o-).","right":"ごあんない します","wrong":"おあんない します"}],"breakdowns":[{"tokens":[{"jp":"おにもつ","role":"object","meaning":"barang bawaan Anda","reading":"onimotsu"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"おもちします","role":"verb","meaning":"izinkan saya bawakan","reading":"omochi shimasu"}],"translation":"Mari saya bawakan barang bawaan Anda."},{"tokens":[{"jp":"かいぎしつ","role":"place","meaning":"ruang rapat","reading":"kaigishitsu"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"ごあんないします","role":"verb","meaning":"mari saya antar (sopan)","reading":"goannai shimasu"}],"translation":"Mari saya antarkan ke ruang rapat."},{"tokens":[{"jp":"あした","role":"time","meaning":"besok","reading":"ashita"},{"jp":"また","role":"time","meaning":"lagi","reading":"mata"},{"jp":"おでんわ","role":"object","meaning":"telepon","reading":"odenwa"},{"jp":"いたします","role":"verb","meaning":"akan saya hubungi (sgt sopan)","reading":"itashimasu"}],"translation":"Besok saya akan menelepon Anda kembali."}],"when_to_use":["Melayani tamu atau pelanggan di toko/kantor (''mari saya antar'', ''biar saya bawakan tasnya'')","Berbicara ke atasan atau klien dalam rapat & wawancara kerja","Memperkenalkan diri atau menghubungi rekan bisnis eksternal"],"formula_parts":[{"role":"particle","text":"お / ご","label":"Awalan hormat"},{"role":"verb","text":"Akar Verba / Kata Benda Aksi","label":"Tindakan diri sendiri"},{"role":"ending","text":"します","label":"Dengan rendah hati melakukan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('42be31b7-89cc-4d77-a3dc-686767f6a7cd', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-001', 'sentence_pattern', 'Partikel WA (Topik Kalimat)', '[Topik / Subjek] + は + [Predikat] + です', 'Partikel は (dibaca wa) berfungsi sebagai penanda topik utama dalam kalimat bahasa Jepang. Digunakan untuk menyatakan identitas, profesi, atau sifat.', 1, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Saya adalah seorang insinyur.","jp":"わたしは エンジニア です。","reading":"Watashi wa enjinia desu."},{"id":"Tuan Tanaka adalah orang Jepang.","jp":"たなかさんは にほんじん です。","reading":"Tanaka-san wa nihonjin desu."}]'::jsonb, '[Topik / Subjek] + wa + [Predikat] + desu', '{"quiz":[{"why":"Penanda topik selalu ditulis は (dibaca wa), bukan わ.","answer":0,"options":["は","を","わ","に"],"question":"Lengkapi kalimat perkenalan: わたし ___ エンジニアです (Saya adalah insinyur)."},{"why":"Bila berfungsi sebagai partikel topik, huruf は dibaca ''wa''.","answer":1,"options":["ha","wa","wo","ga"],"question":"Bagaimana cara melafalkan は dalam kalimat それは かぎです?"},{"why":"Topiknya これ, ditandai は, predikatnya じしょ, dan ditutup akhiran sopan です.","answer":2,"options":["これは じしょは です","じしょは これ","これは じしょです","これわ じしょです"],"question":"Manakah kalimat sopan yang tepat untuk ''Ini adalah kamus''?"}],"forms":[{"id":"adalah mahasiswa","jp":"がくせいです","label":"Positif","reading":"gakusei desu"},{"id":"bukan mahasiswa","jp":"がくせいではありません","label":"Negatif","reading":"gakusei dewa arimasen"},{"id":"apakah mahasiswa?","jp":"がくせいですか","label":"Tanya","reading":"gakusei desu ka"}],"steps":["Tentukan siapa atau benda apa yang ingin kamu bahas di paling depan kalimat.","Tempelkan partikel は (tulis ha, baca wa) tepat di belakang topik tersebut.","Sebutkan keterangannya (profesi, nama, benda, sifat), lalu tutup dengan です agar terdengar sopan."],"analogy":"は (dibaca wa) itu mirip kata ''kalau soal...'' atau ''adapun...'' di bahasa Indonesia. Tugasnya memberi tanda kepada pendengar tentang siapa atau apa yang sedang dibicarakan.","mistakes":[{"why":"Sebagai partikel topik, WA wajib ditulis dengan huruf Hiragana は (ha), bukan わ (wa).","right":"わたしは アグスです","wrong":"わたしわ アグスです"},{"why":"Hal yang paling jelas sebagai topik pembicaraan (''saya'') ditaruh di depan は, baru penjelasannya di belakang.","right":"わたしは アグスです","wrong":"アグスは わたしです"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"アグス","role":"predicate","meaning":"Agus","reading":"Agusu"},{"jp":"です","role":"ending","meaning":"adalah (sopan)","reading":"desu"}],"translation":"Saya adalah Agus."},{"tokens":[{"jp":"これ","role":"topic","meaning":"ini","reading":"kore"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"にほんご","role":"noun","meaning":"bahasa Jepang","reading":"nihongo"},{"jp":"の","role":"particle","meaning":"milik/tentang","reading":"no"},{"jp":"ほん","role":"predicate","meaning":"buku","reading":"hon"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Ini adalah buku bahasa Jepang."},{"tokens":[{"jp":"あした","role":"time","meaning":"besok","reading":"ashita"},{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"やすみ","role":"predicate","meaning":"libur","reading":"yasumi"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Besok saya libur."}],"when_to_use":["Saat memperkenalkan nama, asal, atau pekerjaan diri sendiri","Saat menunjuk benda dan menjelaskan benda apa itu","Saat mendeskripsikan sifat atau keadaan suatu topik secara sopan"],"formula_parts":[{"role":"topic","text":"Topik / Subjek","label":"Hal yang dibahas"},{"role":"particle","text":"は","label":"Penanda topik (wa)"},{"role":"predicate","text":"Predikat","label":"Info / keterangan"},{"role":"ending","text":"です","label":"Akhiran sopan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('84296601-2071-4b58-a093-e916c1f4abac', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-002', 'conjugation', 'Bentuk Lampau Negatif (Deshita / Dewa Arimasen)', '[Predikat] + ではありませんでした', 'Digunakan untuk menyatakan negasi lampau (bukan / dulu tidak) secara sopan (Teineigo).', 2, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Kemarin bukanlah hari libur.","jp":"きのうは やすみ ではありませんでした。","reading":"Kinou wa yasumi dewa arimasen deshita."},{"id":"Dia dulunya adalah mahasiswa.","jp":"かれは がくせい でした。","reading":"Kare wa gakusei deshita."}]'::jsonb, '[Predikat] + dewa arimasen deshita', '{"quiz":[{"why":"Untuk negasi masa lampau yang sopan, pakai ではありませんでした.","answer":1,"options":["せんせい でした","せんせい ではありませんでした","せんせい ではない","せんせい ではありません"],"question":"Pilih bentuk yang tepat untuk ''Kemarin saya bukan guru (dulu bukan)'':"},{"why":"では dapat disingkat menjadi じゃ (ja) dalam percakapan biasa agar lebih luwes.","answer":0,"options":["じゃありませんでした","でしたじゃない","ありませんでした","じゃないでした"],"question":"Apa versi percakapan lisan yang lebih ringan dari ではありませんでした?"},{"why":"Lampau positif kata benda cukup mengganti です dengan でした.","answer":2,"options":["きのうは あめではありませんでした","きのうは あめです","きのうは あめでした","きのうは あめではありません"],"question":"Kalimat mana yang menyatakan lampau positif (''Kemarin hujan'')?"}],"forms":[{"id":"sekarang libur","jp":"やすみです","label":"Sekarang (+)","reading":"yasumi desu"},{"id":"kemarin libur","jp":"やすみでした","label":"Lampau (+)","reading":"yasumi deshita"},{"id":"sekarang bukan libur","jp":"やすみではありません","label":"Sekarang (-)","reading":"yasumi dewa arimasen"},{"id":"kemarin bukan libur","jp":"やすみではありませんでした","label":"Lampau (-)","reading":"yasumi dewa arimasen deshita"}],"steps":["Tulis topik dan kata benda/sifat seperti kalimat biasa.","Alih-alih です (sekarang) atau でした (lampau positif), pakai ではありませんでした di paling akhir.","Dalam percakapan santai sehari-hari di kantor, ではありませんでした sering disingkat menjadi じゃありませんでした."],"analogy":"ではありませんでした itu seperti kata ''dulu bukan...'' atau ''kemarin tidak...'' versi sopan. Bagian akhir kalimat diubah untuk menunjukkan waktu yang sudah lewat.","mistakes":[{"why":"Urutan ekornya harus negasi dulu (ではありません), baru penanda lampau (でした) menempel paling belakang.","right":"きのうは やすみではありませんでした","wrong":"きのう やすみでした ではありません"},{"why":"ではありませんでした dipakai untuk kata benda & sifat-Na. Untuk sifat berakhiran -i (seperti oishii), pakai -ku arimasen deshita / -kunakatta desu.","right":"おいしくありませんでした","wrong":"おいしい ではありませんでした"}],"breakdowns":[{"tokens":[{"jp":"きのう","role":"time","meaning":"kemarin","reading":"kinou"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"やすみ","role":"predicate","meaning":"libur","reading":"yasumi"},{"jp":"ではありませんでした","role":"ending","meaning":"bukan (lampau)","reading":"dewa arimasen deshita"}],"translation":"Kemarin bukan hari libur."},{"tokens":[{"jp":"たなかさん","role":"topic","meaning":"Tuan Tanaka","reading":"Tanaka-san"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"いしゃ","role":"predicate","meaning":"dokter","reading":"isha"},{"jp":"じゃありませんでした","role":"ending","meaning":"dulu bukan","reading":"ja arimasen deshita"}],"translation":"Tuan Tanaka dulu bukan dokter."},{"tokens":[{"jp":"せんしゅう","role":"time","meaning":"minggu lalu","reading":"senshuu"},{"jp":"の","role":"particle","meaning":"(penghubung)","reading":"no"},{"jp":"テスト","role":"topic","meaning":"ujian","reading":"tesuto"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"かんたん","role":"adjective","meaning":"mudah","reading":"kantan"},{"jp":"ではありませんでした","role":"ending","meaning":"tidak (lampau)","reading":"dewa arimasen deshita"}],"translation":"Ujian minggu lalu tidak mudah."}],"when_to_use":["Saat membantah status atau jabatan di masa lalu (dulu bukan murid)","Saat menjelaskan bahwa kemarin atau minggu lalu libur atau bukan hari kerja","Saat menjawab pertanyaan masa lampau dengan sopan secara formal"],"formula_parts":[{"role":"topic","text":"Topik は","label":"Hal yang dibahas"},{"role":"predicate","text":"Kata Benda / Sifat-Na","label":"Predikat awal"},{"role":"ending","text":"ではありませんでした","label":"Bukan (dulu / lampau)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('b24507cb-1868-40ca-b1b9-3288ae4b0640', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-003', 'particle', 'Partikel NO (Kepemilikan & Kualifikasi)', '[Kata Benda 1] + の + [Kata Benda 2]', 'Partikel の (no) menghubungkan dua kata benda untuk menyatakan kepemilikan, asal, atau atribut penjelasan (misal: わたし の なまえ = nama saya).', 3, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Ini adalah buku bahasa Jepang.","jp":"これは にほんご の ほん です。","reading":"Kore wa nihongo no hon desu."},{"id":"Kunci saya ada di atas meja.","jp":"わたしの かぎ は つくえの うえです。","reading":"Watashi no kagi wa tsukue no ue desu."}]'::jsonb, '[Kata Benda 1] + no + [Kata Benda 2]', '{"quiz":[{"why":"Penjelas (くるま = mobil) ditaruh di depan, lalu の, lalu benda inti (かぎ = kunci).","answer":2,"options":["かぎのくるま","くるまのはかぎ","くるまのかぎ","かぎをくるま"],"question":"Bagaimana cara mengatakan ''Kunci mobil'' dalam bahasa Jepang (くるま = mobil, かぎ = kunci)?"},{"why":"わたしのくるま berarti mobil milik saya.","answer":1,"options":["Mobil itu milik dia","Itu adalah mobil saya","Saya punya banyak mobil","Di mana mobil saya?"],"question":"Pilih arti yang tepat untuk kalimat ''あれは わたし の くるま です'':"},{"why":"だれ (siapa) + の (milik) = punya siapa. Benda di belakang の boleh disingkat bila sudah jelas dari konteks.","answer":0,"options":["これは だれのですか","だれは これですか","これの だれですか","だれを これですか"],"question":"Kalimat ''Ini milik siapa?'' dalam bahasa Jepang adalah:"}],"forms":[{"id":"pulpen saya","jp":"わたしのペン","label":"Kepemilikan","reading":"watashi no pen"},{"id":"buku bahasa Jepang","jp":"にほんごのほん","label":"Isi/Topik","reading":"nihongo no hon"},{"id":"pulpen milik siapa?","jp":"だれのペンですか","label":"Tanya Pemilik","reading":"dare no pen desu ka"}],"steps":["Siapkan dua kata benda: siapa pemilik/penjelasnya, dan apa benda intinya.","Balik posisinya ala Jepang: taruh pemilik/penjelas di DEPAN.","Sisipkan の di tengah, lalu taruh benda intinya di BELAKANG."],"analogy":"の itu mirip kata ''punya'' atau ''dari'', tapi URUTANNYA DIBALIK dibanding bahasa Indonesia! Pemilik atau penjelasnya ditaruh di DEPAN, sedangkan benda utamanya ditaruh di BELAKANG.","mistakes":[{"why":"Bukan urutan Indonesia (''buku saya''), dalam bahasa Jepang pemilik (watashi) harus sebelum の.","right":"わたしのほん","wrong":"ほんのわたし"},{"why":"の hanya menyambungkan dua KATA BENDA. Kata sifat-i (ookii) langsung menempel tanpa の.","right":"おおきいくるま","wrong":"おおきいのくるま"}],"breakdowns":[{"tokens":[{"jp":"わたし","role":"noun","meaning":"saya","reading":"watashi"},{"jp":"の","role":"particle","meaning":"milik","reading":"no"},{"jp":"かばん","role":"noun","meaning":"tas","reading":"kaban"}],"translation":"Tas saya (tas milik saya)"},{"tokens":[{"jp":"これ","role":"topic","meaning":"ini","reading":"kore"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"さくらだいがく","role":"noun","meaning":"Univ. Sakura","reading":"Sakura Daigaku"},{"jp":"の","role":"particle","meaning":"dari","reading":"no"},{"jp":"パンフレット","role":"predicate","meaning":"brosur","reading":"panfuretto"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Ini adalah brosur Universitas Sakura."},{"tokens":[{"jp":"やまださん","role":"topic","meaning":"Tuan Yamada","reading":"Yamada-san"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"東京","role":"place","meaning":"Tokyo","reading":"Toukyou"},{"jp":"の","role":"particle","meaning":"asal/dari","reading":"no"},{"jp":"かいしゃいん","role":"predicate","meaning":"karyawan kantor","reading":"kaishain"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Tuan Yamada adalah karyawan kantor dari Tokyo."}],"when_to_use":["Menyatakan kepemilikan barang (buku milik saya, tas milik Budi)","Menyatakan afiliasi kantor/kampus/negara (mahasiswa Universitas Tokyo)","Menjelaskan jenis atau isi benda (buku tentang bahasa Jepang, kunci mobil)"],"formula_parts":[{"role":"noun","text":"Kata Benda 1","label":"Pemilik / Penjelas"},{"role":"particle","text":"の","label":"Penghubung (no)"},{"role":"noun","text":"Kata Benda 2","label":"Benda utama"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('56f9b781-8683-4704-beba-3643ccc0fd9e', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-004', 'particle', 'Partikel WO (Objek Penderita)', '[Objek] + を + [Verba Transitif]', 'Partikel を (dibaca o/wo) menandai objek langsung penderita tindakan kata kerja (misal: みず を のみます = minum air).', 4, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Setiap pagi saya minum kopi.","jp":"まいあさ コーヒーを のみます。","reading":"Maiasa koohii o nomimasu."},{"id":"Saya membaca buku di perpustakaan.","jp":"としょかんで ほんを よみます。","reading":"Toshokan de hon o yomimasu."}]'::jsonb, '[Objek] + o + [Verba Transitif]', '{"quiz":[{"why":"Koran (しんぶん) adalah benda yang langsung dibaca (objek), jadi ditandai dengan を.","answer":1,"options":["は","を","の","で"],"question":"Pilih partikel yang tepat untuk kalimat ''Saya membaca koran'' (しんぶん = koran, よみます = membaca):"},{"why":"を hanya berfungsi sebagai partikel (dibaca o), berbeda dari お dalam kosakata biasa.","answer":1,"options":["お","を","は","へ"],"question":"Huruf Hiragana manakah yang khusus dipakai hanya sebagai partikel penanda objek?"},{"why":"Objek (おちゃ) + を + kata kerja (のみます).","answer":3,"options":["のみます おちゃを","おちゃお のみます","おちゃは のみます","おちゃを のみます"],"question":"Susunan yang benar untuk ''Minum teh hijau (おちゃ)'' adalah:"}],"forms":[{"id":"makan roti","jp":"パンをたべます","label":"Sekarang","reading":"pan o tabemasu"},{"id":"tidak makan roti","jp":"パンをたべません","label":"Negatif","reading":"pan o tabemasen"},{"id":"sudah makan roti","jp":"パンをたべました","label":"Lampau","reading":"pan o tabemashita"}],"steps":["Tentukan benda apa yang dikenai pekerjaan (misal: kopi, majalah, lagu).","Tempelkan partikel を (huruf khusus wo, dibaca ''o'') tepat setelah benda itu.","Tutup dengan kata kerjanya di bagian paling belakang kalimat."],"analogy":"を (dibaca o) itu seperti penunjuk ''sasaran aksi''. Kalau dalam bahasa Indonesia kita bilang ''makan nasi'', di Jepang objeknya disebut dulu lalu ditempeli を, baru kata kerjanya: ''nasi を makan''.","mistakes":[{"why":"Walau dibaca ''o'', sebagai partikel objek wajib ditulis pakai huruf を (bukan お).","right":"コーヒーを のみます","wrong":"コーヒーお のみます"},{"why":"Dalam bahasa Jepang, kata kerja selalu berada di akhir kalimat, sesudah objek.","right":"コーヒーを のみます","wrong":"のみます コーヒーを"}],"breakdowns":[{"tokens":[{"jp":"みず","role":"object","meaning":"air","reading":"mizu"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"のみます","role":"verb","meaning":"minum","reading":"nomimasu"}],"translation":"Minum air."},{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"あさごはん","role":"object","meaning":"sarapan","reading":"asagohan"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"たべます","role":"verb","meaning":"makan","reading":"tabemasu"}],"translation":"Saya makan sarapan."},{"tokens":[{"jp":"まいばん","role":"time","meaning":"setiap malam","reading":"maiban"},{"jp":"にほんご","role":"object","meaning":"bahasa Jepang","reading":"nihongo"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"べんきょうします","role":"verb","meaning":"belajar","reading":"benkyou shimasu"}],"translation":"Setiap malam saya belajar bahasa Jepang."}],"when_to_use":["Saat menyatakan aktivitas yang langsung mengenai benda (makan roti, minum teh)","Saat membaca, menonton, membeli, atau menulis sesuatu","Saat kalimat membutuhkan objek yang dikenai tindakan kata kerja"],"formula_parts":[{"role":"object","text":"Objek","label":"Benda sasaran aksi"},{"role":"particle","text":"を","label":"Penanda objek (o)"},{"role":"verb","text":"Kata Kerja","label":"Aksi transitif"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('05ca9c23-60a3-4eb9-bc58-259bbf0033c9', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-005', 'particle', 'Partikel NI / HE (Tujuan Arah Perpindahan)', '[Tempat] + に / へ + いきます / きます', 'Partikel に (ni) atau へ (e) menunjukkan tempat tujuan arah perpindahan fisik.', 5, '2026-11-16T14:02:48.021082+00:00', '[{"id":"Setiap hari pergi ke kantor naik kereta.","jp":"まいにち でんしゃで かいしゃへ いきます。","reading":"Mainichi densha de kaisha e ikimasu."},{"id":"Tahun depan datang ke Jepang.","jp":"らいねん 日本に きます。","reading":"Rainen Nihon ni kimasu."}]'::jsonb, '[Tempat] + ni / e + ikimasu / kimasu', '{"quiz":[{"why":"Ketika menjadi partikel penunjuk arah, huruf へ dilafalkan sebagai ''e''.","answer":1,"options":["he","e","ni","wa"],"question":"Bagaimana bacaan huruf へ saat berada di kalimat にほんへ いきます?"},{"why":"Untuk tujuan perpindahan tempat dengan verba いきます, gunakan に atau へ.","answer":2,"options":["かいしゃを いきます","かいしゃで いきます","かいしゃに いきます","かいしゃは いきます"],"question":"Kalimat mana yang benar untuk ''Pergi ke perusahaan''?"},{"why":"かえります berarti pulang (ke rumah atau negara asal).","answer":0,"options":["かえります","のみます","よみます","あります"],"question":"Kata kerja apa yang cocok untuk kalimat ''うちへ ___'' saat pulang ke rumah?"}],"forms":[{"id":"pergi ke sekolah","jp":"がっこうへいきます","label":"Pergi","reading":"gakkou e ikimasu"},{"id":"datang ke sini","jp":"ここへきます","label":"Datang","reading":"koko e kimasu"},{"id":"pulang ke negara asal","jp":"くにへかえります","label":"Pulang","reading":"kuni e kaerimasu"}],"steps":["Tentukan tempat tujuanmu (misal: stasiun, Jepang, rumah).","Tambahkan に (fokus titik tujuan) atau へ (tulis ''he'', tapi wajib baca ''e'', fokus ke arahnya).","Akhiri dengan kata kerja berpindah: いきます (pergi), きます (datang), atau かえります (pulang)."],"analogy":"Partikel に / へ artinya sama persis dengan kata depan ''ke'' dalam bahasa Indonesia. Dipakai di belakang nama tempat sebelum kata kerja berpindah (pergi, datang, pulang).","mistakes":[{"why":"Partikel arah dibaca ''e'', tetapi penulisan Hiragananya wajib へ (bukan え).","right":"スーパーへ いきます","wrong":"スーパーえ いきます"},{"why":"で dipakai untuk alat transportasi atau tempat aktivitas di dalam lokasi, bukan untuk arah tujuan perpindahan.","right":"えきに / へ いきます","wrong":"えきで いきます"}],"breakdowns":[{"tokens":[{"jp":"きょうと","role":"place","meaning":"Kyoto","reading":"Kyouto"},{"jp":"へ","role":"particle","meaning":"ke arah","reading":"e"},{"jp":"いきます","role":"verb","meaning":"pergi","reading":"ikimasu"}],"translation":"Pergi ke Kyoto."},{"tokens":[{"jp":"らいげつ","role":"time","meaning":"bulan depan","reading":"raigetsu"},{"jp":"にほん","role":"place","meaning":"Jepang","reading":"Nihon"},{"jp":"に","role":"particle","meaning":"ke","reading":"ni"},{"jp":"きます","role":"verb","meaning":"datang","reading":"kimasu"}],"translation":"Bulan depan datang ke Jepang."},{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"うち","role":"place","meaning":"rumah","reading":"uchi"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"かえります","role":"verb","meaning":"pulang","reading":"kaerimasu"}],"translation":"Saya pulang ke rumah."}],"when_to_use":["Menyatakan tujuan pergi ke kantor, sekolah, toko, atau Jepang","Menyatakan datang ke rumah teman atau kantor","Menyatakan pulang ke kampung halaman atau ke rumah"],"formula_parts":[{"role":"place","text":"Tempat Tujuan","label":"Lokasi yang dituju"},{"role":"particle","text":"に / へ","label":"Penanda arah (ni / e)"},{"role":"verb","text":"いきます・きます・かえります","label":"Verba perpindahan"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('e612bfa2-c788-4a37-bfb2-06d24ea5a108', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-006', 'conjugation', 'Konjugasi Verba Formal (-MASU / -MASEN)', '[Akar Kata Kerja] + ます / ません', 'Bentuk sopan formal kata kerja untuk menyatakan kegiatan rutin harian atau kebiasaan saat ini dan masa depan (misal: たべます = makan, たべません = tidak makan).', 6, '2026-11-16T14:02:48.199664+00:00', '[{"id":"Setiap malam belajar bahasa Jepang.","jp":"まいばん にほんごを べんきょうします。","reading":"Maiban nihongo o benkyou shimasu."},{"id":"Tadi pagi saya tidak sarapan.","jp":"けさ あさごはんを たべませんでした。","reading":"Kesa asagohan o tabemasen deshita."}]'::jsonb, '[Akar Kata Kerja] + masu / masen', '{"quiz":[{"why":"Akhiran ます langsung diganti menjadi ません untuk bentuk negatif sopan.","answer":0,"options":["よみません","よみではない","よむません","よみました"],"question":"Bagaimana bentuk negatif sopan dari よみます (membaca)?"},{"why":"Negasi lampau sopan kata kerja adalah ～ませんでした.","answer":2,"options":["きのう テレビを みません","きのう テレビを みました","きのう テレビを みませんでした","きのう テレビを みます"],"question":"Kalimat mana yang menyatakan ''Kemarin tidak menonton TV''?"},{"why":"Bentuk ～ます berfungsi untuk kebiasaan masa kini maupun rencana yang akan datang.","answer":1,"options":["Hanya untuk kejadian kemarin","Untuk kebiasaan sekarang & rencana masa depan","Khusus kalimat perintah saja","Hanya dengan kata benda"],"question":"Kapan bentuk positif ～ます digunakan?"}],"forms":[{"id":"tidur","jp":"ねます","label":"Positif","reading":"nemasu"},{"id":"tidak tidur","jp":"ねません","label":"Negatif","reading":"nemasen"},{"id":"sudah tidur","jp":"ねました","label":"Lampau (+)","reading":"nemashita"},{"id":"kemarin tidak tidur","jp":"ねませんでした","label":"Lampau (-)","reading":"nemasen deshita"}],"steps":["Ambil akar kata kerja bentuk sopan (misal: tabe-, nomi-, yomi-).","Tambahkan ～ます untuk arti positif (''melakukan / akan melakukan'').","Ganti menjadi ～ません untuk arti negatif (''tidak melakukan / tidak akan melakukan'')."],"analogy":"Akhiran ～ます itu seperti tanda kalimat sopan untuk kata kerja (kegiatan rutin atau rencana), sedangkan mengubahnya ke ～ません artinya menambahkan kata ''tidak''.","mistakes":[{"why":"Kata kerja tidak dinegasikan dengan ありません, cukup ubah akhiran ます menjadi ません.","right":"たべません","wrong":"たべます ありません"},{"why":"Bentuk ます sudah mencakup masa depan (''akan makan''); tidak ada bentuk です atau でした di belakang ます.","right":"あした たべます","wrong":"あした たべます でした"}],"breakdowns":[{"tokens":[{"jp":"あさ","role":"time","meaning":"pagi","reading":"asa"},{"jp":"おきます","role":"verb","meaning":"bangun","reading":"okimasu"}],"translation":"Bangun di pagi hari."},{"tokens":[{"jp":"さけ","role":"object","meaning":"alkohol/sake","reading":"sake"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"のみません","role":"verb","meaning":"tidak minum","reading":"nomimasen"}],"translation":"Saya tidak minum alkohol."},{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"まいにち","role":"time","meaning":"setiap hari","reading":"mainichi"},{"jp":"テレビ","role":"object","meaning":"TV","reading":"terebi"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"みます","role":"verb","meaning":"menonton","reading":"mimasu"}],"translation":"Setiap hari saya menonton TV."}],"when_to_use":["Menceritakan kebiasaan harian (setiap hari bangun jam 6, makan pagi)","Menyatakan rencana kegiatan hari ini atau besok secara sopan","Menolak atau menyatakan tidak melakukan kegiatan tertentu"],"formula_parts":[{"role":"verb","text":"Akar Kata Kerja","label":"Inti aksi"},{"role":"ending","text":"ます / ません","label":"Positif / Tidak (sopan)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('33006568-75f9-4aa3-8d11-4b029168a7d4', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-007', 'particle', 'Partikel DE (Sarana & Lokasi Tindakan)', '[Sarana/Alat] + で / [Tempat] + で + [Verba]', 'Partikel で (de) memiliki 2 fungsi utama: menandai sarana/alat transportasi (misal: でんしゃ で = dengan kereta) dan menandai tempat berlangsungnya suatu aksi aktif (misal: カフェ で たべます = makan di kafe).', 7, '2026-11-16T14:02:48.199664+00:00', '[{"id":"Pergi sampai bandara naik kereta bawah tanah.","jp":"ちかてつで くうこうまで いきます。","reading":"Chikatetsu de kuukou made ikimasu."},{"id":"Menulis laporan di kafe.","jp":"カフェで レポートを かきます。","reading":"Kafe de repooto o kakimasu."}]'::jsonb, '[Sarana/Alat] + de / [Tempat] + de + [Verba]', '{"quiz":[{"why":"Kafetaria adalah tempat berlangsungnya kegiatan aktif (makan), jadi pakai で.","answer":2,"options":["に","を","で","へ"],"question":"Partikel yang tepat untuk ''Makan roti di kafetaria (しょくどう)'' adalah:"},{"why":"Pulpen adalah alat untuk menulis, sehingga ditandai dengan で.","answer":1,"options":["ペンに てがみを かきます","ペンで てがみを かきます","ペンを てがみを かきます","ペンは てがみを かきます"],"question":"Bagaimana mengatakan ''Menulis surat dengan pulpen (ペン)''?"},{"why":"Pengecualian penting: ''berjalan kaki'' adalah あるいて (tanpa で).","answer":2,"options":["あるいてで かえります","あるいてをかえります","あるいて かえります","あるくで かえります"],"question":"Manakah kalimat tentang perjalanan kaki yang alami?"}],"forms":[{"id":"pergi naik bus","jp":"バスでいきます","label":"Transportasi","reading":"basu de ikimasu"},{"id":"berbicara dalam bahasa Jepang","jp":"にほんごではなします","label":"Bahasa / Alat","reading":"nihongo de hanashimasu"},{"id":"minum di kafe","jp":"カフェでのみます","label":"Lokasi Aksi","reading":"kafe de nomimasu"}],"steps":["Bedakan peran: apakah benda itu sarana/alat, atau tempat aktivitas aktif?","Taruh sarana/alat atau tempat aktivitas di depan, lalu tempelkan で.","Tambahkan objek (jika ada) dan akhiri dengan kata kerja."],"analogy":"Partikel で punya dua arti praktis dalam bahasa Indonesia: ''naik/memakai ...'' (sarana/alat) dan ''di ...'' khusus ketika ada aktivitas yang dilakukan di tempat itu.","mistakes":[{"why":"Jalan kaki (aruite) adalah bentuk kata kerja, jadi tidak perlu ditempeli partikel で.","right":"あるいて いきます","wrong":"あるいてで いきます"},{"why":"あります/います (keberadaan diam) memakai に, bukan で. Partikel で khusus untuk lokasi tindakan aktif.","right":"へやに あります","wrong":"へやで あります"}],"breakdowns":[{"tokens":[{"jp":"でんしゃ","role":"noun","meaning":"kereta listrik","reading":"densha"},{"jp":"で","role":"particle","meaning":"naik / dengan","reading":"de"},{"jp":"いきます","role":"verb","meaning":"pergi","reading":"ikimasu"}],"translation":"Pergi naik kereta."},{"tokens":[{"jp":"はし","role":"noun","meaning":"sumpit","reading":"hashi"},{"jp":"で","role":"particle","meaning":"memakai","reading":"de"},{"jp":"ごはん","role":"object","meaning":"nasi","reading":"gohan"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"たべます","role":"verb","meaning":"makan","reading":"tabemasu"}],"translation":"Makan nasi memakai sumpit."},{"tokens":[{"jp":"としょかん","role":"place","meaning":"perpustakaan","reading":"toshokan"},{"jp":"で","role":"particle","meaning":"di (tempat aksi)","reading":"de"},{"jp":"ともだち","role":"noun","meaning":"teman","reading":"tomodachi"},{"jp":"と","role":"particle","meaning":"bersama","reading":"to"},{"jp":"べんきょうします","role":"verb","meaning":"belajar","reading":"benkyou shimasu"}],"translation":"Belajar bersama teman di perpustakaan."}],"when_to_use":["Naik kendaraan menuju suatu tempat (naik kereta, naik bus, jalan kaki)","Memakai alat atau bahasa saat beraktivitas (makan pakai sumpit, bicara pakai bahasa Jepang)","Menyebut lokasi tempat terjadinya aktivitas (makan di restoran, belajar di perpustakaan)"],"formula_parts":[{"role":"place","text":"Alat / Lokasi Aksi","label":"Sarana atau tempat aktif"},{"role":"particle","text":"で","label":"Dengan / Di (de)"},{"role":"verb","text":"Kata Kerja Aksi","label":"Kegiatan berlangsung"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('79e54427-faad-401e-b423-a97ff3e695d8', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-008', 'particle', 'Partikel NI (Waktu Spesifik & Titik Jam)', '[Angka Jam / Hari] + に + [Verba]', 'Partikel に (ni) dilekatkan pada angka jam atau hari kalender spesifik untuk menunjukkan titik waktu dilakukannya kegiatan (misal: ７じ に おきます = bangun jam 7).', 8, '2026-11-16T14:02:48.199664+00:00', '[{"id":"Setiap pagi bangun pada jam 6.","jp":"まいあさ ６じに おきます。","reading":"Maiasa rokuji ni okimasu."},{"id":"Pada hari Jumat ada rapat.","jp":"きんようびに かいぎが あります。","reading":"Kinyoubi ni kaigi ga arimasu."}]'::jsonb, '[Angka Jam / Hari] + ni + [Verba]', '{"quiz":[{"why":"しちじ (jam 7) adalah titik angka jam spesifik, sehingga wajib pakai に.","answer":2,"options":["まいにちに にほんごを べんきょうします","あしたに とうきょうへ いきます","しちじに あさごはんを たべます","きのうに ともだちと あそびました"],"question":"Kalimat mana yang BENAR penggunaan partikel waktunya?"},{"why":"らいしゅう (minggu depan) bersifat relatif terhadap pembicara, tidak memakai に.","answer":1,"options":["に","(tidak perlu partikel)","で","を"],"question":"Lengkapi: ''らいしゅう ___ テストが あります'' (Minggu depan ada ujian)."},{"why":"なんじ (jam berapa) adalah kata tanya titik jam, sehingga diikuti に.","answer":0,"options":["なんじに ねますか","なんじで ねますか","いつに ねますか","なんじを ねますか"],"question":"Cara menanyakan ''Jam berapa kamu tidur?'' dengan sopan adalah:"}],"forms":[{"id":"tidur jam 9","jp":"くじにねます","label":"Pakai に (Jam)","reading":"kuji ni nemasu"},{"id":"pergi tanggal 4","jp":"よっかにいきます","label":"Pakai に (Tanggal)","reading":"yokka ni ikimasu"},{"id":"besok pergi (tanpa に)","jp":"あしたいきます","label":"Tanpa に (Relatif)","reading":"ashita ikimasu"}],"steps":["Cek dulu apakah waktunya punya angka jam, tanggal, atau nama hari.","Jika iya (seperti ろくじ = jam 6, にちようび = hari Minggu), tempelkan に.","Jika waktunya relatif tanpa angka (きょう = hari ini, まいにち = setiap hari, きのう = kemarin), JANGAN pakai に."],"analogy":"Partikel に di depan waktu mirip seperti kata ''pada pukul...'' atau ''di hari...'' ketika jadwalnya berupa titik angka jam atau nama hari spesifik.","mistakes":[{"why":"Kata waktu relatif seperti きょう (hari ini), あした (besok), きのう (kemarin), まいにち (setiap hari) tidak pernah memakai partikel に.","right":"きょう べんきょうします","wrong":"きょうに べんきょうします"},{"why":"Untuk menanyakan titik jam, partikelnya adalah に (nanji ni), bukan で.","right":"なんじに おきますか","wrong":"なんじで おきますか"}],"breakdowns":[{"tokens":[{"jp":"ろくじ","role":"time","meaning":"jam 6","reading":"rokuji"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"おきます","role":"verb","meaning":"bangun","reading":"okimasu"}],"translation":"Bangun pada jam 6."},{"tokens":[{"jp":"まいあさ","role":"time","meaning":"setiap pagi","reading":"maiasa"},{"jp":"はちじはん","role":"time","meaning":"jam 8.30","reading":"hachijihan"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"いえ","role":"place","meaning":"rumah","reading":"ie"},{"jp":"を","role":"particle","meaning":"dari (keluar)","reading":"o"},{"jp":"でます","role":"verb","meaning":"keluar/berangkat","reading":"demasu"}],"translation":"Setiap pagi berangkat dari rumah pukul 8.30."},{"tokens":[{"jp":"にちようび","role":"time","meaning":"hari Minggu","reading":"nichiyoubi"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"ともだち","role":"noun","meaning":"teman","reading":"tomodachi"},{"jp":"に","role":"particle","meaning":"dengan (bertemu)","reading":"ni"},{"jp":"あいます","role":"verb","meaning":"bertemu","reading":"aimasu"}],"translation":"Pada hari Minggu bertemu teman."}],"when_to_use":["Menyebut jam bangun tidur, mulai kerja, atau jadwal kereta","Menyebut tanggal, bulan, atau hari spesifik dilakukannya janji","Menjelaskan rentang atau titik kapan suatu pertemuan dimulai"],"formula_parts":[{"role":"time","text":"Titik Waktu","label":"Jam / Tanggal / Hari"},{"role":"particle","text":"に","label":"Pada (ni)"},{"role":"verb","text":"Kata Kerja","label":"Kegiatan sesuai jadwal"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('dda49c88-24d5-4407-9778-faaec686ad7f', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-009', 'sentence_pattern', 'Keberadaan Benda & Makhluk Hidup (あります・います)', '[Tempat] に [Benda/Orang] が あります / います', 'Gunakan あります untuk benda mati/tumbuhan dan います untuk manusia/hewan guna menyatakan keberadaan di suatu lokasi.', 9, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Di atas meja ada laptop.","jp":"つくえの うえに パソコンが あります。","reading":"Tsukue no ue ni pasokon ga arimasu."},{"id":"Di kantor ada Tuan Tanaka.","jp":"じむしょに たなかさんが います。","reading":"Jimusho ni Tanaka-san ga imasu."}]'::jsonb, '[Tempat] ni [Benda/Orang] ga arimasu / imasu', '{"quiz":[{"why":"Pak Tanaka adalah manusia (makhluk hidup), jadi wajib memakai います.","answer":1,"options":["あります","います","です","します"],"question":"Lengkapi: ''じむしょに たなかさんが ___'' (Di kantor ada Pak Tanaka)."},{"why":"Tumbuhan yang tidak berpindah tempat sendiri dihitung benda non-animasi dan memakai あります.","answer":1,"options":["います","あります","いきます","します"],"question":"Bunga atau pohon di taman memakai verba yang mana?"},{"why":"Bentuk negatif dari あります adalah ありません.","answer":0,"options":["おかねが ありません","おかねが いません","おかねではありません","おかねが なしです"],"question":"Bagaimana mengatakan ''Tidak ada uang'' dengan sopan?"}],"forms":[{"id":"ada waktu / sempat","jp":"じかんがあります","label":"Benda (+)","reading":"jikan ga arimasu"},{"id":"tidak ada waktu","jp":"じかんがありません","label":"Benda (-)","reading":"jikan ga arimasen"},{"id":"punya saudara","jp":"きょうだいがいます","label":"Orang (+)","reading":"kyoudai ga imasu"},{"id":"tidak ada siapa-siapa","jp":"だれもいません","label":"Orang (-)","reading":"dare mo imasen"}],"steps":["Sebutkan lokasinya dulu diikuti partikel に (bukan で).","Sebutkan benda atau makhluk yang ada, lalu tempelkan partikel が.","Pilih kata kerja penutupnya: あります untuk benda mati/acara/waktu, atau います untuk manusia/hewan."],"analogy":"Di bahasa Indonesia kita cukup bilang ''ada'', tapi di Jepang dibedakan: あります (arimasu) untuk benda mati & tumbuhan yang diam, sedangkan います (imasu) khusus manusia & hewan yang bisa bergerak sendiri.","mistakes":[{"why":"Anjing adalah makhluk hidup bernyawa, jadi wajib memakai います, bukan あります.","right":"こうえんに いぬが います","wrong":"こうえんに いぬが あります"},{"why":"Untuk sekadar menyatakan ''berada di tempat'', gunakan に. Partikel で hanya dipakai jika ada tindakan aktif (seperti mengajar).","right":"きょうしつに せんせいが います","wrong":"きょうしつで せんせいが います"}],"breakdowns":[{"tokens":[{"jp":"へや","role":"place","meaning":"kamar","reading":"heya"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"いす","role":"subject","meaning":"kursi","reading":"isu"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あります","role":"verb","meaning":"ada (benda mati)","reading":"arimasu"}],"translation":"Di kamar ada kursi."},{"tokens":[{"jp":"にわ","role":"place","meaning":"halaman","reading":"niwa"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"ねこ","role":"subject","meaning":"kucing","reading":"neko"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"います","role":"verb","meaning":"ada (hewan)","reading":"imasu"}],"translation":"Di halaman ada kucing."},{"tokens":[{"jp":"つくえ","role":"noun","meaning":"meja","reading":"tsukue"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"うえ","role":"place","meaning":"atas","reading":"ue"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"ほん","role":"subject","meaning":"buku","reading":"hon"},{"jp":"と","role":"particle","meaning":"dan","reading":"to"},{"jp":"かぎ","role":"subject","meaning":"kunci","reading":"kagi"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あります","role":"verb","meaning":"ada","reading":"arimasu"}],"translation":"Di atas meja ada buku dan kunci."}],"when_to_use":["Menyebut benda apa yang ada di atas meja atau di dalam kamar","Menyebut apakah seseorang atau hewan peliharaan sedang berada di suatu tempat","Menanyakan letak fasilitas umum (toilet, ATM, stasiun) atau keberadaan keluarga"],"formula_parts":[{"role":"place","text":"Tempat","label":"Lokasi keberadaan"},{"role":"particle","text":"に","label":"Di (khusus diam)"},{"role":"subject","text":"Benda / Makhluk","label":"Yang ada di sana"},{"role":"particle","text":"が","label":"Penanda subjek"},{"role":"verb","text":"あります / います","label":"Ada (mati / hidup)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('dd9fe2c9-ae3f-438c-9f46-0fdd53524078', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-010', 'particle', 'Partikel TO & YA (Daftar Lengkap vs Contoh)', '[Benda A] と [Benda B] / [Benda A] や [Benda B] など', 'Partikel と menyebut semua item secara lengkap ("dan"), sedangkan や (... など) menyebut sebagian contoh representatif.', 10, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Di tas ada buku catatan dan pulpen (lengkap).","jp":"かばんに ノートと ペンが あります。","reading":"Kaban ni nooto to pen ga arimasu."},{"id":"Di kamar ada kasur, meja, dan lain-lain.","jp":"へやに ベッドや つくえなどが あります。","reading":"Heya ni beddo ya tsukue nado ga arimasu."}]'::jsonb, '[Benda A] to [Benda B] / [Benda A] ya [Benda B] nado', '{"quiz":[{"why":"と digunakan ketika daftar benda yang disebut lengkap tidak ada tambahannya.","answer":1,"options":["や","と","か","の"],"question":"Kalau di kotak pensil hanya ada tepat 2 benda (pensil & penghapus), partikel penyambungnya adalah:"},{"why":"Untuk menyebutkan sebagian contoh dari banyak benda, pakai [A] や [B] など.","answer":2,"options":["れいぞうこに ぎゅうにゅうと チーズと りんご だけ あります","れいぞうこに ぎゅうにゅうを チーズが あります","れいぞうこに ぎゅうにゅうや チーズなど が あります","れいぞうこに ぎゅうにゅうの チーズなど あります"],"question":"Manakah kalimat yang paling alami untuk ''Di kulkas ada susu, keju, apel, dan masih banyak lagi''?"},{"why":"と penyambung daftar hanya boleh dipakai di antara kata benda (untuk kata kerja nanti pakai bentuk-TE).","answer":3,"options":["Bisa kalau formal","Bisa kalau di akhir kalimat","Hanya saat lampau","Tidak bisa, と khusus menyambung kata benda"],"question":"Bisakah partikel と dipakai menyambung dua kata kerja (misal: ''makan と minum'')?"}],"forms":[{"id":"kopi dan teh (hanya 2 itu)","jp":"コーヒーとこうちゃ","label":"Daftar Penuh (と)","reading":"koohii to koucha"},{"id":"kopi, teh, dan lain-lain","jp":"コーヒーやこうちゃなど","label":"Contoh (や～など)","reading":"koohii ya koucha nado"}],"steps":["Tentukan apakah daftarnya sudah komplet 100% atau hanya contoh saja.","Kalau komplet (cuma dua itu saja), sambungkan dengan と.","Kalau cuma sebut beberapa contoh dari banyak hal, sambungkan dengan や lalu tutup dengan など sebelum partikel berikutnya."],"analogy":"と berarti ''dan'' untuk menyebutkan SEMUA barang yang ada (daftar lengkap, habis tidak ada sisanya). Sedangkan や (...など) artinya ''...dan lain-lain'' (hanya ambil 2–3 contoh perwakilan saja).","mistakes":[{"why":"と hanya menyambungkan KATA BENDA, tidak boleh menyambung dua kata sifat atau dua kalimat.","right":"おおきくて きれいです","wrong":"おおきいと きれいです"},{"why":"Pasangan alami kata など (''dan lain-lain'') adalah や, bukan と.","right":"りんごや みかん など を たべました","wrong":"りんごと みかん など を たべました"}],"breakdowns":[{"tokens":[{"jp":"つくえ","role":"place","meaning":"meja","reading":"tsukue"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"うえ","role":"place","meaning":"atas","reading":"ue"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"ほん","role":"subject","meaning":"buku","reading":"hon"},{"jp":"と","role":"particle","meaning":"dan (lengkap)","reading":"to"},{"jp":"ペン","role":"subject","meaning":"pulpen","reading":"pen"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あります","role":"verb","meaning":"ada","reading":"arimasu"}],"translation":"Di atas meja hanya ada buku dan pulpen."},{"tokens":[{"jp":"スーパー","role":"place","meaning":"supermarket","reading":"suupaa"},{"jp":"で","role":"particle","meaning":"di","reading":"de"},{"jp":"パン","role":"object","meaning":"roti","reading":"pan"},{"jp":"や","role":"particle","meaning":"seperti... dan","reading":"ya"},{"jp":"たまご","role":"object","meaning":"telur","reading":"tamago"},{"jp":"など","role":"ending","meaning":"dll.","reading":"nado"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"かいました","role":"verb","meaning":"membeli","reading":"kaimashita"}],"translation":"Saya membeli roti, telur, dan lain-lain di supermarket."},{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"の","role":"particle","meaning":"milik","reading":"no"},{"jp":"まち","role":"noun","meaning":"kota","reading":"machi"},{"jp":"には","role":"particle","meaning":"di dalamnya","reading":"ni wa"},{"jp":"こうえん","role":"subject","meaning":"taman","reading":"kouen"},{"jp":"や","role":"particle","meaning":"antara lain","reading":"ya"},{"jp":"びじゅつかん","role":"subject","meaning":"museum seni","reading":"bijutsukan"},{"jp":"など","role":"ending","meaning":"dll.","reading":"nado"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"あります","role":"verb","meaning":"ada","reading":"arimasu"}],"translation":"Di kota saya ada taman, museum seni, dan lain sebagainya."}],"when_to_use":["Menyebut semua isi tas tanpa ada yang terlewat (pakai と)","Menyebut beberapa contoh makanan kesukaan atau barang di toko dari banyak pilihan (pakai や...など)","Memesan lebih dari satu item menu sekaligus"],"formula_parts":[{"role":"noun","text":"Benda A","label":"Item pertama"},{"role":"particle","text":"と / や","label":"Dan (lengkap) / Antara lain"},{"role":"noun","text":"Benda B","label":"Item kedua"},{"role":"ending","text":"(など)","label":"Dan lain-lain (opsional dgn や)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('eae4f656-7049-4859-b696-ebe9a71c4814', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-011', 'conjugation', 'Kata Sifat-I & Negasinya (～い / ～くないです)', '[Adjektiva-I (buang い)] + くないです / かったです', 'Untuk membentuk negatif kata sifat-い, ganti akhiran い dengan くないです; untuk lampau positif gunakan かったです (pengecualian: いい → よくない・よかった).', 11, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Kamar ini terang dan luas.","jp":"この へやは あかるくて ひろいです。","reading":"Kono heya wa akarukute hiroi desu."},{"id":"Hari ini udaranya tidak dingin.","jp":"きょうは さむくないです。","reading":"Kyou wa samukunai desu."}]'::jsonb, '[Adjektiva-I (buang -i)] + kunai desu / katta desu', '{"quiz":[{"why":"Buang い paling belakang dari おいしい lalu ganti dengan くないです.","answer":1,"options":["おいしい ではありません","おいしくないです","おいしいくないです","おいしではないです"],"question":"Bagaimana mengubah おいしい (enak) menjadi ''tidak enak''?"},{"why":"いい berubah akarnya menjadi よ- saat dikonjugasikan: よくないです.","answer":2,"options":["いくないです","いいくないです","よくないです","いいではありません"],"question":"Bentuk negatif dari いい (bagus/baik) adalah:"},{"why":"Buang い dari あつい menjadi あつ, lalu tambah かったです.","answer":3,"options":["きのうは とても あついでした","きのうは とても あつくです","きのうは とても あついかったです","きのうは とても あつかったです"],"question":"Untuk mengatakan ''Kemarin sangat panas (あつい)'', pilih bentuk yang tepat:"}],"forms":[{"id":"dingin","jp":"さむいです","label":"Positif","reading":"samui desu"},{"id":"tidak dingin","jp":"さむくないです","label":"Negatif","reading":"samukunai desu"},{"id":"kemarin dingin","jp":"さむかったです","label":"Lampau (+)","reading":"samukatta desu"},{"id":"kemarin tidak dingin","jp":"さむくなかったです","label":"Lampau (-)","reading":"samukunakatta desu"}],"steps":["Ambil kata sifat-i dan lepaskan huruf い paling belakang (misal: たかい → たか).","Untuk bilang ''tidak...'', tempelkan ～くないです (misal: たかくないです).","Untuk bilang ''dulu/kemarin...'', tempelkan ～かったです (misal: たかかったです). Ingat 1 pengecualian: いい (bagus) akarnya berubah jadi よ (よくないです / よかったです)."],"analogy":"Kata sifat berakhiran huruf ''i'' (seperti takai = mahal, samui = dingin) punya cara unik untuk bilang ''tidak'' atau ''kemarin'': buang huruf い paling belakang, lalu tukar dengan ekor baru (くない / かった).","mistakes":[{"why":"Kata sifat-i tidak memakai ではありません, melainkan mengubah akhiran い menjadi くないです.","right":"たかくないです","wrong":"たかい ではありません"},{"why":"Kata sifat いい (bagus/baik) bentuk dasarnya adalah よい, jadi saat berubah wajib memakai akar よ- → よくないです.","right":"よくないです","wrong":"いくないです / いきません (untuk いい)"}],"breakdowns":[{"tokens":[{"jp":"この","role":"noun","meaning":"ini","reading":"kono"},{"jp":"かばん","role":"topic","meaning":"tas","reading":"kaban"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"たかくないです","role":"adjective","meaning":"tidak mahal","reading":"takakunai desu"}],"translation":"Tas ini tidak mahal."},{"tokens":[{"jp":"きのう","role":"time","meaning":"kemarin","reading":"kinou"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"てんき","role":"topic","meaning":"cuaca","reading":"tenki"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"とても","role":"adjective","meaning":"sangat","reading":"totemo"},{"jp":"よかったです","role":"adjective","meaning":"bagus (lampau)","reading":"yokatta desu"}],"translation":"Cuaca kemarin sangat bagus."},{"tokens":[{"jp":"きょうと","role":"topic","meaning":"Kyoto","reading":"Kyouto"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"あたらしい","role":"adjective","meaning":"baru","reading":"atarashii"},{"jp":"まち","role":"predicate","meaning":"kota","reading":"machi"},{"jp":"ではありませんが","role":"connector","meaning":"bukan tapi","reading":"dewa arimasen ga"},{"jp":"おもしろかったです","role":"adjective","meaning":"menarik (lampau)","reading":"omoshirokatta desu"}],"translation":"Kyoto memang bukan kota baru, tapi sangat menarik."}],"when_to_use":["Menilai rasa makanan, cuaca, harga barang, atau ukuran benda","Menyangkal sifat sesuatu (''tidak mahal'', ''tidak enak'')","Menceritakan pengalaman yang sudah berlalu (''kemarin panas'', ''liburan kemarin menyenangkan'')"],"formula_parts":[{"role":"adjective","text":"Akar Sifat-い","label":"Buang huruf い akhir"},{"role":"ending","text":"くないです / かったです","label":"Tidak ... / Dulu ..."}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-012', 'sentence_pattern', 'Kata Sifat-Na & Perbandingan (～な / より / いちばん)', '[A] は [B] より [Adjektiva] です', 'Kata sifat-な memakai な saat menerangkan kata benda di depannya dan memakai ではありません untuk bentuk negatif sopan.', 12, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Kyoto adalah kota yang tenang.","jp":"きょうとは しずかな まちです。","reading":"Kyouto wa shizukana machi desu."},{"id":"Kereta lebih cepat daripada bus.","jp":"電車は バスより はやいです。","reading":"Densha wa basu yori hayai desu."}]'::jsonb, '[A] wa [B] yori [Adjektiva] desu', '{"quiz":[{"why":"ゆうめい adalah kata sifat-Na; bila menerangkan kata benda di belakangnya wajib menyisipkan な.","answer":2,"options":["ゆうめい ひと","ゆうめいの ひと","ゆうめいな ひと","ゆうめいく ひと"],"question":"Pilih frasa yang benar untuk ''Orang yang terkenal'' (ゆうめい = terkenal, ひと = orang):"},{"why":"A は B より [Sifat] artinya A lebih [Sifat] daripada B. Di sini A adalah kemarin (きのう).","answer":1,"options":["Hari ini lebih sejuk dari kemarin","Kemarin lebih sejuk daripada hari ini","Kemarin dan hari ini sama sejuknya","Kemarin tidak terlalu sejuk"],"question":"Apa arti kalimat ''きのうは きょうより すずしかったです''?"},{"why":"すき adalah kata sifat-Na dan objek kesukaan ditandai が, sehingga negasinya: すきではありません.","answer":1,"options":["さかなが すきくないです","さかなが すきでは ありません","さかなを すきます","さかなが すきな ではありません"],"question":"Manakah kalimat yang tepat untuk ''Saya tidak terlalu suka ikan (さかな)''?"}],"forms":[{"id":"kuil yang terkenal","jp":"ゆうめいな おてら","label":"Menerangkan Benda","reading":"yuumei na otera"},{"id":"tidak senggang","jp":"ひまでは ありません","label":"Negatif Sifat-Na","reading":"hima dewa arimasen"},{"id":"lebih besar dari Tokyo","jp":"東京より おおきいです","label":"Perbandingan","reading":"Toukyou yori ookii desu"}],"steps":["Untuk menerangkan kata benda dengan sifat-Na, sisipkan な di antara keduanya (しずかな まち = kota tenang). Hati-hati: きれい (cantik) dan ゆうめい (terkenal) ikut golongan Na meski berakhiran bunyi ''i''!","Untuk membandingkan dua hal: sebutkan A は B より [Sifat] です (''A lebih [Sifat] daripada B'').","Untuk menyebut ''paling...'': pakai [Kategori] の なかで [A] が いちばん [Sifat] です."],"analogy":"Kata sifat-Na (seperti kirei = cantik, shizuka = tenang) sifatnya persis seperti kata benda: kalau digabung ke benda di depannya minta bantuan ''な'', dan kalau negatif memakai ''ではありません''. Sementara より artinya ''lebih... daripada...''.","mistakes":[{"why":"きれい (indah/bersih) adalah pengecualian terkenal: ia kata sifat-Na, bukan sifat-I!","right":"きれいな はな / きれいではありません","wrong":"きれいの はな / きれくない"},{"why":"Huruf な hanya dipakai jika langsung menempel di depan kata benda. Di depan です, な dihilangkan.","right":"しずか です","wrong":"しずか です な"}],"breakdowns":[{"tokens":[{"jp":"ここ","role":"topic","meaning":"sini","reading":"koko"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"しずかな","role":"adjective","meaning":"yang tenang","reading":"shizuka na"},{"jp":"まち","role":"predicate","meaning":"kota","reading":"machi"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Di sini adalah kota yang tenang."},{"tokens":[{"jp":"しんかんせん","role":"topic","meaning":"kereta cepat","reading":"Shinkansen"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"バス","role":"noun","meaning":"bus","reading":"basu"},{"jp":"より","role":"connector","meaning":"daripada","reading":"yori"},{"jp":"はやい","role":"adjective","meaning":"lebih cepat","reading":"hayai"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Shinkansen lebih cepat daripada bus."},{"tokens":[{"jp":"スポーツ","role":"noun","meaning":"olahraga","reading":"supootsu"},{"jp":"の","role":"particle","meaning":"di","reading":"no"},{"jp":"なかで","role":"connector","meaning":"antara","reading":"naka de"},{"jp":"サッカー","role":"subject","meaning":"sepak bola","reading":"sakkaa"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"いちばん","role":"adjective","meaning":"paling","reading":"ichiban"},{"jp":"すき","role":"adjective","meaning":"disukai","reading":"suki"},{"jp":"です","role":"ending","meaning":"(sopan)","reading":"desu"}],"translation":"Di antara olahraga, saya paling suka sepak bola."}],"when_to_use":["Mendeskripsikan suasana tempat atau sifat orang dengan kata sifat-Na (terkenal, praktis, ramai)","Membandingkan dua hal: mana yang lebih murah, lebih jauh, atau lebih enak","Menyebutkan yang ''paling...'' di antara satu kategori (いちばん)"],"formula_parts":[{"role":"topic","text":"A は","label":"Yang dinilai"},{"role":"connector","text":"B より","label":"Daripada B"},{"role":"adjective","text":"Kata Sifat (+ な + Benda)","label":"Sifat pembanding"},{"role":"ending","text":"です","label":"(Sopan)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('a830983b-40e2-4080-a8a5-416276586f1a', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-013', 'sentence_pattern', 'Ajakan Sopan (～ませんか・～ましょう)', '[Akar Verba] + ませんか / ましょう', '～ませんか dipakai untuk mengajak lawan bicara secara halus ("Maukah...?"), sedangkan ～ましょう untuk ajakan aktif ("Mari kita...").', 13, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Maukah makan siang bersama?","jp":"いっしょに ひるごはんを たべませんか。","reading":"Issho ni hirugohan o tabemasen ka."},{"id":"Ayo beristirahat sebentar.","jp":"すこし やすみましょう。","reading":"Sukoshi yasumimashou."}]'::jsonb, '[Akar Verba] + masen ka / mashou', '{"quiz":[{"why":"Akhiran tanya negatif ～ませんか adalah cara paling sopan untuk mengajak.","answer":1,"options":["いっしょに たべますか","いっしょに たべませんか","いっしょに たべましたか","いっしょに たべません"],"question":"Mana bentuk ajakan paling sopan kepada rekan baru untuk makan bersama?"},{"why":"''ええ、いきましょう'' berarti ''Ya, ayo kita pergi!''.","answer":2,"options":["はい、いきません","いいえ、いきましょう","ええ、いきましょう！","いいえ、いきました"],"question":"Jika rekanmu mengajak ''こうえんへ いきませんか'', jawaban menerima yang pas adalah:"},{"why":"Pola ～ましょうか menandakan pembicara menawarkan diri membantu sesuatu.","answer":0,"options":["Menawarkan bantuan untuk membawakan","Menyuruh teman mengangkat barang","Menolak membawa barang","Menanyakan isi barang"],"question":"Apa nuansa kalimat ''にもつを もちましょうか'' saat melihat teman membawa dus berat?"}],"forms":[{"id":"maukah minum kopi?","jp":"コーヒーをのみませんか","label":"Ajakan Halus","reading":"koohii o nomimasen ka"},{"id":"ya, ayo kita minum!","jp":"ええ、のみましょう","label":"Menyetujui / Ayo","reading":"ee, nomimashou"},{"id":"boleh saya bantu?","jp":"てつだいましょうか","label":"Tawar Bantuan","reading":"tetsudaimashou ka"}],"steps":["Ambil kata kerja bentuk sopan lalu buang akhiran ます (misal: いきます → いき).","Tambahkan ～ませんか kalau ingin mengajak secara sopan tanpa memaksa.","Tambahkan ～ましょう kalau menjawab antusias (''Ayo!'') atau mengajak tim bekerja bersama."],"analogy":"～ませんか mirip ajakan halus ''Mau nggak kita...?'' (memberi ruang lawan bicara menjawab ya/tidak), sedangkan ～ましょう seperti ''Ayo kita...!'' atau ''Biar saya bantu ya!''.","mistakes":[{"why":"Di Jepang, menolak ajakan tidak langsung dijawab ''いえ、いきません'' (kasar); cukup bilang ''Maaf, hari ini agak... (chotto)''.","right":"すみません、きょうは ちょっと…","wrong":"いっしょに いきましょう！(menolak tapi bilang ini)"},{"why":"のみますか terdengar seperti sekadar menanyakan kebiasaan (''Apakah kamu minum kopi?''), sedangkan のみませんか bernada mengajak.","right":"コーヒーを のみませんか","wrong":"コーヒーを のみますか (saat berniat mengajak)"}],"breakdowns":[{"tokens":[{"jp":"いっしょに","role":"connector","meaning":"bersama-sama","reading":"issho ni"},{"jp":"かえりませんか","role":"verb","meaning":"maukah pulang?","reading":"kaerimasen ka"}],"translation":"Maukah pulang bersama-sama?"},{"tokens":[{"jp":"ちゅうしょく","role":"object","meaning":"makan siang","reading":"chuushoku"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"たべましょう","role":"verb","meaning":"ayo makan!","reading":"tabemashou"}],"translation":"Ayo makan siang!"},{"tokens":[{"jp":"あした","role":"time","meaning":"besok","reading":"ashita"},{"jp":"えき","role":"place","meaning":"stasiun","reading":"eki"},{"jp":"の","role":"particle","meaning":"(dari)","reading":"no"},{"jp":"まえ","role":"place","meaning":"depan","reading":"mae"},{"jp":"で","role":"particle","meaning":"di","reading":"de"},{"jp":"あいませんか","role":"verb","meaning":"maukah bertemu?","reading":"aimasen ka"}],"translation":"Maukah kita bertemu di depan stasiun besok?"}],"when_to_use":["Mengajak teman makan siang, minum kopi, atau jalan-jalan akhir pekan","Menyetujui ajakan teman dengan bersemangat","Menawarkan bantuan ringan kepada orang lain (pakai ～ましょうか)"],"formula_parts":[{"role":"verb","text":"Akar Verba","label":"Sama seperti bentuk ます"},{"role":"ending","text":"ませんか / ましょう","label":"Maukah...? / Ayo...!"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('2daba56c-c5f5-4d22-b973-6a40dcefc8e3', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-014', 'conjugation', 'Permintaan Sopan & Urutan Aksi (～てください)', '[Verba Bentuk-TE] + ください', 'Mengubah verba ke bentuk-TE lalu menambahkan ください menghasilkan instruksi atau permohonan sopan di lingkungan kerja.', 14, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Tolong tulis nama di sini.","jp":"ここに なまえを かいてください。","reading":"Koko ni namae o kaite kudasai."},{"id":"Mandi shower, lalu tidur.","jp":"シャワーを あびて、ねます。","reading":"Shawaa o abite, nemasu."}]'::jsonb, '[Verba Bentuk-TE] + kudasai', '{"quiz":[{"why":"Kata kerja Grup 1 berakhiran み sebelum ます (no-mi-masu) berubah menjadi んで → のんで.","answer":2,"options":["のみて ください","のいて ください","のんで ください","のって ください"],"question":"Ubah ''のみます'' (minum) menjadi bentuk permohonan ''Tolong minum'':"},{"why":"みます termasuk verba Grup 2 (satu suku kata vokal i), sehingga cukup buang ます dan tambah て → みて.","answer":0,"options":["みて ください","みって ください","みんで ください","みる ください"],"question":"Bagaimana cara benar untuk ''Tolong lihat foto ini'' (みます = grup 2)?"},{"why":"Bentuk-TE tanpa ください berfungsi sebagai kata sambung aksi berurutan (''makan dulu, lalu pergi'').","answer":1,"options":["Menyuruh orang makan","Menyambung dua aksi berurutan (''lalu'')","Menyatakan sedang makan","Menyangkal sudah makan"],"question":"Dalam kalimat ''あさ ごはんを たべて、がっこうへ いきます'', fungsi Bentuk-TE pada たべて adalah:"}],"forms":[{"id":"tolong tulis","jp":"かいてください","label":"Grup 1 (き→いて)","reading":"kaite kudasai"},{"id":"tolong baca","jp":"よんでください","label":"Grup 1 (み→んで)","reading":"yonde kudasai"},{"id":"tolong makan","jp":"たべてください","label":"Grup 2 (～て)","reading":"tabete kudasai"},{"id":"tolong pergi","jp":"いってください","label":"Pengecualian (行)","reading":"itte kudasai"}],"steps":["Ubah kata kerja ke Bentuk-TE: verba berakhiran i-chi-ri jadi って (kaimasu→かって), mi-bi-ni jadi んで (nomimasu→のんで), ki jadi いて (kakimasu→かいて), gi jadi いで, shi jadi して, grup 2 tinggal ganti ます jadi て (tabemasu→たべて).","Tambahkan ください setelah Bentuk-TE untuk membuat kalimat permohonan sopan (''Tolong...'').","Kalau mau menyambung dua kegiatan berurutan, cukup pakai Bentuk-TE di kalimat pertama tanpa ください."],"analogy":"Bentuk-TE + ください itu artinya ''Tolong ... ya''. Uniknya, Bentuk-TE (yang berakhiran -te atau -de) juga berfungsi sebagai lem penyambung untuk menggabungkan beberapa aksi berurutan (''... lalu ...'').","mistakes":[{"why":"Meski いきます punya huruf き, kata kerja ''pergi'' ini adalah pengecualian wajib menjadi いって (itte).","right":"いって ください","wrong":"いきます → いいて ください"},{"why":"おねがいします dipakai setelah kata benda (''Bantuannya ya''), sedangkan kata kerja memakai Bentuk-TE + ください.","right":"かいて ください","wrong":"おねがいします かきます"}],"breakdowns":[{"tokens":[{"jp":"ここ","role":"place","meaning":"di sini","reading":"koko"},{"jp":"に","role":"particle","meaning":"pada","reading":"ni"},{"jp":"なまえ","role":"object","meaning":"nama","reading":"namae"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"かいて","role":"verb","meaning":"tulis (TE)","reading":"kaite"},{"jp":"ください","role":"ending","meaning":"tolong","reading":"kudasai"}],"translation":"Tolong tulis nama Anda di sini."},{"tokens":[{"jp":"すみません","role":"connector","meaning":"permisi","reading":"sumimasen"},{"jp":"ゆっくり","role":"adjective","meaning":"pelan-pelan","reading":"yukkuri"},{"jp":"はなして","role":"verb","meaning":"berbicara (TE)","reading":"hanashite"},{"jp":"ください","role":"ending","meaning":"tolong","reading":"kudasai"}],"translation":"Permisi, tolong bicara pelan-pelan."},{"tokens":[{"jp":"あさ","role":"time","meaning":"pagi","reading":"asa"},{"jp":"おきて","role":"verb","meaning":"bangun lalu","reading":"okite"},{"jp":"シャワー","role":"object","meaning":"mandi","reading":"shawaa"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"あびて","role":"verb","meaning":"guyur lalu","reading":"abite"},{"jp":"うち","role":"place","meaning":"rumah","reading":"uchi"},{"jp":"を","role":"particle","meaning":"dari","reading":"o"},{"jp":"でます","role":"verb","meaning":"berangkat","reading":"demasu"}],"translation":"Pagi hari bangun, lalu mandi, kemudian berangkat dari rumah."}],"when_to_use":["Meminta bantuan orang lain secara sopan (tolong tulis, tolong baca, tolong tunggu sebentar)","Memberi petunjuk atau instruksi kerja atau arah jalan","Menceritakan rentetan kegiatan berurutan dari pagi sampai malam"],"formula_parts":[{"role":"verb","text":"Verba Bentuk-TE","label":"Bentuk sambung (-て / -で)"},{"role":"ending","text":"ください","label":"Tolong (sopan)"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('713b3950-cd77-436e-9e0e-d131b205008e', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-015', 'tense', 'Aksi Sedang Berlangsung & Status (～ています)', '[Verba Bentuk-TE] + います', 'Menyatakan kegiatan yang sedang dilakukan sekarang ("sedang ...") atau keadaan yang masih berlanjut seperti tempat tinggal & pekerjaan.', 15, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Sekarang sedang menulis email.","jp":"いま メールを かいています。","reading":"Ima meeru o kaite imasu."},{"id":"Saya tinggal di Tokyo.","jp":"わたしは トーキョーに すんでいます。","reading":"Watashi wa Toukyou ni sunde imasu."}]'::jsonb, '[Verba Bentuk-TE] + imasu', '{"quiz":[{"why":"Tinggal di suatu kota adalah status berkelanjutan, sehingga memakai すんでいます (dan lokasi tinggal memakai に).","answer":1,"options":["ジャカルタに すみます","ジャカルタに すんでいます","ジャカルタで すみます","ジャカルタを すんでいます"],"question":"Cara yang benar untuk berkata ''Saya sekarang tinggal di Jakarta'' adalah:"},{"why":"Pengecualian terkenal: bentuk negatif ''tahu'' adalah しりません.","answer":2,"options":["しっていません","しっています","しりません","しりています"],"question":"Jika teman bertanya tentang seseorang dan kamu TIDAK mengenalnya, jawabannya yang natural adalah:"},{"why":"Bentuk-TE (きいて) + います dengan penanda waktu いま menyatakan kegiatan sedang berlangsung.","answer":2,"options":["Tolong dengarkan musik sekarang","Saya sudah mendengarkan musik","Sekarang saya sedang mendengarkan musik","Saya ingin mendengarkan musik"],"question":"Kalimat ''いま おんがくを きいています'' artinya:"}],"forms":[{"id":"sedang belajar","jp":"べんきょうしています","label":"Sedang Aksi","reading":"benkyou shite imasu"},{"id":"tidak sedang belajar","jp":"べんきょうしていません","label":"Tidak Sedang","reading":"benkyou shite imasen"},{"id":"sudah menikah","jp":"けっこんしています","label":"Status Tetap","reading":"kekkon shite imasu"}],"steps":["Ubah kata kerja ke Bentuk-TE terlebih dulu (sama seperti pola ～てください).","Tambahkan います (atau versi singkat lisan ってます / てます saat ngobrol kasual, tapi di N5 pakai lengkap います).","Untuk negatif (''tidak sedang...''), ubah menjadi ～ていません."],"analogy":"～ています itu punya 2 arti praktis: seperti imbuhan ''sedang...'' (aksi yang masih berlangsung detik ini) ATAU menyatakan ''status tetap'' saat ini (tinggal di mana, bekerja di mana, sudah menikah).","mistakes":[{"why":"Kata kerja keadaan seperti tinggal (住む), mengenal (知る), dan menikah (結婚する) WAJIB memakai ～ています untuk menyatakan keadaan saat ini.","right":"おおさかに すんでいます","wrong":"おおさかに すみます (utk tinggal sekarang)"},{"why":"Pengecualian khusus: ''tahu'' = しっています, tapi ''tidak tahu'' selalu memakai しりません (bukan しっていません).","right":"しりません","wrong":"しっていません (bilang tidak tahu)"}],"breakdowns":[{"tokens":[{"jp":"いま","role":"time","meaning":"sekarang","reading":"ima"},{"jp":"あめ","role":"subject","meaning":"hujan","reading":"ame"},{"jp":"が","role":"particle","meaning":"(subjek)","reading":"ga"},{"jp":"ふっています","role":"verb","meaning":"sedang turun","reading":"futte imasu"}],"translation":"Sekarang sedang turun hujan."},{"tokens":[{"jp":"わたし","role":"topic","meaning":"saya","reading":"watashi"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"おおさか","role":"place","meaning":"Osaka","reading":"Oosaka"},{"jp":"に","role":"particle","meaning":"di","reading":"ni"},{"jp":"すんでいます","role":"verb","meaning":"tinggal (status)","reading":"sunde imasu"}],"translation":"Saya tinggal di Osaka."},{"tokens":[{"jp":"たなかさん","role":"topic","meaning":"Tuan Tanaka","reading":"Tanaka-san"},{"jp":"は","role":"particle","meaning":"(topik)","reading":"wa"},{"jp":"かいぎしつ","role":"place","meaning":"ruang rapat","reading":"kaigishitsu"},{"jp":"で","role":"particle","meaning":"di","reading":"de"},{"jp":"パソコン","role":"object","meaning":"laptop","reading":"pasokon"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"つかっています","role":"verb","meaning":"sedang memakai","reading":"tsukatte imasu"}],"translation":"Tuan Tanaka sedang memakai laptop di ruang rapat."}],"when_to_use":["Menjelaskan aktivitas yang sedang terjadi sekarang (''sedang makan'', ''hujan sedang turun'')","Menyebutkan kota tempat tinggal, tempat kerja, atau status menikah","Menyebutkan hal yang biasa dilakukan berulang-ulang dalam keseharian"],"formula_parts":[{"role":"verb","text":"Verba Bentuk-TE","label":"Aksi (-て / -で)"},{"role":"ending","text":"います","label":"Sedang / Berstatus"}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO grammar_points ("id", "level_id", "code", "category", "title", "formula", "explanation", "order_index", "created_at", "examples", "formula_reading", "learning_guide") VALUES ('de0cdbef-121a-454b-8f8c-5a4484f858d0', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'GP-JA-N5-016', 'sentence_pattern', 'Keinginan & Tujuan Tindakan (～たいです・～にいきます)', '[Akar Verba] + たいです / [Tempat] へ [Akar Verba] に いきます', 'Ganti akhiran ～ます dengan ～たいです untuk menyatakan keinginan pribadi, dan pakai partikel に setelah akar verba sebelum いきます/きます untuk menyatakan tujuan.', 16, '2026-11-18T11:46:30.450543+00:00', '[{"id":"Tahun depan saya ingin bekerja di Jepang.","jp":"らいねん 日本で はたらきたいです。","reading":"Rainen Nihon de hatarakitai desu."},{"id":"Pergi ke supermarket untuk berbelanja.","jp":"スーパーへ かいものに いきます。","reading":"Suupaa e kaimono ni ikimasu."}]'::jsonb, '[Akar Verba] + tai desu / [Tempat] e [Akar Verba] ni ikimasu', '{"quiz":[{"why":"Pola ～たい berubah layaknya adjektiva-i menjadi ～たくないです.","answer":2,"options":["コーヒーを のみません たい","コーヒーを のみたい ではありません","コーヒーを のみたくないです","コーヒーを のみませんでした"],"question":"Bagaimana mengatakan ''Saya tidak ingin minum kopi sekarang''?"},{"why":"Tujuan kepergian memakai akar kata kerja (tanpa ます) + に + いきます → かりに.","answer":0,"options":["かりに","かりて","かりたい","かるに"],"question":"Lengkapi: ''としょかんへ ほんを ___ いきます'' (Pergi ke perpustakaan untuk meminjam buku; meminjam = かります)."},{"why":"かいます dibuang ます menjadi かい, lalu ditambah たいです → かいたいです.","answer":1,"options":["くるまを かってです","くるまを かいたいです","くるまを かいに たいです","くるまを かいません"],"question":"Kalau kamu sedang berangan-angan ingin membeli mobil (かう = membeli), bagaimana bentuk yang tepat?"}],"forms":[{"id":"ingin pergi","jp":"いきたいです","label":"Ingin (+)","reading":"ikitai desu"},{"id":"tidak ingin pergi","jp":"いきたくないです","label":"Tidak Ingin (-)","reading":"ikitakunai desu"},{"id":"kemarin ingin pergi","jp":"いきたかったです","label":"Dulu Ingin","reading":"ikitakatta desu"},{"id":"pergi untuk melihat","jp":"みに いきます","label":"Tujuan Aksi","reading":"mi ni ikimasu"}],"steps":["Untuk bilang ''ingin'': buang ます dari kata kerja, lalu tempelkan ～たいです (tabe-masu → tabe-tai desu).","Uniknya, pola ～たい ini berubah layaknya Kata Sifat-I! Jadi ''tidak ingin'' adalah ～たくないです.","Untuk bilang ''pergi ke X untuk melakukan Y'': [X] へ [Akar kata kerja / Kata benda aksi] に いきます."],"analogy":"～たいです artinya ''Saya ingin...''. Sementara pola [Tempat] へ [Verba-akar] に いきます artinya ''Pergi ke tempat tertentu UNTUK melakukan suatu kegiatan''.","mistakes":[{"why":"Bentuk ～たい ikut aturan Kata Sifat-I, jadi bentuk negatifnya adalah ～たくないです (bukan ません).","right":"にほんへ いきたくないです","wrong":"にほんへ いきたいません"},{"why":"ます wajib dibuang terlebih dulu sebelum menempelkan たい.","right":"コーヒーが / を のみたいです","wrong":"コーヒーを みます たい (pakai ます)"}],"breakdowns":[{"tokens":[{"jp":"すし","role":"object","meaning":"sushi","reading":"sushi"},{"jp":"が","role":"particle","meaning":"(objek ingin)","reading":"ga"},{"jp":"たべたいです","role":"verb","meaning":"ingin makan","reading":"tabetai desu"}],"translation":"Saya ingin makan sushi."},{"tokens":[{"jp":"スーパー","role":"place","meaning":"supermarket","reading":"suupaa"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"かいもの","role":"noun","meaning":"belanja","reading":"kaimono"},{"jp":"に","role":"particle","meaning":"untuk","reading":"ni"},{"jp":"いきます","role":"verb","meaning":"pergi","reading":"ikimasu"}],"translation":"Pergi ke supermarket untuk berbelanja."},{"tokens":[{"jp":"きょうと","role":"place","meaning":"Kyoto","reading":"Kyouto"},{"jp":"へ","role":"particle","meaning":"ke","reading":"e"},{"jp":"さくら","role":"object","meaning":"bunga sakura","reading":"sakura"},{"jp":"を","role":"particle","meaning":"(objek)","reading":"o"},{"jp":"み","role":"verb","meaning":"melihat","reading":"mi"},{"jp":"に","role":"particle","meaning":"untuk","reading":"ni"},{"jp":"いきました","role":"verb","meaning":"telah pergi","reading":"ikimashita"}],"translation":"Saya pergi ke Kyoto untuk melihat bunga sakura."}],"when_to_use":["Mengungkapkan keinginan pribadi (ingin makan sushi, ingin pergi ke Jepang)","Menjelaskan tujuan kepergian ke suatu tempat (pergi ke mall untuk belanja, pergi ke resto untuk makan)","Memesan atau merencanakan aktivitas bersama teman"],"formula_parts":[{"role":"verb","text":"Akar Verba","label":"Bentuk masu tanpa ます"},{"role":"ending","text":"たいです","label":"Ingin ... (sifat-i)"},{"role":"connector","text":"/ へ [Verba] に いきます","label":"Pergi ke ... untuk ..."}]}'::jsonb) ON CONFLICT DO NOTHING;
